WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[49744] = { title = "Bombs, Away", description = "By the sea's foamy beard, what a blast!\n\nThey've brought goblins, and if there's one thing I know about goblins it's that they like to blow things up.\n\nI saw a few of them carrying large bombs, and I presume that they are going to blow up the town. I would like to keep the town, so how about you head out there and steal as many of those explosives as you can find? After that, let's blow up their demolishers and stop this infernal bombardment!", objectives = "Retrieve 8 Horde Explosives and use them against the Demolishers.", progress = "Don't forget to check inside the buildings too!", completion = "These look particularly nasty. I'm glad they aren't blowing up in our faces." }
WordHunterWoW_QuestEN[49745] = { title = "You Have Their Orders", description = "The Horde is an army, make no mistake. And armies need orders.\n\nSomeone must be giving orders here. They know the plan, and I want to know the plan too.\n\nLook for the people who seem to be in charge and see if you can uncover any intelligence so we know what to do next.", objectives = "Find the Warchief's Orders.", progress = "You find those orders?", completion = "The Banshee Queen is not like the previous Warchiefs." }
WordHunterWoW_QuestEN[49746] = { title = "Dousing the Flames", description = "The Horde have set fire to my town, {class}. I will make them pay for this.\n\nStormsong Valley is the breadbasket of Kul Tiras, and our people need to be fed. The first thing we must do is damage control.\n\nGrab some buckets and help put those fires out!", objectives = "Use the Water Bucket to put out 15 fires around the Ruins of Brennadam.", completion = "Bombs, fire, Horde. Our town will endure it all." }
WordHunterWoW_QuestEN[49753] = { title = "Contruct Armory", description = "", objectives = "" }
WordHunterWoW_QuestEN[49754] = { title = "Not \"Only Zul\"", description = "Our enemies here either follow de name of Zul, or dey want to use him to take Zandalar.\n\nHe has the ego to allow either. \n\nDey claim only Zul can lead us.\n\nDissuade dem.", objectives = "Purge Zul's forces.", progress = "Did ya leave any breathing?", completion = "Well done, <name>. I wish that put a bigger dent in the threat they pose." }
WordHunterWoW_QuestEN[49755] = { title = "Heavy Artillery", description = "Bad news, friend. They're bringing in serious firepower now.\n\nWe've spotted a tank on the northern hill by the windmill. They can reach the other side of the town from there. We can't let them set it up.\n\nWhat do you say to giving them a taste of their own medicine? If you can take out their commander, you'd have a fancy new tank all to yourself. Imagine the mayhem you could unleash on their invasion!", objectives = "Slay Captain Wormwood and commandeer the Experimental War Machine.", progress = "If that cannon can reach Brennadam, it can reach those zeppelins!", completion = "Those were some explosions! I'm just glad they were directed at the Horde and not us." }
WordHunterWoW_QuestEN[49756] = { title = "Dark Forces", description = "The Old Gods have inflicted one of their faceless ones upon Thunder Bluff. The fiend desecrates my people's city!\n\nWe must fight together to rid this place of such filth.\n\nI believe that destroying this herald will drive our enemies from Mulgore. May our weapons strike true, {name}!", objectives = "Defeat Qy'telek, Herald of Uul'gyneth", progress = "This herald of the Old Gods must be stopped.", completion = "A fine kill, <name>. My people can clean up from here." }
WordHunterWoW_QuestEN[49757] = { title = "Cat on a Hot Copper Roof", description = "My parents said we have to go, but I won't leave Scratchy behind!\n\nShe's so gentle and precious and pure and kind and soft and cuddly! She must be so scared up there on the balcony!\n\nPlease help her!", objectives = "Climb the burning house and rescue Scratchy.", progress = "We can't leave Scratchy here!", completion = "Yay!\n\nIsn't she the sweetest most perfectest kitty cat ever?!" }
WordHunterWoW_QuestEN[49758] = { title = "Send the Signal!", description = "My crew is not on board with de word of Zul. We saw too much of who he really is. \n\nFar out in de harbor, Zul's traitors have joined with de mogu to try to take my ships! If we lose de fleet and de harbor, we lose de city!\n\nWe must let Zuldazar know we stand strong. We take back de ships. We drive de villains out. \n\nYou must light de towers with loa-blessed flame. Dey will always see dat de Bay of Kings belongs to Zandalar!", objectives = "Get to the ship.", completion = "Ya got here just in time!" }
WordHunterWoW_QuestEN[49759] = { title = "Contruct Workshop", description = "", objectives = "" }
WordHunterWoW_QuestEN[49766] = { title = "Your Next Move", description = "We have some thoughts on the best way to win over the Zandalari.\n\nThe princess is heading to Nazmir to take the fight to the blood trolls. Her voice carries much weight with the council and her father.\n\nGeneral Jakra'zet detests the Horde. Removing his voice from the Zanchuli Council will greatly improve our chances here.\n\nWe should also keep working on winning over the King here in Zuldazar. This city is vast and has many secrets.", objectives = "Choose your next move in Zandalar.We have some thoughts on the best way to win over the Zandalari.\n\nThe princess is heading to Nazmir to take the fight to the blood trolls. Her voice carries much weight with the council and her father.\n\nGeneral Jakra'zet detests the Horde. Removing his voice from the Zanchuli Council will greatly improve our chances here.\n\nWe should also keep working on winning over the King here in Zuldazar. This city is vast and has many secrets." }
WordHunterWoW_QuestEN[49767] = { title = "Your Next Move", description = "We have some thoughts on the best way to win over the Zandalari.\n\nThe princess is heading to Nazmir to take the fight to the blood trolls. Her voice carries much weight with the council and her father.\n\nGeneral Jakra'zet detests the Horde. Removing his voice from the Zanchuli Council will greatly improve our chances here.\n\nWe should also keep working on winning over the King here in Zuldazar. This city is vast and has many secrets.", objectives = "Choose your next move in Zandalar.We have some thoughts on the best way to win over the Zandalari.\n\nThe princess is heading to Nazmir to take the fight to the blood trolls. Her voice carries much weight with the council and her father.\n\nGeneral Jakra'zet detests the Horde. Removing his voice from the Zanchuli Council will greatly improve our chances here.\n\nWe should also keep working on winning over the King here in Zuldazar. This city is vast and has many secrets.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[49768] = { title = "Nesingwary's Trek", description = "De greatest hunter from your lands, de dwarf Nesingwary, has come to participate in de Great Hunt.\n\nIf you are enough of a hunter to join him, den travel to de Nesingwary Trek along de northeastern region of Zuldazar.", objectives = "Speak with Hemet Nesingwary at Nesingwary's Trek.", completion = "Welcome to tha hunt." }
WordHunterWoW_QuestEN[49769] = { title = "Wreckage of the Cataclysm", description = "In recent years one of the greatest Zandalari loa temples mysteriously fell into the sea. It is a topic of some debate what caused this, and what treasures might have been lost in the catastrophe.\n\nMy cousin Rokor was in charge of the salvaging efforts. Within the temple were many great items of knowledge and power. I am sure he will have need of the services of someone like yourself with strong arms and working knees.", objectives = "Find Rokor at Scavenger's Strand.In recent years one of the greatest Zandalari loa temples mysteriously fell into the sea. It is a topic of some debate what caused this, and what treasures might have been lost in the catastrophe.\n\nMy cousin Rokor was in charge of the salvaging efforts. Within the temple were many great items of knowledge and power. I am sure he will have need of the services of someone like yourself with strong arms and working knees.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[49772] = { title = "For the Alliance", description = "The Army of the Light was founded with one purpose: to defeat the Legion. Though we have achieved that goal, a new duty lies before us.\n\nAzeroth is a world beset by enemies. Use your training to battle the darkness and uphold the ideals of the Alliance.\n\nGo to Stormwind. Seek the king's ambassador at the embassy, then set out to spread the Light's justice across the land.\n\nPheta thones gamera, {name}.", objectives = "Meet Ambassador Moorgard at the Stormwind Embassy.", completion = "What have we here? One of the famed Lightforged draenei! Welcome, welcome.\n\nThank you for your service against the Legion, <name>. Truly an inspiration!" }
WordHunterWoW_QuestEN[49773] = { title = "For the Horde", description = "A new age dawns upon Highmountain, {name}.\n\nAfter centuries apart, the bond with our kin from Kalimdor has been reforged. And in the fight to save our land, we found new friends among the people of the Horde.\n\nTo show the strength we bring to our allies, brave tauren like you must heed the call of adventure.\n\nYou have been invited to Orgrimmar. Meet with the ambassador at the warchief's embassy, then begin your journey across Azeroth.\n\nEarthmother be with you, {name}.", objectives = "Meet Ambassador Blackguard at the Orgrimmar Embassy.", completion = "Are you the new one? I'm supposed to welcome you. Here, take this letter.\n\n<Blackguard lets out an exasperated sigh.>" }
WordHunterWoW_QuestEN[49774] = { title = "Won't Leaf Him to Die", description = "I may have done some wicked things in my past, but I won't leave dis guard to die.\n\nZulajin has taken a nasty bite outta Zaluto... and has also infected him with some weird voodoo.\n\nBut don't worry, because today is our lucky day. I have a plan to cure him. Dere are sweetleaf bushes nearby!\n\nDe leaves of dis bush are known for their healing properties. You get me some, and I will be able to save dis Zaluto.\n\nIt's de only chance we have!", objectives = "Gather 8 Sweetleaf.", progress = "Did you get de sweetleaf?", completion = "You have de sweetleaf! Looks like you gathered just enough, too!" }
WordHunterWoW_QuestEN[49775] = { title = "Key to the Brig", description = "You can tell a lot about a troll by what they do when they learn who Zul truly is. \n\nThat Garza is a mutinous, foul-tusked, ship stealin' traitor. She is the kind of zealot dat will follow de heretic into the maw of an Old God. \n\nI am more de type to rip out her tusks and beat her with dem. \n\nI'd settle for ya taking her key and getting our wavemaster and crew free!", objectives = "Get the key from Quartermaster Garza.", progress = "Did ya relieve her of de key?", completion = "Garza was lost long ago. It sounds that Maset is as feisty as ever. We will get out to de ships!" }
WordHunterWoW_QuestEN[49776] = { title = "No Problem Tar Can't Solve", description = "I'm not going to lie... I did wicked things in my youth and I've been living with de shame ever since.\n\nBut Zaluto is going to die without my healing, and we're all going to die if dat dino isn't taken care of.\n\nDere is a lot of tar in dis area. I need it to cure Zaluto of whatever is infecting him here.\n\nGet me dat tar, and I'll be able to save Zaluto from dis fate.", objectives = "Collect 6 Sticky Tar.", progress = "We will need plenty of dat sticky tar!", completion = "Good job! Dis is exactly de kind of stuff we need!" }
WordHunterWoW_QuestEN[49777] = { title = "On The Run", description = "<The guard captain appears to be fatally wounded.>\n\nWe were... transporting prisoners when de ambush came... a giant devilsaur... tore through everything.\n\nMost of de prisoners escaped in de carnage... dese are hardened criminals. Dey cannot be allowed to roam free!\n\nI swore a blood oath dat I would deliver dem to Vol'dun... I am probably going to die here, but I will not die an oathbreaker!\n\nFind de escaped criminals and exile dem to Vol'dun.", objectives = "Exile the escaped prisoners.", progress = "Have you found de escaped prisoners?", completion = "You have my thanks... if I die here, at least I can face my ancestors with my oath fulfilled." }
WordHunterWoW_QuestEN[49778] = { title = "Don't Go into the Light", description = "Okay, dis is de moment of truth! We will see if my voodoo can cure Zaluto.\n\nI should have been honest with you... dere is a chance dis won't work. Voodoo isn't a science, you know.\n\nI need you to hold Zaluto down, because dis here is going to hurt. A lot.", objectives = "Hold Zaluto down while Jin'Tiki cures him.", progress = "We can't leave Zaluto to die.", completion = "Zaluto is free from death's door, but he's still weak. We have more to do." }
WordHunterWoW_QuestEN[49779] = { title = "Bad To The Bone", description = "I will not leave here without killing Zulajin, or else it will just go after de next caravan dat comes through.\n\nI have a plan, but we must work together to pull it off.\n\nDere are skeletal raptors roaming in de area. I do not know what voodoo brought dem here, but we need dem gone.\n\nWe are going to need as much space as possible for my plan to kill Zulajin.", objectives = "Slay 10 Bone Raptors.", progress = "Did you take care of de skeletal raptors yet?", completion = "You have done well taking care of de bone raptors. Even if dis road is only for criminals, dey at least deserve to make it to Vol'dun alive." }
WordHunterWoW_QuestEN[49780] = { title = "Recovering Ancient Fire", description = "Zaluto has a crazy plan to kill Zulajin. Never thought a guard could come up with something so clever.\n\nDere is ancient mojo throughout dis place... who knows what it used to be? But I sense something I can use.\n\nDe statues sinking in de tar pits have de fire mojo still burning in dem. We will need it to kill Zulajin.\n\nTake my fetish and use it to absorb what's left of de fire in dese statues.\n\nJust don't get dat fire too close to de tar!", objectives = "Absorb fire mojo from 4 Nazmani statues.", progress = "Do you have de fire yet?", completion = "De fetish is brimming with de fire magic! Good, because you will need it for what comes next." }
WordHunterWoW_QuestEN[49781] = { title = "Catch Me if You Can", description = "Alright, de time has come for you to face Zulajin yourself!\n\nJin'Tiki's fetish has de power of some ancient fire in it now. You will ride my raptor here to lure Zulajin into de tar pits.\n\nAfter dat... you will use de fetish to light de tar pits on fire! Dat should be enough to kill Zulajin.\n\n...and if not, well, den you will have to improvise. Good luck!", objectives = "Ride Zulato's raptor to lure Zulajin into the tar pits and set it on fire.", completion = "I knew you'd take care of Zulajin, no problem! I guess it is time for me to say goodbye to de jungle once and for all..." }
WordHunterWoW_QuestEN[49782] = { title = "Heritage of the Lightforged", description = "Your service to the Alliance has been most impressive, {name}. I could not have done better myself. Well, I could... but not by much.\n\nCome, meet with me at the Vindicaar. It is time that we reward your diligence.", objectives = "Meet Captain Fareeya aboard the Vindicaar.", progress = "Welcome aboard, <name>.", completion = "Duty. Honor. Sacrifice. The Lightforged strive to embody these qualities. You have done so with aplomb.\n\nIt is my pleasure to award you with a symbol of your service, <name>." }
WordHunterWoW_QuestEN[49783] = { title = "Heritage of Highmountain", description = "Your sojourn through Azeroth has been long, {name}. And through it all, you have brought honor to Highmountain.\n\nNow Thunder Totem calls you home. It is time we thank you for all that you have done for us.", objectives = "Meet Mayla Highmountain in Thunder Totem.", completion = "You have brought great honor to our tribes, <name>. It is fitting that we give you a symbol of our thanks.\n\nHighmountain stands... because you have the courage to fight for it." }
WordHunterWoW_QuestEN[49784] = { title = "Heritage of the Nightborne", description = "You are among the first shal'dorei to venture forth and explore the wilds of Azeroth. But now it is time to come home.\n\nReturn to Suramar so that we may thank you for helping our people reclaim a place in this world.", objectives = "Meet First Arcanist Thalyssra at the Nighthold.", completion = "When we were liberated from the Legion, some among the shal'dorei believed we should remain isolated. Alone.\n\nYour accomplishments in Azeroth have shown that we made the right decision in reclaiming our place in this world. It pleases me to honor you with this symbol of Suramar's gratitude." }
WordHunterWoW_QuestEN[49785] = { title = "Destroy the Weapon", description = "I did scout de next island. Rezan's Claw has a mighty weapon on board.\n\nI don't know what it is, but dey are confident in its ability to break de defenses of our home.\n\nGet to de ship. Destroy that weapon before dey can use it on Zuldazar!", objectives = "Investigate the weapon.", completion = "Dat was unexpected." }
WordHunterWoW_QuestEN[49787] = { title = "The Ghostlands", description = "Are you familiar with how the Void elves joined the Alliance? \n\nIt began with Alleria Windrunner finding out about a blood elf named Umbric. \n\nHe and his followers were banished from Silvermoon City for researching void magic.\n\nAlleria believed she could convince Umbric and his followers to join the Alliance and prevent the void from corrupting them.\n\nIt all began when she opened up a portal to go into the Ghostlands...", objectives = "Locate Umbric's home in the Ghostlands.", progress = "These lands bring back memories. Some good, some bad.", completion = "Umbric's methods are a bit cavalier, but he seems competent. We must get to him before things become too dangerous." }
WordHunterWoW_QuestEN[49788] = { title = "For the Alliance", description = "Mastering the whispers requires constant focus and discipline. Your dedication inspires all who bear the name ren'dorei--for we have become children of the Void.\n\nYou have learned many lessons here, but the time has come to venture beyond Telogrus Rift.\n\nGo to Stormwind, the heart of the Alliance. There, the king's ambassador will greet you and guide you along your journey.\n\nAzeroth must be defended. I can think of no one better suited to answer that call than you, {name}.", objectives = "Meet Ambassador Moorgard at the Stormwind Embassy.", completion = "Ah, there you are, <name>! We've been inspecting--err--expecting you!" }
WordHunterWoW_QuestEN[49789] = { title = "The Pledge", description = "The ethereals were lying in wait, anticipating someone strong enough in the void to be corrupted by the influence of the Old Gods.\n\nWe arrived in time to save them, and I will help teach them how to resist the whispers.\n\nUmbric is ready to join the Alliance. Let us return to Stormwind and inform King Wrynn.", objectives = "Return to Stormwind and speak with Anduin.The ethereals were lying in wait, anticipating someone strong enough in the void to be corrupted by the influence of the Old Gods.\n\nWe arrived in time to save them, and I will help teach them how to resist the whispers.\n\nUmbric is ready to join the Alliance. Let us return to Stormwind and inform King Wrynn." }
WordHunterWoW_QuestEN[49791] = { title = "Lost, Not Forgotten", description = "I know not what madness has overtaken my people, but we must stop it together.\n\nTake this bell. It calls the souls of the recently deceased to it for later release. We Stormsong do not bury our dead in the earth. The tides claim all.\n\nIf they will not answer to reason, then we must give them eternal peace. Fallen or not, they are Stormsong.", objectives = "Recover 12 souls using the Dead Ringer.", progress = "It is a grim task, but it is our burden to bear.", completion = "It is done. We will release them somewhere a bit more peaceful." }
WordHunterWoW_QuestEN[49792] = { title = "Bound and Oppressed", description = "We had our orders: ships, and lots of 'em. I led my boys as best I could.\n\nEverything changed when the tidesages showed up. We figured they was just checkin' on our progress, but the hood-wearin' bastards turned on us!\n\nThese anchors bind us here, forcin' us to work to death. No one deserves a fate like that. You gotta free my boys!", objectives = "Destroy 8 Anchors of Binding.", completion = "I owe you one, stranger!" }
WordHunterWoW_QuestEN[49793] = { title = "Means to an End", description = "In our haste to journey here I did not think to bring my ritual implements we tidesages use to augment our power.\n\nTo be honest, I had never expected them necessary on what should have been a peaceful sojourn.\n\nAddington does not have his, either. I am sure the militia took him from his home before he had the chance to react.\n\nThat means his implements should still be in the yard somewhere. We must find them before my power is of much real use.", objectives = "Retrieve Brother Addington's Tidal Kris, Abyssal Beacon, and Wavecaller's Mantle.", progress = "We must find a full set of ritual implements. I fear we will have need of them.", completion = "Those initiates were nowhere near ready to wield our sacred implements. They are far better served in our hands." }
WordHunterWoW_QuestEN[49794] = { title = "The Rising Tide", description = "This mainspring wasn't altered by an engineer. These runes on the surface can only have come from a tidesage.\n\nTheir aquatic magic is unmistakable. I'd bet whoever did this is also responsible for Addington's death.\n\nWhoever they are, they're likely still nearby. Keep an eye out... they won't be hard to find.", objectives = "Seek revenge on Sister Ava.", completion = "This does not bode well." }
WordHunterWoW_QuestEN[49800] = { title = "Atal'Dazar: Spiders!", description = "", objectives = "" }
WordHunterWoW_QuestEN[49801] = { title = "Aggressive Mating Strategy", description = "Aggression is good. I agree with Jangalar that Ben'jin needs to be a lot less passive to succeed and I can prove science is the way to do it by making an injection for him.\n\nAlchemy tells us that, for this type of beast, aggression comes from a substance in their bile sacs. The local razorwings are invasive and, as such, have more than enough aggression for our purposes. \n\nHarvest some of their bile sacs and I'll make a treatment that will have our big boy ready to go again in no time.", objectives = "Harvest 8 Bile Sacs from Invasive Razorwings.", progress = "Did you get all of the bile sacs I need yet? Science is not supposed to be safe...", completion = "Just what I needed! Boy do they smell! \n\nWith these bile sacs, I can make enough Aggression Formula for a creature as big as a brutosaur." }
WordHunterWoW_QuestEN[49803] = { title = "Changing of the Guard", description = "I have no doubt that you're a quite capable {class}, mainlander, but we will need some help if we want to make it to Waycrest Manor in one piece.  A small group would be ideal; strong enough to face the coven's threats, but small enough to remain largely unnoticed.\n\n<Reade produces a bundle of letters.>\n\nI have written new orders to some of my finest soldiers to join your Order of Embers. They will report to you and the lady Waycrest. Please deliver these to them, so they can be prepared to move out.", objectives = "Deliver recruitment orders to Captain Cleardawn, Ensign Yorrick, Ensign Mace, Lieutenant Sterntide, and Falconer Notley in Arom's Stand.", progress = "You will need to gather your recruits before we venture forth.", completion = "It is with reluctance that I hand command of these men over to you, but it must be done.\n\nI hope you lead them well." }
WordHunterWoW_QuestEN[49804] = { title = "Sharp Thinking", description = "I have reason to believe that the coven has already infiltrated Arom's Stand. There are many unfamiliar faces here, with the refugees from Corlain, and we know they can use their magic to appear like one of us.\n\nThis needle is fashioned of solid silver. If the witches are indeed vulnerable to silver, then a prick from this may be enough to break their spell. \n\nThe refugees may not be keen on being prodded, but they must understand that this is for the good of the town... and perhaps all of Drustvar.", objectives = "Use Lucille's Sewing Needle on 10 Corlain Refugees to reveal the hidden witches in Arom's Stand.", progress = "I really hope this works...", completion = "It worked?! I knew we were on the right track!\n\nIt's too bad we don't have a stockpile of silver weapons lying around, but I think I know how we can deal with that." }
WordHunterWoW_QuestEN[49805] = { title = "Implements of Ill Intent", description = "<It looks like some careless witch made a poor attempt to hide this grimoire from sight. No good could come of leaving the possessions of the coven for a hapless villager to find.\n\nIt would probably be a good idea to destroy any trappings of the coven that you find in Arom's Stand.>", objectives = "Destroy 12 Heartsbane objects in Arom's Stand.", completion = "That was good thinking to dispose of the witches' trappings. \n\nI don't want to know what would happen if an innocent villager toyed around with such things!" }
WordHunterWoW_QuestEN[49806] = { title = "Hidden Dealings", description = "<Among her possessions, the witch carried a crudely drawn map of Arom's Stand. \n\nA symbol marks what looks like the entrance to a cellar beneath one of the buildings.\n\nIf this location is important to the coven, it might be worth scouting out.>", objectives = "Explore the location marked on the Crude Map.", progress = "What's this? A map?", completion = "You found their leader? Excellent work, <class>!\n\nThe people of Arom's Stand will be safe, now that you've so thoroughly dismantled the coven's machinations here." }
WordHunterWoW_QuestEN[49807] = { title = "A New Order", description = "Before we leave, I have one more task to ask of you.\n\nWhile you were busy recruiting our inquisitors and driving the coven away from Arom's Stand, I took the liberty of placing an order with the local tailor. \n\nUsing some of the sketches within the tome, I had him put together some uniforms reminiscent of those worn by the ancient order.\n\nSince you will be leading our inquisitors, I think it's only fitting that you present them with their new regalia.", objectives = "Give the Inquisitors Regalia to the recruits in Arom's Stand.", progress = "You should be inducting them, not me!", completion = "There, that was nice and official. \n\nNow, I think it's time we took the fight back to the Heartsbane. I believe the marshal has a plan." }
WordHunterWoW_QuestEN[49809] = { title = "Atal'Dazar: From the Shadows", description = "", objectives = "" }
WordHunterWoW_QuestEN[49810] = { title = "Monstrous Matchmaker", description = "We have a problem, a matter of love, and you've come just in time. \n\nTwo white brutosaurs, de male Ben'jin and de female Maka'fon, are de last of their kind. De rest have passed on. \n\nDese two are not in de mood for love. If you can help my new friend Cala and myself, dis may be de only chance to give dem a future. \n\nPlace my voodoo totem close to each one so dat I can feel what dey feel and learn how we can help.", objectives = "Place Witch Doctor Jangalar's Voodoo Totem near both brutosaurs.", progress = "Place de voodoo totem close to both of de brutosaurs and I will be able to sense what dey feel.", completion = "We need to help Ben'jin to get his mojo back and Maka'fon to be in de mood. Is voodoo or science de better way to go?" }
WordHunterWoW_QuestEN[49812] = { title = "Delas in Dalaran", description = "Delas Moonfang needs our help. In-turn, she will aid us to decrypt the Codex of Command.\n\nI implore you to seek her out as soon as possible. She is known to enjoy the memorial dedicated to the fallen, great leader of the Kirin Tor, Antonidas.", objectives = "Find Delas Moonfang at the Antonidas Memorial in Dalaran.", completion = "Goddess be praised that you are here, <name>. I'm hoping that you can aid me." }
WordHunterWoW_QuestEN[49813] = { title = "Adventure Calls", description = "Tales of your heroism have spread to the ends of Azeroth... and beyond. Your skills have been requested elsewhere.\n\nWill you travel through the Dark Portal, fighting the Burning Legion on the sundered world of Outland?\n\nOr will you fly north, joining the battle against the Lich King in Northrend?\n\nThe choice is yours, adventurer.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Special Duty Assignments to select your next adventuring destination." }
WordHunterWoW_QuestEN[49814] = { title = "The Scent for a Brutosaur", description = "Mood is everything for love, and Maka'fon is not in de mood. \n\nVoodoo incense, specially formulated for brutosaurs by an expert witch doctor like myself, will surely spark de fire of de mother spirit in her heart. \n\nCertain fragrant rushes work best, and de jungle will provide. \n\nZandalari rushes grow near de waters here. Get a good amount for me and I will make an incense bundle big enough to set de mood.", objectives = "Find 7 Fragrant Rushes to make incense for Irritable Maka'fon.", progress = "Look for de rushes near de life-giving waters dat I might use my voodoo to make incense for de brutosaurs.", completion = "Well done! I will weave dese rushes into incense bundles and cast my best spells upon dem." }
WordHunterWoW_QuestEN[49816] = { title = "Burning Crusade: To Outland!", description = "The Burning Legion - an uncountably vast army of demons - has assaulted Outland, the tattered homeworld of the orcs. Adventurers of the Horde are needed to protect what remains of Outland from utter annihilation at the hands of this demonic invasion.\n\nTravel to the Blasted Lands, and pass through the Dark Portal.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Go through the Dark Portal in Blasted Lands.\n\nThe Thrallmar Mage in the Orgrimmar Portal Room can help you get there." }
WordHunterWoW_QuestEN[49817] = { title = "To Northrend!", description = "The Lich King stirs in the north.\n\nAn undead army follows his command, marching across Northrend and spreading blight wherever they tread.\n\nWe need you to stop them, <name>.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Take a zeppelin to Northrend.\n\nYou can board the Howling Fjord zeppelin in Tirisfal Glades, or the Borean Tundra zeppelin in Orgrimmar." }
WordHunterWoW_QuestEN[49818] = { title = "Trouble at Fort Daelin", description = "I was sent to Brennadam by my commanding officer to find a tidesage to help us at Fort Daelin to the west. The naga have started another attack on the bastion, and it's larger than any we have seen. \n\nLieutenant Bauer is in the middle of helping out civilians at the village near the fort, and she could use any help possible.", objectives = "Report to Lieutenant Bauer at Seabreeze Village.", completion = "These fishermen are no pushovers themselves. They should be able to hold their own here with a little help." }
WordHunterWoW_QuestEN[49831] = { title = "From the Depths", description = "We must prepare for an attack.\n\nMan the cannons!\n\nDefend the levee at all costs!", objectives = "Defend the levee from the Azshara's assault.", completion = "We've done it! The naga are defeated and the levee remains intact!" }
WordHunterWoW_QuestEN[49832] = { title = "An Illegible Scroll", description = "<Resting within the waterproof container is an illegible scroll of undetermined age and origin. \n\nPerhaps the tortollans along the coast will be able to decipher what is written upon the parchment?>", objectives = "Take the scroll to the tortollans along the Windswept Coast.", completion = "What have you found, traveler? Ah, a scroll written in a mysterious language. Quite an interesting find!\n\n<Nola carefully examines the scroll.>\n\nI've never seen characters like these before, but perhaps Kugro has..." }
WordHunterWoW_QuestEN[49846] = { title = "Wars on Two Fronts", description = "<name>! You have been called upon once again to assist the Horde in matters of great import.\n\nWill you assist the Horde's efforts against Deathwing and the Twilight Hammer?\n\nOr will you fly south to Pandaria, claiming its resources before the Alliance does first?\n\nMake your choice and head into battle!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Special Duty Assignments to select your next adventuring destination." }
WordHunterWoW_QuestEN[49851] = { title = "Cataclysm First Responder", description = "Deathwing, the draconic aspect of death, has sent his minions out to scour Azeroth of life.\n\nFarseer Krogar in Orgrimmar can tell you more about Mount Hyjal, Vashj'ir, and other areas that Deathwing has targeted.", objectives = "Report to Farseer Krogar in Orgrimmar.", completion = "Ah, <name>. Thank you for responding to my request." }
WordHunterWoW_QuestEN[49852] = { title = "To Pandaria!", description = "You are hereby ordered to present yourself at Grommash Hold immediately.\n\nWe have received word of a new, resource-rich continent in the south, and we intend to send you and a small contingent of soldiers to claim it for the Horde.", objectives = "Report to Grommash Hold in Orgrimmar.", completion = "Lok'tar, <name>." }
WordHunterWoW_QuestEN[49855] = { title = "Disaster at Mount Hyjal", description = "Our brothers in the Cenarion Circle report that Deathwing's minions have launched a destructive offensive against the world tree and threaten to burn it to the ground!\n\nYou can speak with Cenarion Emissary Blackhoof to gain entry into Moonglade. He is in the tauren district in the Valley of Wisdom in Orgrimmar.", objectives = "Speak to Cenarion Emissary Blackhoof to secure transportation to Moonglade.", completion = "We knew the Horde would send help and not a moment too soon!" }
WordHunterWoW_QuestEN[49860] = { title = "Adventure Calls", description = "Tales of your heroism have spread to the ends of Azeroth... and beyond. Your skills have been requested elsewhere.\n\nWill you travel through the Dark Portal, fighting the Burning Legion on the sundered world of Outland?\n\nOr will you fly north, joining the battle against the Lich King in Northrend?\n\nThe choice is yours, adventurer.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Special Duty Assignments to select your next adventuring destination." }
WordHunterWoW_QuestEN[49862] = { title = "Burning Crusade: To Outland!", description = "The Burning Legion - an uncountably vast army of demons - has assaulted Outland, the tattered homeworld of the draenei. Adventurers of the Alliance are needed to protect what remains of Outland from utter annihilation at the hands of this demonic invasion.\n\nTravel to the Blasted Lands, and pass through the Dark Portal.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Go through the Dark Portal in Blasted Lands.\n\nThe Honor Hold Mage in the Mage District can help you get there." }
WordHunterWoW_QuestEN[49863] = { title = "Wrath of the Lich King: To Northrend!", description = "The Lich King stirs in the north.\n\nAn undead army follows his command, marching across Northrend and spreading blight wherever they tread.\n\nWe need you to stop them, <name>.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Take a ship to Northrend.\n\nYou can board the ship to Borean Tundra in Stormwind Harbor, or the ship to Howling Fjord in Wetlands." }
WordHunterWoW_QuestEN[49864] = { title = "Wars on Two Fronts", description = "<name>! You have been called upon once again to assist the Alliance in matters of great import.\n\nWill you assist the Alliance's efforts against Deathwing and the Twilight Hammer?\n\nOr will you fly south to Pandaria, claiming its resources before the Horde does first?\n\nMake your choice and head into battle!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Special Duty Assignments to select your next adventuring destination." }
WordHunterWoW_QuestEN[49865] = { title = "Cataclysm: First Responder", description = "Deathwing, the draconic aspect of death, has sent his minions out to scour Azeroth of life.\n\nNaraat the Earthspeaker can tell you more about Mount Hyjal, Vashj'ir, and other areas that Deathwing has targeted.", objectives = "Report to Naraat the Earthspeaker in Stormwind.", completion = "Ah, <name>. Thank you for responding to my request." }
WordHunterWoW_QuestEN[49866] = { title = "Mists of Pandaria: To Pandaria!", description = "Please come to Stormwind Keep immediately for a briefing with King Varian Wrynn.\n\nWe have received word of a conflict in the seas to the south, and we need the help of an experienced <class> to assist in the investigation.", objectives = "Report to Rell Nightwind in Stormwind.", completion = "Greetings, <name>." }
WordHunterWoW_QuestEN[49869] = { title = "A Desperate Defense", description = "The soldiers garrisoned here are doing their best to hold out, but they're struggling. Pirates haven't dared attack this gate in years, and never with such a large force.\n\nIf you're handy in a fight, Lieutenant Tarenfold will want to meet you. \n\nHe's organizing the militia up ahead.", objectives = "Report to Lieutenant Tarenfold.", completion = "Aha! Reinforcements!\n\nWait... Where are the rest of you?" }
WordHunterWoW_QuestEN[49870] = { title = "Size Matters", description = "So the unintended side-effect of Gentle Ben'jin being, shall we say 'fun-sized' is that he is now small enough to get into the cave where the alpha wind serpent is! \n\nThe beast is called Gloomtail and if Ben'jin defeats it, he will feel like this territory is his and will want to fill it with little brutosaurs. So he will seek out a mate. If Maka'fon is receptive, everyone wins! \n\nGo give him another hit of the formula!", objectives = "Administer the 'voodoo'-ed Aggression Formula to Ben'jin.", progress = "Size isn't all dat matters. Ben'jin can get to more places if he's small... and fight dere!", completion = "Dat was incredible! I could hear de snorting and stomping from here. \n\nWell done, <name>." }
WordHunterWoW_QuestEN[49871] = { title = "Against the Tide", description = "De mogu are growin' desperate. Ha! Maybe dey hope to get away from here before de fury of de loa rain down on dem!\n\nDe warlord's pet sorcerer set up blockers and dey have taken de tower.\n\nIf you can avoid the sting, de lightning rods can have ya feelin' pretty good. One could even say energized. \n\nGet to Warlord Xiar and relieve him of his life privileges.\n\nThen let our people know we have taken back de Breath of Pa'ku! \n\nDis mojo is empowered to ignite de tower with a mighty blast.", objectives = "Kill Warlord Xiar, and light the signal fire.", completion = "Not bad, <name>! Our work is nearly complete!" }
WordHunterWoW_QuestEN[49873] = { title = "Sacrificial Writes", description = "<As you peer inside the tome, you find a verse appear, glowing bright red.>\n\n\"For blood to bond, one strikes a deal,\nA sacrifce which will appeal.\nSeek out the lame, and never yield,\nFor in return, you shall be healed.\"\n\n<As you finish reading the verse, you notice that a scroll has appeared in your hand.\n\nWritten across the top it's titled, \"Writ of Sacrifice\". Various runes, unknown to you, appear on the rest of the scroll. Yet, there's no explanation as to what to do with the scroll...>", objectives = "Ask Kronah about the Writ of Sacrifice. Follow her directions after she gives you the information you need.", completion = "I see you've completed the trial.\n\n<Kronah takes the writ from your hand and places it on the tome. It slowly begins to meld with the tome, and in a burst of light it vanishes.>\n\nYou have done well and are now imprinted for all time with the Contract of Sacrifce.\n\nNow, onto more important matters. What do you think of murloc brain soup? I find it delightful and would love a guest to accompany me for a serving of it." }
WordHunterWoW_QuestEN[49874] = { title = "By the Book", description = "As you open the book, you stare at a blank page, waiting for something to happen.\n\nInstinctively you flip to the next page only to find it blank as well. Perhaps your trial awaits you further into the book?", objectives = "Investigate the Bloodshed Compendium further to begin your trial.", progress = "I trust you to be careful inside the Bloodshed Compendium. I don't want to find any ripped pages from that weapon you wield.", completion = "You've done well, young one. I recall a gnome not too long ago completing that trial as well.\n\nHer story was quite the read. But between you and me, gnomes smell like porridge.\n\n<Kronah looks off into the distance, lost in thought for a moment.>\n\nBut you are now a bearer of the Bloodshed Contract and one step closer to your final prize.\n\n<Kronah quirks a grin at you and goes back about her business.>" }
WordHunterWoW_QuestEN[49875] = { title = "First Impressions", description = "This was all I had to offer you, young scribe. But your journey is not yet at the end.\n\nGo to your trainer and and inform them of your success here.\n\n<Kronah grabs an odd-looking jar.>\n\nI don't suppose you'd like to take some pickled crocolisk eggs with you for the road, would you?\n\n<As she unlocks the lid, the foulest odor you've ever smelled permeates the air and you reel back in disgust.>\n\nFine, be that way. It's an acquired taste anyway. Takes thousands of years to train the palate.", objectives = "Return to Zooey Inksprocket in Tiragarde Sound.This was all I had to offer you, young scribe. But your journey is not yet at the end.\n\nGo to your trainer and and inform them of your success here.\n\n<Kronah grabs an odd-looking jar.>\n\nI don't suppose you'd like to take some pickled crocolisk eggs with you for the road, would you?\n\n<As she unlocks the lid, the foulest odor you've ever smelled permeates the air and you reel back in disgust.>\n\nFine, be that way. It's an acquired taste anyway. Takes thousands of years to train the palate." }
WordHunterWoW_QuestEN[49876] = { title = "Lines In the Sand", description = "This was all I had to offer you, young scribe. But your journey is not yet at an end.\n\nIf you're up for some traveling, and interested in some of the deadlier blood contracts, you're going to have to travel to Zandalar.\n\nOnce there, seek out a sethrak by the name of Veriss in an area known as Vol'dun.\n\n<Kronah grabs an odd-looking jar and opens it. The foulest odor you've ever smelled emanates from it and you reel in disgust.>\n\nPickled crocolisk eggs are my favorite. Would you like some?", objectives = "Seek out Veriss at the Terrace of the Devoted in Vol'dun to begin your blood trials there.", completion = "Ah! A new initiate! Were you wondering how I knew? Because of the blood on your hands, of course.\n\n<A sly grin crosses over the sethrak's face.>\n\nI am Veriss, the resident keeper of the Zandalar blood contracts.\n\nIf you wish to inscribe your name into them, there is something I must ask of you first." }
WordHunterWoW_QuestEN[49877] = { title = "Temple of Sethraliss: Booking on a Favor", description = "When the Faithless came to power, we Devoted fled our sacred temple and took shelter here.\n\nHowever, in the midst of  our exodus, many of us were forced to abandon some of our belongings.\n\nI myself left a tome that is used to learn the Oblivion contract. If you wish to proceed with the trials, you must retrieve that book for me, {name}.\n\nI trust you won't disappoint me.", objectives = "Recover the Tome of Oblivion from the Temple of Sethraliss.", progress = "I'll admit, I'm a bit embarrassed to have left it behind. An oversight that I still regret to this day.", completion = "I'm relieved you were able to retrieve it. Thank you, <name>." }
WordHunterWoW_QuestEN[49878] = { title = "Penning In Protection", description = "<As you open the book, you turn each page and see portraits of champions standing alongside a large beast.\n\nEventually you come to a blank portrait, and touch the page. Runes begin to appear in an ancient language, and quickly translate into words you can read.>\n\n\"The creature within, a guardian of men,\nA mixture of blood\nand of bone inked with pen.\nThe blood from the scribe,\nthe bone from the land,\nMilled to perfection,\nand signed by the hand.\"", objectives = "Collect bones from Zem'lan pirates and mill them into a fine powder. Mix the powder with your blood to create a Vial of Ossein Ink. Then sign the Bloodguard Chronicles.", progress = "You would think with all the blood you have to give up for these trials, that you would be white as a ghost at the end of them.\n\nOr maybe just passed out for a week.", completion = "You've been accepted, it appears.\n\n<Veriss motions to the book. You glance over and see an image of yourself posed alongside a great beast. Your signature glistening at the top of the page.>\n\nYou may now invoke the Contract of the Bloodguard.\n\nBe mindful of the guardian's life though. If it gets too low, it may look at you as potential fuel." }
WordHunterWoW_QuestEN[49879] = { title = "Brush With Death", description = "<As you open the book, a sudden chill comes over you. You shake the sensation off as you read the verse.>\n\n\"A fatal bargain, in blood is struck,\nOne inks their pledge,\nwith strokes of luck.\nStay true your lines,\nkeep still your breath,\nLest you stray too far,\nand summon death.\"\n\n<As you finish reading the incantation, a quill appears next to the book.>", objectives = "Pick up the quill and begin your trial.", completion = "Well done, young blood scribe.\n\nYou can now invoke the Oblivion Contract. It lets you summon a creature that, well let's just say, his bite is bigger than his bark.\n\nHe likes to prey on creatures that are on the verge of death, yourself included if you're not too careful." }
WordHunterWoW_QuestEN[49880] = { title = "Blood Bonded", description = "Looks like you're all done here, {name}. Thanks again for getting my book back, you can understand how that might appear for a master such as myself to lose something like that.\n\nBut between you and me, this was the easy part. Just wait till you meet the grandmaster.\n\nI'll let your current trainer fill you in on that part. Good luck, {name}!", objectives = "Return to Zooey Inksprocket in Tiragarde Sound.Looks like you're all done here, <name>. Thanks again for getting my book back, you can understand how that might appear for a master such as myself to lose something like that.\n\nBut between you and me, this was the easy part. Just wait till you meet the grandmaster.\n\nI'll let your current trainer fill you in on that part. Good luck, <name>!" }
WordHunterWoW_QuestEN[49881] = { title = "The Final Verse", description = "It appears you are finished here, {name}. Thank you again for getting my book back.\n\nBut between you and I, this was the easy part. Just wait till you meet the grandmaster.\n\nIf you haven't noticed already, you'll need a special quill to invoke those contracts. And he'll be the one who shows you how to craft it.\n\nHis name is Miju and he lives out on an island off the southern coast of Zuldazar. Good luck, {name}!", objectives = "Seek out Miju in southern Zuldazar to begin your final trial.", completion = "What's this then? Another novice come to learn the ways of blood-scribing?\n\nVery well, for which contract do you need a quill?\n\n<You explain to Miju that you've learned all four contracts and need a quill to invoke all of them.>\n\nALL FOUR?! Oh my, it's been... let's see here...\n\n<Miju beings mumbling to himself.>\n\nToo long I suppose. But yes. I still know the recipe. Your trial awaits you then." }
WordHunterWoW_QuestEN[49882] = { title = "A Test of Quills", description = "The recipe you're after, young one, is that of the Sanguine Feather Quill of Lana'thel. I...\n\n<Miju motions to a pile of stuff.>\n\nAm the only other person I know of who has one... err... somewhere. But be warned, this trial may be your undoing!\n\nI shall have to invoke all four contracts against you. You must defeat each of the creatures, and from each one learn the rune needed to carve into your quill.\n\nOnce you've learned all four runes, your trial shall be completed.", objectives = "Speak with Miju to begin your final trial and collect the knowledge to craft your quill.", completion = "Well done, young scribe. Well done, indeed!\n\nYou have the knowledge now. It's up in there.\n\n<Miju tries to poke you in the head but you back away just in time.>\n\nYou're quick, probably how you succeeded in the trial. And now I present you with the final knowledge you need to craft your quill.\n\nOk, goodbye." }
WordHunterWoW_QuestEN[49884] = { title = "Hope's Blue Light", description = "There is but one step left!\n\nDe second tower means the fleet is ours again!\n\nClimb aboard and we will finish dis thing!", objectives = "Fly with Captain Grez'ko to light the signal fire on the tower.", completion = "You have saved de fleet and protected de Bay of Kings!\n\nYa did well, <name>! We captains are a wise lot." }
WordHunterWoW_QuestEN[49886] = { title = "Follow Your Nose", description = "You there! I could use your help!\n\nThe ground isn't safe. The quilboar have established a network of tunnels below us, allowing them to spring up to ambush people who aren't walking carefully.\n\nLuckily for us, Humphrey here has a nose for the Briarback, and can sniff 'em out even when they're underground. Root a few of them out and let's make the farms a little safer to walk through.\n\nThere's a particularly large clump of them in the northeastern fields. Good hunting!", objectives = "Use Humphrey to find and slay 5 Panicked Tunnelers.", completion = "Hah! I bet ol' Humphrey gave them a good spook!" }
WordHunterWoW_QuestEN[49887] = { title = "Forced Labor", description = "<The laborer struggles to speak through the magic binding him.>\n\nH... help... us...\n\n<He achingly lifts a finger, gesturing towards the nearby anchor.>\n\nPlease...", objectives = "Free Samuel Williams.", progress = "<It appears he lacks the energy to respond further.>", completion = "At least not all of the tidesages have turned on us.\n\nNot yet." }
WordHunterWoW_QuestEN[49888] = { title = "Atal'Dazar: A Little Mojo", description = "", objectives = "" }
WordHunterWoW_QuestEN[49890] = { title = "Drustfall", description = "I believe I see more carvings at the entrance to that cave over there. Come, we should see what else was left behind.", objectives = "Investigate the ice cavern.", completion = "The carvings could have been Drust propaganda stating he lived, but that voice!\n<Cleardawn's face becomes grim>\nIt seems we may have all been mistaken about the ultimate fate of Gorak Tul. I shudder to think what he might be planning now." }
WordHunterWoW_QuestEN[49896] = { title = "To Falconhurst!", description = "Our time here was well spent. The guards in Arom's Stand can handle what few Drust forces remain and I suspect the Drust leader and his magic might have some greater part to play here. \n\nHowever we must continue on the mission to Falconhurst. The path on the far side of these ruins will take us there.\n\nI will ride ahead and meet you outside of town!", objectives = "Meet Inquisitor Cleardawn outside of Falconhurst.", completion = "The town is under siege! No wonder we have not heard from them. We must help them." }
WordHunterWoW_QuestEN[49897] = { title = "Making Mysteries", description = "Do you know what people love? The unexplained! Problem is, everything here is explainable. \n\nSo I have a plan to create our own phe-gnome-enon. There are stories that talk about some weird chicken-snake hybrids that can turn you to stone. I've already released the chickens, now we just need the snakes.\n\nThe first problem can be solved easily. Just chase down the chickens, and stick one of these robotic tails on them.", objectives = "Catch 5 Unassuming Chickens.", progress = "How do my petrifyingly scary chickens look?", completion = "Stupendous! Now we can start calling our resort tour a \"mystery safari\"!" }
WordHunterWoW_QuestEN[49898] = { title = "Clear Victory", description = "<The ghostly captain continues to fight as she speaks, once more locked into the heat of battle, unaware the war has been over for centuries.>\n\nWhat are you doing standing around? We've ground them down to their final warriors and those damnable runic constructs, but the war isn't over yet!\n\nColonel Waycrest needs us to hold this line! Kill as many of those Drust as you can and we might see the end of this war, today. Get back out there!", objectives = "Slay 15 Drust Skeletons.", completion = "Not bad, marine! We might make a proper soldier out of you yet!\n\nThey'll make Colonel Waycrest a Lord for this, I'm sure. Your bravery will be remembered." }
WordHunterWoW_QuestEN[49901] = { title = "Atal'Dazar: Yazma the Fallen Priestess", description = "Zul knows dat we cannot let de first king rise from his grave. Dazar would be more than a figure head for Zul's dream troll empire, he would be a force dat could rival de very loa.\n\nBut I cannot just let Zul get away. I and mine will follow Zul, but I want you and yours to enter Atal'Dazar. Yazma is trying to buy time and keep de tombs sealed away. You will need to fight your way through to her and you will need some allies to do so. Slay her.", objectives = "Defeat Yazma in Atal'Dazar.", progress = "And here I always thought Yazma was just rude. I never expected just how far she had fallen.", completion = "Yazma's betrayal was vile beyond words.\n\nIt may take us some time to find our way deeper into Atal'dazar. In de meantime, we have more work to do." }
WordHunterWoW_QuestEN[49902] = { title = "To Gloom Hollow", description = "There's only one safe area in Nazmir that this Rokhan and your other Horde friends could be in. Gloom Hollow.\n\nLucky for you, it's also close to Krag'wa's den. We used Gloom Hollow as a last stop on our pilgrimage.\n\nMake your way to Gloom Hollow along the path I've marked on your map, and tell any tortollans along the way to meet us there.\n\nThey'll be interested in seeing the end of this story. We'll make our way there and grab anyone else we find.", objectives = "Recruit tortollans to your cause on the way to Gloom Hollow.", completion = "Good ta see ya, <name>. Princess Talanji be tellin' me all about Torga and da tortollans. Guess we lucky dat we got sometin' outta dis.\n\nWe be here, waitin' on reinforcements from da Horde." }
WordHunterWoW_QuestEN[49905] = { title = "Plot Twist", description = "It is time to end Vol'jamba.\n\nI want to make one thing clear. He can still kill you. Your fate, moreso than mine, hangs on your ability to fight dis former student of mine.\n\nHe will bring masks, and voodoo, and he will do everything within his power to end you. All we have done is taken away his ability to cheat.\n\nGood luck. For your sake, I hope you do not fail.", objectives = "Slay Vol'jamba.", progress = "Let us be rid of dis nuisance.", completion = "Death is a tool, <name>. Do not forget dat." }
WordHunterWoW_QuestEN[49908] = { title = "Back to Brennadam", description = "The naga are mostly cleared out thanks to your help. They'll think twice before attacking again.\n\nCan you return to Brennadam and tell Squire Augustus III to return to his normal station?", objectives = "Report back to Squire Augustus III at Brennadam.", completion = "Oh, roger! I'll head back at once!" }
WordHunterWoW_QuestEN[49917] = { title = "Kaja'mite? Kaja'must!", description = "I been waitin' to talk to the King for a while now, but he not be seein' me! And this pompous lackey not be listenin' either.\n\nWe got a problem brewin' in the Village of the Vines, just outside de city. With all the Horde landin' in the Harbor, some goblins got wind of our old kaja'mite quarry. They split outta here like the teeth of Deathwing himself behind 'em.\n\nBut that quarry be dangerous. Wicked dangerous. Think you can go to de village an' talk some sense into them goblins?", objectives = "Travel to Village in the Vines.", completion = "You came just in time pal. There's loads of work to do if there's really kaja'mite here in Zuldazar!" }
WordHunterWoW_QuestEN[49918] = { title = "Gorilla Gorge", description = "", objectives = "" }
WordHunterWoW_QuestEN[49919] = { title = "Kaja'mite Ore Bust", description = "Kaja'mite! Just saying the name gives my big beautiful ears a buzz. \n\nThese Zandalari were sitting on a huge deposit of it all these years. And they abandoned it just because of a few talking gorillas. By goblin law it's ours for the taking!\n\nLet's see how concentrated a deposit we're talking about. Get a good peek at those vents that are steaming out kaja'mite vapors.\n\nGo into the gorge and plant my scanners on those steam vents. They'll do the rest.", objectives = "Scan Kaja'mite Steam Vents in Gorilla Gorge.", completion = "Thank you chump! I mean chum.\n\nThere's enough kaja'mite there to get us started. Too bad about all the talking gorillas in the way." }
WordHunterWoW_QuestEN[49920] = { title = "Gorilla Warfare", description = "Your timing is most fortuitous, stranger. I thank you for your assistance.\n\nThings are not peaceful in Gorilla Gorge. The kaja'mite has given us great intelligence and wit. With intelligence has come war. \n\nMy brethren are those who do not wish to fight. Neither the Zandalari trolls nor each other. But for our passivity we have been persecuted.\n\nPlease free my comrades. They will be in cages all throughout the gorge and under guard. Make haste!", objectives = "Rescue 6 Pacifist Gorillas.", completion = "Thank you my friend! I saw the bravery with which you granted freedom to my comrades. We shall speak more anon." }
WordHunterWoW_QuestEN[49922] = { title = "King Da'ka", description = "These Zandalari won't go near Gorilla Gorge. All because they're afraid!\n\nIt's just a few talking gorillas. And one 'big mon' in particular as the Zandalari call him. \n\nAll we need to do is take out King Da'ka and the villagers will probably throw us a parade! Or at least let us mine that kaja'mite.\n\nThink you can handle one big gorilla, chum?", objectives = "Slay King Da'ka.", completion = "Good. One less mook to deal with. That kaja'mite is as good as ours!" }
WordHunterWoW_QuestEN[49926] = { title = "The Road to Corlain", description = "Lord and Lady Waycrest lay trapped in Waycrest Manor. Before we can reach them, however, we must brave through the city of Corlain... which is firmly in the grasp of the Heartsbane.\n\nOur first course of action should be to set up a forward outpost. Our scouts have found that the tower at Watchman's Rise is only lightly guarded. I recommend we take the tower from them.\n\nThis is now your command, Inquisitor. Say the word, and we ride.", objectives = "Meet with Marshal Reade at Watchman's Rise in Drustvar.", completion = "Good, you've arrived. \n\nThis tower watches over Corlain and the surrounding lands. Apparently it is of little value to the coven, but to us it would serve as a valuable foothold." }
WordHunterWoW_QuestEN[49928] = { title = "Heritage of the Void", description = "Throughout your journeys across Azeroth, you have achieved mastery over the forces that constantly seek to control you.\n\nYou have become a formidable weapon of the Alliance, {name}. Return to the void rift so that we may honor your accomplishment.", objectives = "Meet Alleria Windrunner at Telogrus Rift.", completion = "Though some continue to doubt us, your deeds have proven that the ren'dorei serve the Alliance with honor.\n\nYour will is strong, <name>. Accept this gift as a symbol of the powers you command." }
WordHunterWoW_QuestEN[49929] = { title = "The Call for Allies", description = "The Alliance has been beset by dangers growing throughout all of Azeroth.\n\nThe only way we will keep our friends safe is if we seek out new allies.\n\nI have been tasked as an ambassador to help seek these allies. Come to our embassy in Stormwind, I could use your help.", objectives = "Meet Aysa Cloudsinger at the Stormwind Embassy.", completion = "Welcome, <name>. I am pleased you answered the call." }
WordHunterWoW_QuestEN[49930] = { title = "The Call for Allies", description = "Greetings, champion! I have been appointed as the Horde's diplomatic ambassador to our allies far and wide. \n\nIt is my duty to seek out those of like mind and spirit, and speak to them about joining the Horde.\n\nAs a renowned hero of the Horde yourself, your aid would be most appreciated! Come see me at the embassy in Orgrimmar when you are able.", objectives = "Meet Ji Firepaw at the Orgrimmar Embassy.", completion = "Ah, <name>. Now we can begin." }
WordHunterWoW_QuestEN[49931] = { title = "The Titan's Wrath", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[49932] = { title = "Slumber No More", description = "There's something you should look into. You've got the time anyway, those goblins aren't ready yet.\n\nThere's a statue nearby. Only, it's not a statue to the trained tortollan eye. It's a deactivated titan keeper!\n\nNoises have been coming from that thing ever since you helped Krag'wa. It must be trying to reactivate itself.\n\nI bet that titan-looking amulet of yours could help restart it. We'd be unstoppable against the blood trolls with a titan keeper's help.\n\nGo see if you can restart this titan!", objectives = "Examine the deactivated titan keeper outside of Gloom Hollow.", progress = "Core detected. Appreciation for retrieval.", completion = "Your aid is required. We must begin." }
WordHunterWoW_QuestEN[49933] = { title = "For the Horde", description = "After ages standing alone, we are once again poised to become part of something greater. Our alliance with the Horde affords us a fresh start, a unique chance that must not be squandered.\n\nGo to Orgrimmar. From there, you will set out on a journey across Azeroth. Fight to defend this land, and claim a place for the shal'dorei within it.\n\nShow the world who we are, {class}. Bring honor to the Horde, for in so doing, you will bring honor to Suramar.", objectives = "Meet Ambassador Blackguard at the Orgrimmar Embassy.", completion = "Are you the new one? I'm supposed to welcome you. Here, take this letter.\n\n<Blackguard lets out an exasperated sigh.>" }
WordHunterWoW_QuestEN[49935] = { title = "How to Repair a Titan Keeper", description = "Major system repair possible within nearby structure. Preliminary goal: repair auxiliary systems.\n\nScans detect three fallen titan keepers. Recover cores. Titan Keeper Hezrel able to retrieve data from cores.\n\nTitan Keeper Hezrel goal: reboot auxiliary systems, reach nearby structure, restore all primary systems, seal corruption.\n\nResult: corruption contained. Titan Keeper Hezrel able to aid against blood trolls.\n\nBlood troll definition not found in databanks.", objectives = "Recover Titan Data Cores from fallen titan keepers.", progress = "Insert data cores.", completion = "Cores recovered. Data validation and merge will begin shortly." }
WordHunterWoW_QuestEN[49937] = { title = "Recovering Remnants", description = "Scan of area indicates roaming spirits clad in armor plating. Purpose: defense of structure, animated by corruption.\n\nDetecting remnants of titan plating within spirits' armor. Request: recover remnants.\n\nTitan Keeper Hezrel capable of breaking down titan plating to reforge into weapon against forces drawn by corruption.", objectives = "Recover 25 Titan Plating from Nazwathan Spectres.", progress = "Titan plating required.", completion = "Sufficient titan plating. Will begin forging process once functionality is restored." }
WordHunterWoW_QuestEN[49938] = { title = "Corrupted Earth", description = "Unacceptable levels of corruption detected nearby. Scan indicates vegetation affected by corruption. \n\nAll corruption must be eradicated. Request: destroy any vegetation affected by corruption.", objectives = "Destroy 12 Blood-Infused Lashers.", completion = "Vegetation corruption reduced to an acceptable level." }
WordHunterWoW_QuestEN[49939] = { title = "So Long, Sister", description = "We have given the defenders some breathing room, but these creatures continue to lay siege to the barricade!\n\nThe witch behind the attack fled from the field when we defeated her forces. I saw her go into the mansion on the hill. I will help keep the defenses going here.\n\nYou must go into the mansion and slay the witch!", objectives = "Slay Sister Noella Briarwood.", progress = "The witch must be slain!", completion = "We wouldn't have been able to hold out much longer. You saved us all." }
WordHunterWoW_QuestEN[49940] = { title = "Sandscar Breach", description = "I heard some mutterings about sand and snakes.\n\nThe plea comes from a tiny village on the very fringes of Zuldazar- hardly more than a few farms. Dol-something I think it was called. Don't know what they be calling it now. Go see what the fuss is about.\n\nBladeguard Sonji was sent ahead some time ago. She should be able to get you up to speed on that... situation.", objectives = "Meet Bladeguard Sonji at Sandscar Breach.", completion = "Rastakhan finally sent someone!\n\nI hope you not be afraid of snakes, mon." }
WordHunterWoW_QuestEN[49941] = { title = "Bone Procession", description = "Undead entities influenced by corruption surround nearby structure. Impossible to approach. Plan required.\n\nCalculating.\n\nPlan achieved. Large creatures designated reanimated monstrosities focal gathering point of corruption.\n\nTake titan weapon forged from plating recovered. Use it to weaken monstrosities and collect bones.\n\nWill run process to destroy bones, prevent creation of further monstrosities.", objectives = "Weaken Reanimated Monstrosities with the Titan Manipulator and collect 15 of their bones.", progress = "Insert reanimated monstrosity bones to continue.", completion = "Destruction of bones will begin." }
WordHunterWoW_QuestEN[49943] = { title = "Drawing Blood", description = "Hey, {name}! I have something exciting to tell you about, but I need you to keep it secret. Just between us scribes.\n\n<Grazzul gives you a nod and pulls out a large tome.>\n\nDis is de Bloodbound Ledger. Signing your name in it let's you learn how to craft \"blood contracts\" which are rather dangerous, but worth de risk.\n\nI only know one of dem and it is quite de rush when I use it because it... well, you'll see.\n\nSo what do you say? Interested?", objectives = "Sign the Bloodbound Ledger.", completion = "Let me make sure you did it right.\n\n<Grazzul finds your signature and nods.>\n\nYes, everything looks in order and it looks like de spell has already taken effect on you.\n\nYou are now worthy of knowing how to craft de \"blood contracts\".\n\nBut be careful with dem, <name>. I said it before and I'll say it again. They're dangerous things to play with." }
WordHunterWoW_QuestEN[49944] = { title = "Turn to Drust", description = "Dere are blood scribe masters all over de place who'll teach you what you need to know. De first master I'd recommend seeking out is Kronah.\n\nShe's a bit... eccentric to say de least. One of de few tortollan who've experienced a thing or two.\n\nShe's de one who taught me de blood contract I know how to invoke!\n\nShe prefers to hang out at de Smuggler's Cove on de western coast of Drustvar.", objectives = "Seek out Kronah at the Smuggler's Cove in Drustvar.", completion = "<Kronah eyes you up and down warily.>\n\nSay ahhh for me, would you lad?\n\n<Kronah peers inside your mouth.>\n\nNice teeth you have there. Would fetch a fine price. But that's not really what you're here for, is it?\n\nNo, you're one of those who think they can handle the trials of the blood contracts, aren't you? Very well." }
WordHunterWoW_QuestEN[49945] = { title = "First Impressions", description = "This was all I had to offer you, young scribe. But your journey is not yet at the end.\n\nGo to your trainer and and inform them of your success here.\n\n<Kronah grabs an odd-looking jar.>\n\nI don't suppose you'd like to take some pickled crocolisk eggs with you for the road, would you?\n\n<As she unlocks the lid, the foulest odor you've ever smelled permeates the air and you reel back in disgust.>\n\nFine, be that way. It's an acquired taste any ways. Takes thousands of years to train the palette.", objectives = "Return to Zooey Inksprocket in Tiragarde Sound." }
WordHunterWoW_QuestEN[49946] = { title = "Lines In the Sand", description = "This was all I had to offer you, young scribe. But your journey is not yet at an end.\n\nIf you're up for some traveling, and interested in some of the deadlier blood contracts, you're going to have to travel to Zandalar.\n\nOnce there, seek out a sethrak by the name of Veriss in an area known as Vol'dun.\n\n<Kronah grabs an odd-looking jar and opens it. The foulest odor you've ever smelled emanates from it and you reel in disgust.>\n\nPickled crocolisk eggs are my favorite. Would you like some?", objectives = "Seek out Veriss at the Terrace of the Devoted in Vol'dun to begin your blood trials there.", completion = "Ah! A new initiate! Were you wondering how I knew? Because of the blood on your hands, of course.\n\n<A sly grin crosses over the sethrak's face.>\n\nI am Veriss, the resident keeper of the Zandalar blood contracts.\n\nIf you wish to inscribe your name into them, there is something I must ask of you first." }
WordHunterWoW_QuestEN[49947] = { title = "Blood Bonded", description = "Looks like you're all done here, {name}. Thanks again for getting my book back, you can understand how that might appear for a master such as myself to lose something like that.\n\nBut between you and me, this was the easy part. Just wait till you meet the grandmaster.\n\nI'll let your current trainer fill you in on that part. Good luck, {name}!", objectives = "Return to Zooey Inksprocket in Tiragarde Sound.Looks like you're all done here, <name>. Thanks again for getting my book back, you can understand how that might appear for a master such as myself to lose something like that.\n\nBut between you and me, this was the easy part. Just wait till you meet the grandmaster.\n\nI'll let your current trainer fill you in on that part. Good luck, <name>!" }
WordHunterWoW_QuestEN[49948] = { title = "The Final Verse", description = "Now dat you be done learnin' all da contracts, you be needin' one more ting ta learn.\n\nDere be a special quill ya need to make in order to craft da contracts. And dere be one last trial ya must complete in order ta be worthy ta learn da design for da quill.\n\nMiju be da mastah in charge of da design. Pass his trial, and he'll be teachin' ya what'cha need ta know.", objectives = "Seek out Miju in (Zone) to begin your final trial.Now dat you be done learnin' all da contracts, you be needin' one more ting ta learn.\n\nDere be a special quill ya need to make in order to craft da contracts. And dere be one last trial ya must complete in order ta be worthy ta learn da design for da quill.\n\nMiju be da mastah in charge of da design. Pass his trial, and he'll be teachin' ya what'cha need ta know." }
WordHunterWoW_QuestEN[49949] = { title = "Unwelcome Undead", description = "Corruption reanimating dead creatures nearby. Morphing into monstrosities. Must be stopped.\n\nCannot kill all, but can reduce numbers. Reduced numbers equates to less corruption outside of containment.\n\nDestroy undead in surrounding area. Keeper Hezrel's systems will continue rebooting while you do so.\n\nReboot goal: recover data regarding nature of corruption.", objectives = "Kill 15 Nazwathan undead.", completion = "Undead levels lowered to acceptable amount. Still require method to bypass targets in order to access containment." }
WordHunterWoW_QuestEN[49950] = { title = "Blood Purification", description = "<You see a strange blood orb that emanates whispers of suffering and destruction.\n\nThese must be the source of energy for whatever corruption Hezrel is hunting. They appear easy enough to destroy.\n\nYou can see more of these orbs around the temple grounds. Perhaps destroying them will help to weaken the corruption in the area.>", objectives = "Destroy 4 Corrupted Energy.", completion = "Scanners did not pick up evidence of corrupted energy. Must continue repairs, cannot make same mistake again." }
WordHunterWoW_QuestEN[49952] = { title = "The Essence of G'huun", description = "Analysis of blood-infused bones complete. Will be able to create synthetic essence similar to G'huun.\n\nWill take a moment to apply essence, allow you to walk past undead without combat.\n\nMust hurry. More forces of G'huun are around temple. Must get inside to reactivate containment protocols.", objectives = "Have Titan Keeper Hezrel apply Synthetic Essence to allow safe passage past undead." }
WordHunterWoW_QuestEN[49955] = { title = "Not Fit for This Plane", description = "System restoration in progress. Data recovered. Source of corruption is from an Old God entity.\n\nMultiple entities detected nearby, blocking goal of analyzing and containing corruption in Nazmir.\n\nEntities appear to be from the Void. Drawn here from Old God corruption.\n\nRequest to destroy Void entities. Void presence inhibiting repair of systems.", objectives = "Eliminate 6 Faceless Ones.", progress = "Level of Void entities too high.", completion = "Old God minions temporarily reduced. Will not last long without proper containment." }
WordHunterWoW_QuestEN[49956] = { title = "Void is Prohibited", description = "Scans indicate errors in reality surrounding nearby structure. Portals directly to the Void.\n\nCurrent theory, corruption has Old God as source. Void attracted to Old God corruption.\n\nPortals must be sealed to contain entities lured here by Old God corruption.\n\nTake this device. Titan Keeper Hezrel has forged it thanks to help in powering up systems.\n\nUse device to seal Void portals, prevent more void entities from entering area.", objectives = "Seal 4 Void Portals.", completion = "Void portals no longer detected. Must continue." }
WordHunterWoW_QuestEN[49957] = { title = "Protocol Recovery", description = "System repairs progressing. One key component needed: containment protocol. \n\nContainment protocol will fully reboot defensive systems. Allow Titan Keeper Hezrel to properly maintain containment.\n\nScans indicate large creature within temple has absorbed slab containing containment protocol. Creature exists between this plane and Void.\n\nRequest: destruction of creature and retrieval of protocol.", objectives = "Retrieve Containment Protocol from Overlord Kraxis.", progress = "Please present containment protocol.", completion = "Containment protocol obtained. System reboot initiated." }
WordHunterWoW_QuestEN[49960] = { title = "Sic 'Em!", description = "Humphrey's a good tracker, to be sure. He's also the orneriest, angriest, most dogged dog if he sets his eyes on a quilboar. This will certainly be useful.\n\nBelow our very noses, the foreman organizes and directs the tunnelers to cause the most mayhem and destruction. If you can put an end to him, it should make things a lot easier for us to move around the farmlands.\n\nHumphrey looks a bit hungry, wouldn't you say? Why don't you bring him with you to take care of business?", objectives = "Defeat Foreman Razorgnarl.", progress = "If I could rate Humphrey, I'd give him at least a twelve out of ten.", completion = "Jolly good. With him out of the way, the quilboar around here should be less organized and take longer to mobilize." }
WordHunterWoW_QuestEN[49965] = { title = "The Warpack", description = "Zul began a coup, but he did not secure de pyramid for himself. Nor has he done anything to rally more to his banner outside of those who were already conspiring with him.\n\nDis concerns me more than if he had carved his face into Dazar'alor itself.\n\nWe must learn what he is up to. Join de disciples of Gonk and ride ahead to de Temple of the Prophet. Look to Wardruid Loti for further orders when you arrive.", objectives = "Ride with Gonk to the Temple of the Prophet.", progress = "Good hunting.", completion = "Blood calls out for blood." }
WordHunterWoW_QuestEN[49969] = { title = "Awaken a God", description = "You see the sinking ruins to the east? They were, not long ago, a temple to the shark loa, Gral.\n\nThe naga tore down his temple and are stealing his secrets. If it is for something good, I'll be a rock's uncle.\n\nIt would be wise to let Gral know what's going on here. I do not think he would approve.\n\nGral was quite powerful, and when it came to his knowledge of the sea, none could compare. It never hurts to have a fellow like that on your side.\n\nSome fresh, bloody naga meat may just lure him out.", objectives = "Gather chunks of naga flesh as an offering to Gral.", progress = "<There is a feeling of anticipation emanating from the bowl.>", completion = "Now this! This is an offering worthy of my attention!" }
WordHunterWoW_QuestEN[49973] = { title = "Thalyssra's Estate", description = "Would you like to hear how the nightborne came to join the Horde?\n\nWe earned their trust when we aided them in liberating Suramar from the tyranny of Grand Magistrix Elisande and the Burning Legion.\n\nLor'themar Theron later asked them to join him in Quel'Thalas. Lady Liadrin made the journey to extend the invitation to First Arcanist Thalyssra...", objectives = "Meet with Lady Liadrin at the Estate of the First Arcanist in Suramar.", completion = "The city of Suramar is beautiful to behold. I hope Silvermoon City is not a disappointment to them." }
WordHunterWoW_QuestEN[49975] = { title = "Rest in the Depths", description = "This passage flows through the Shrine of the Storm out into the open sea. We will release the souls of the fallen here.\n\nLegends say that as our spirits pass through the Shrine, they aid in the great blessing rituals that all Kul Tiran ships undergo. \n\nIn that way, we Stormsong never stop serving our people.", objectives = "Complete the Ritual of Release.", progress = "The sea demands respect. To cross it is to invite its wrath upon us all.", completion = "Thank you for aiding me in my solemn task." }
WordHunterWoW_QuestEN[49976] = { title = "Gifts of the Fallen", description = "Earlier today, King Wrynn addressed the citizens of Stormwind at Lion's Rest in a speech given to formally announce the end of the war.\n\nAfter the crowd departed, I met privately with the King and his advisors to discuss a mysterious substance that has been found in Silithus.\n\nThis glowing ore appears to be most powerful and the Horde has wasted no time in extracting it from the great wound.\n\nThe king has ordered me to fill you in on the details, in preparation for an important mission.", objectives = "Speak with Mathias Shaw.", completion = "If this strange substance is as powerful as it appears to be, we cannot allow it to fall into the wrong hands. Your presence will be needed in Silithus." }
WordHunterWoW_QuestEN[49977] = { title = "Summons to Orgrimmar", description = "The Warchief has requested that you return to Orgrimmar as soon as possible. There is an urgent matter that requires your attention.\n\nI will fill you in on the details as soon as you arrive.\n\nYou will find me near the entrance of Grommash Hold. The Dark Lady has plans for you, <name>. I would not keep her waiting...", objectives = "Speak with Nathanos Blightcaller.", completion = "About time you arrived, <name>. The very future of the Horde may depend on what I am about to tell you..." }
WordHunterWoW_QuestEN[49980] = { title = "Containment Procedure", description = "Scans indicate structure has become inoperable. No possibility for repair.\n\nTitan Keeper Hezrel's database fully restored. Believe solution may be within data.\n\nRequire time to scan data, find solution to contain Old God corruption.\n\nStand by while Titan Keeper Hezrel scans databanks for solution.", objectives = "Observe Titan Keeper Hezrel scan for a solution to Nazmir's old god corruption.", progress = "Please stand by.", completion = "New protocol initiated. Defeat of blood trolls critical priority." }
WordHunterWoW_QuestEN[49981] = { title = "Witness to the Wound", description = "I've already sent operatives to Silithus to establish a base camp.\n\nTheir orders are to monitor the operations of the Horde and gather any information they can find on this mysterious substance.\n\nOne of my SI:7 commanders is currently awaiting your arrival. Go with speed.", objectives = "Meet with the SI:7 commander in Silithus.", completion = "Well met, <name>. It's good to have someone of your renown here with us in Silithus." }
WordHunterWoW_QuestEN[49982] = { title = "Witness to the Wound", description = "The Bilgewater Cartel have already begun mining operations in Silithus to extract this mysterious substance.\n\nThe Warchief has insisted that you personally oversee the extraction efforts in Silithus and prevent the Alliance from interfering.\n\nGallywix seemed less than pleased with your appointment, but nobody refuses Sylvanas...\n\nYou must go to Silithus at once. The base commander is awaiting your arrival.", objectives = "Speak with Grol Warblade in Silithus.", completion = "Greetings, <name>. I was told you'd be coming. The mining operation is currently underway." }
WordHunterWoW_QuestEN[49985] = { title = "Return to Gloom Hollow", description = "Old God G'huun behind destruction of this seal. Commanding blood trolls to destroy final one within Zuldazar.\n\nTitan Keeper Hezrel must aid in destruction of blood trolls. Cannot allow Zuldazar seal to be destroyed and G'huun to be freed.\n\nMust leave interior of Atul'nazman. Meet Titan Keeper Hezrel outside of temple, will help return to Gloom Hollow.\n\nWhen task is complete, Titan Keeper Herzrel must establish contact with other keeper within G'huun containment chamber.", objectives = "Meet Titan Keeper Hezrel outside of Atul'nazman to return to Gloom Hollow.", completion = "We have everything we need to go after de blood trolls. We need to get moving." }
WordHunterWoW_QuestEN[49991] = { title = "Featherfeet's Fun Falling's Fun Fee!", description = "Welcome to Zuldazar, my fine {race} friend!\n\nI've explored every inch of this wonderful city with my own two feet. And let me tell you, they're tired!\n\nThat's why I've decided to provide a service to my powerful friends in the Horde: Featherfeet's Fun Falling!\n\nNow, I know what you're thinking. You nomrally associate falling with screams, pain, and an untimely death.\n\nBUT NOT WITH FEATHERFEET!\n\nFor a small one-time fee, I'll make sure you always float down this ziggurat shrouded in safety and fun.", objectives = "Pay 100 gold to Quinsy Featherfeet and he'll cast Slow Fall on you whenever you're nearby." }
WordHunterWoW_QuestEN[49994] = { title = "Sliding with Style", description = "", objectives = "" }
WordHunterWoW_QuestEN[49995] = { title = "Fabricated Fabrications", description = "There was somethin' off with the ship we were building in the yard. I never saw the blueprints, but I've built enough ships in my day to know it wasn't business as usual.\n\nThey've kept all the pages under tight guard in the Brineworks up the road lately. Full on militia.\n\nIf you can get your hands on enough of them pages, we oughta be able to figure out what Lord Stormsong and his boys are schemin'.", objectives = "Recover 8 Warship Blueprints.", progress = "Any luck recovering those blueprints?", completion = "I knew they'd still have 'em! If you ever want something gone, lad you'd best destroy it yourself." }
WordHunterWoW_QuestEN[49996] = { title = "Rearmament", description = "The people of this valley have true hearts, {name}. They're eager to take back control of their home.\n\nWe have to help them.\n\nThe Brineworks up the road from here supplies most of House Stormsong's weapons. Our movement here could make great use of them.\n\nIf you can collect enough to go around, I'll go over some basic training with our friends here.", objectives = "Collect 12 Stormfused Weapons.", progress = "There are still many who don't follow Lord Stormsong. We need to stand by them.", completion = "This valley belongs to its people. We must fight to make it whole again!" }
WordHunterWoW_QuestEN[49997] = { title = "Storm's Judgment", description = "When I opened my mind to the currents during the ritual, I felt the presence of a member of Lord Stormsong's innermost circle.\n\nWavespeaker Reid. If anyone can locate the missing fleet, it is him.\n\nI will not stand by while my brothers move against our own people. Oaths be damned.\n\nWe must force Reid to see reason.", objectives = "Confront Wavespeaker Reid.", progress = "This must be done.", completion = "I never thought Reid would succumb to darkness. Things are worse than I feared." }
WordHunterWoW_QuestEN[49998] = { title = "Voices Below", description = "The others forged ahead to Port Fogtide. I doubt they will receive a warm welcome. \n\nWe are to meet them there. However, there is something I must do first.\n\nDespite Reid's retreat I still feel a terrible darkness nearby; I wish to listen to the tides for answers. I would appreciate your joining me in case more danger strays into our path.", objectives = "Help Brother Pike investigate his omen.", completion = "We must help the others before they are overrun!" }
WordHunterWoW_QuestEN[50000] = { title = "Beastly Dealings", description = "", objectives = "" }
WordHunterWoW_QuestEN[50001] = { title = "Breaking Hag", description = "The town is overrun! \n\nThe guards have fallen back and what is worse, some of the villagers have been twisted by the witches' magic. They are little more than wretched beasts blindly following orders. \n\nWe must release these poor souls and slay the monsters that twisted them!\n\nSee what you can do to cut down the numbers of monsters in town!", objectives = "Kill 15 Briarwood Creatures and Witches.", progress = "We have a little breathing room.", completion = "Well done. You've thinned their numbers." }
WordHunterWoW_QuestEN[50002] = { title = "A Very Precious Cargo", description = "We weren't the only ship in our convoy to get caught up in this mess. Our flagship ran aground to the east. It was holding a very precious cargo and I need you to bring it back here.", objectives = "Find the \"Precious\" cargo in Fogcliff Strand.", completion = "Who are you? Where's my dad? I'm hungry. Can I have a sword? Where's my dad?!" }
WordHunterWoW_QuestEN[50003] = { title = "The First Watch", description = "As you can see, the coven has conscripted my own guardsmen into their service. Though I am loath to battle my own, these men are too corrupted by the coven's magic to be saved.\n\nFor them, death is the only mercy we can give.\n\nThe Inquisitors and I can handle the regiment stationed outside. We will need you to find and take out their leader.\n\nYour Inquisitors await your command, {class}. Are you ready to take the tower?", objectives = "Defeat Sister Adela at Watchman's Rise.", progress = "We assault the tower at your command.", completion = "Well fought, <class>.  The tower is ours.\n\nNow, we should set our sights on Corlain proper!" }
WordHunterWoW_QuestEN[50005] = { title = "Hold My Hand", description = "Take me to my daddy this instant!\n\nWaaaait! You have to hold my hand...", objectives = "Escort Penny back to her father.", progress = "Where is she? Don't tell me you lost her.", completion = "You found my precious little sea star!" }
WordHunterWoW_QuestEN[50009] = { title = "Shipwreck Recovery Crew", description = "Fogcliff Strand is swarming with Sirens and Saurolisks! Clear them out and grab any remaining cargo from the ships.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "" }
WordHunterWoW_QuestEN[50026] = { title = "Save Our Shipmates", description = "Oh, thank the stars! Our ship ran aground and our men are in desperate need of help.\n\nFind Henry Hardwick down the hill at the shipwreck. He stayed behind to try and help the others.", objectives = "Find Henry Hardwick in Fogcliff Strand.", completion = "We need your help, sailor!" }
WordHunterWoW_QuestEN[50035] = { title = "Bret Test - SQL", description = "", objectives = "" }
WordHunterWoW_QuestEN[50036] = { title = "A Weapon of Old", description = "I've been studying the parchment Lady Lucille sent with you and have translated some of the older language. \n\nThey called it \"Liquid Fire\" and it was used to \"burn away the Drust\". Using this as a basis I believe we can adapt it to our needs. This is a complex recipe, but it just so happens I have everything we need to make this potent alchemical weapon!\n\nI will need your assistance in creating this. Would you be so kind as to help?", objectives = "Help Master Ashton create the Liquid Fire potion.", progress = "We'd better get cooking!", completion = "Wonderful! Smells a bit strong but I think it will burn those wooden constructs well! Now it's time to test it out." }
WordHunterWoW_QuestEN[50041] = { title = "A Pocketful of Shells", description = "You see the problem? No you don't.\n\nProblem isn't all these dang quilboar. Quilboar I can shoot all day. Been shootin' em all my life, since my pappy gave me my first gun. \n\nProblem is these pigs are tough. Tougher'n they've been before. Can't kill em like I used to, see? My new modified bullets just get stuck in them and they refuse to die!\n\nHere, take my knife. Go out there and kill some of the quilboar and get my ammo back. Then I can shoot the rest! I won't stop 'till there's none left to shoot!", objectives = "Collect 20 Salvaged Azerite Ammunition.", progress = "Pretty sure I'll have to start shootin' my dinnerware, and I only have three sets. Hurry up, will you?", completion = "Good! I can keep shooting, and they can't get to me! This is really the perfect setup." }
WordHunterWoW_QuestEN[50043] = { title = "Archaeological Efficiency", description = "Miss Tae'shara and I share a passion for uncovering hidden secrets and a deep, abiding respect for this ancient land.\n\nThat said! If we were to continue at the pace to which she is accustomed, the Alliance would overtake us before we could make a single discovery. \n\nIt is time to expedite our survey.\n\nThe ruins hide many fossils. Take a beacon and use it to summon one of my sweepers. It will clear away the topsoil and allow you to collect samples.\n\nGather what you can- we can assemble them later.", objectives = "Collect 50 Xibalan fossil fragments.", progress = "I simply see no reason to dirty our hands, <name>.", completion = "Hm. These are a little... broken, don't you think?\n\nAh, well, nothing a little magic cannot fix." }
WordHunterWoW_QuestEN[50044] = { title = "Archaeological Efficiency", description = "Suppose I owe the lass her bones if I'm tae be monopolizin' yer time. And I will be.\n\nGo on out into the ruins an' use this here stone to call one of my rumbly elemental friends. They'll blast away any dirt 'tween you an' the fossils.\n\nWe could go about this the ol' fashion way, but do you really want to spend all day digging? Course ye don't.\n\nAcadia will see that a little efficiency gets everyone what they want.", objectives = "Use the Elemental Summoning Stone to expose Xibalan fossils. Bring 50 Xibalan Fossil Fragments to Acadia Chistlestone.", progress = "<Acadia eyes Morgrum sourly.>\n\nI don't think he cares one lick about our expedition, <name>.", completion = "<Acadia stares at the fragments, dismayed.>\n\nI'll just... clean these up... See what we can salvage.\n\nThanks?" }
WordHunterWoW_QuestEN[50046] = { title = "It's a Sabotage", description = "The Horde has wasted no time in shamelessly extracting this mysterious ore from the great wound.\n\nLuckily for us, goblin engineering is not nearly as sophisticated as what we create in Gnomeregan! All it takes is a little bit of old fashioned dynamite to completely disable a goblin shredder.\n\nWhat unsophisticated machinery!\n\nTake these dynamite bundles and plant them on the inactive shredders around the mining camp.\n\nIt'll take those greedy goblins weeks to get back up and running again!", objectives = "Plant 10 dynamite bundles.", completion = "Great work, <name>! With the shredders sabotaged, the Bilgewater Cartel mining operation will grind to a halt!" }
WordHunterWoW_QuestEN[50047] = { title = "Free Samples", description = "The crown has ordered SI:7 to infiltrate the goblin mining operation and collect any information we can find on this mysterious new substance.\n\nMy agents have infiltrated the camp, but the clock is ticking and we need to get our hands on some extracted ore samples fast.\n\nIn other words, I need someone who can take the direct approach. Someone who can handle a fight against overwhelming odds and come out alive.\n\nTake the ore samples to Khargus Stonemantle for analysis when you return.", objectives = "Collect 8 Mysterious Ore samples.", progress = "What have ye got for me?", completion = "I've never seen anythin' like this before... I'll get to work examinin' it at once!" }
WordHunterWoW_QuestEN[50048] = { title = "The Seething Shore", description = "We've received reports of an island off the coast of Silithus that is ripe with Azerite deposits.\n\nIt is vital that we secure the island before the Horde learns of its existence.\n\nMaster Mathias Shaw is personally leading the expedition force and has requested that you report for duty. Good luck!", objectives = "Complete the Seething Shore battleground.", completion = "You made it back alive. That's good news, indeed! I trust the expedition went well?" }
WordHunterWoW_QuestEN[50049] = { title = "The Speaker's Perspective", description = "Sargeras has left a scar upon our world, {name}. A scar that will not soon heal...\n\nIt appears that the scars between the Alliance and Horde have yet to heal as well.\n\nToo many lives have already been lost fighting to save Azeroth from destruction. I will not stay and watch this world lose more.\n\nI have a request for you before I go. Take this letter to Magni Bronzebeard. He is in Silithus seeking a way to heal the wound.\n\nThe letter contains information that may prove valuable to him.", objectives = "Deliver Khadgar's letter to Magni Bronzebeard in Silithus.", completion = "Thank you for delivering Khadgar's letter ta me. I'm goin' ta need some time ta consider his words. If what he says is correct, we may be able ta save Azeroth... but at a great cost." }
WordHunterWoW_QuestEN[50052] = { title = "No Spies Allowed", description = "Hey {name}, I'm glad you're here.\n\nI'm in way over my head! Killer bugs, a strange substance... that GIANT sword sticking outta the ground... I don't have a good feelin' about this place!\n\nTo make matters worse, I've been gettin' reports of Alliance spies snoopin' around the camp!\n\nLook kid, the Dark Lady has plans for this mysterious ore and I ain't going to be the one to dissapoint her, know what I mean?\n\nGet over to the mining camp and take out those SI:7 spies before they ruin the whole operation!", objectives = "Kill 10 SI:7 Operatives in Silithus.", completion = "You did well, <name>... Crisis averted! But we better keep an eye out for reinforcements.\n\nIf this stuff is as valuable as Gallywix says it is, the Alliance is going to be all over this place in no time!" }
WordHunterWoW_QuestEN[50053] = { title = "Lazy Prospectors!", description = "I've been around long enough to know you can never trust a goblin with an orc's work.\n\nGallywix and his cartel may be serving the warchief, but we need to keep a close eye on them if we're going to get anything done!\n\nI've already noticed many of the workers loafing about and sleeping on the job. The Horde does not tolerate laziness!\n\nGet out there and put those lazy prospectors in their place!", objectives = "Motivate 10 Lazy Prospectors.", completion = "Hmmpf! I hope you didn't go easy on them. If it were up to me they'd be getting more than a simple beating!" }
WordHunterWoW_QuestEN[50054] = { title = "The Seething Shore", description = "We've received reports of an island off the coast of Silithus that is ripe with Azerite deposits.\n\nIt is vital that we secure the island before the Alliance learns of its existence.\n\nNathanos Blightcaller is personally leading the expedition force and has requested that you report for duty. Go with honor!", objectives = "Complete the Seething Shore battleground.", completion = "I'm pleased to see that you made it back alive. I'm sure you fought with honor!" }
WordHunterWoW_QuestEN[50055] = { title = "The Speaker's Perspective", description = "Sargeras has left a scar upon our world, {name}. A scar that will not soon heal...\n\nIt appears that the scars between the Alliance and Horde have yet to heal as well.\n\nToo many lives have already been lost fighting to save Azeroth from destruction. I will not stay and watch this world lose more.\n\nI have a request for you before I go. Take this letter to Magni Bronzebeard. He is in Silithus seeking a way to heal the wound.\n\nThe letter contains information that may prove valuable to him.", objectives = "Deliver Khadgar's letter to Magni Bronzebeard in Silithus.", progress = "What do ye have for me, <class>?", completion = "Thank you for delivering Khadgar's letter ta me. I'm goin' ta need some time ta consider his words. If what he says is correct, we may be able ta save Azeroth... but at a great cost." }
WordHunterWoW_QuestEN[50056] = { title = "The Speaker's Call", description = "I been travelin' the land, seekin' out anyone who might know how ta heal Azeroth. I've consulted ancient sages, druids, shamans... from dragons ta titan keepers. Nobody's seen anythin' like this before.\n\nWent ta Karazhan ta speak with Khadgar. Studyin' those old tomes o' his, we came up with an idea. No tellin' if it's gonna work, but we gotta try.\n\nCome ta Silithus. Meet me at the wound. Time is runnin' out fer Azeroth, $p.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Meet Magni Bronzebeard at the Wound in Silithus." }
WordHunterWoW_QuestEN[50057] = { title = "The Power in Our Hands", description = "That sword of Sargeras is surgin' with dark energies. They're seepin' into Azeroth's heart like poison.\n\nThe blade's power must be snuffed out.\n\nThe Pillars o' Creation could do it, but they're keepin' the tomb sealed. So we need other vessels capable o' harnessin' vast energies.\n\nVessels like those artifact weapons you and the other champions wield.\n\nIt's a risk, $p. We don't know what Sargeras' power will do ta those weapons. But unless we act now, the heart of Azeroth is sure ta die.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Go to the Sword in Silithus and draw its power into your artifact." }
WordHunterWoW_QuestEN[50058] = { title = "The Witch's Pet", description = "I've seen her! The witch!\n\nEvery once in a while she comes down to the cave, checking on her pet. I've never seen a spider so large!\n\nShe spreads her spell, cursing all of the animals in these woods to follow her command and attack us.\n\nThe broodmother laid all these eggs, and they're hatching into more possessed beasts!\n\nTake her out, and perhaps the infestation will stop.", objectives = "Kill the Mossfang Matriarch.", completion = "<With the spider matriarch defeated, the flow of cursed spiders should slow, if not stop completely.>" }
WordHunterWoW_QuestEN[50059] = { title = "Can't Hear A Thing", description = "These snake wenches show up and everyone loses their minds! All my men are head over heels for these things. Personally, I don't see it. I mean, I sort of get the appeal, but the wings for arms and snake tails are a big turn off.\n\nThere's a big one in a cave to the east. She's got a whole heap of suitors. I need them back to work. Go give her a wallop and get everyone back here.", objectives = "Kill Anthemusa.", completion = "I decided if you can't beat 'em, join 'em! That one over there looks available. Think she'll go out with me?\n\nOh, and thanks for getting everyone back at their posts. We got a lot of cleanup." }
WordHunterWoW_QuestEN[50063] = { title = "Fighting With Fire", description = "Excellent! Now that we have these lovely Liquid Fire flasks prepared we have one last thing to do:\n\nTest them out!\n\nThere are some of those large abominations lurking about in the woods above my home. I think they would make excellent test subjects for our little alchemical experiment, wouldn't you say?", objectives = "Test the Liquid Fire flasks on 3 Briarwood Bulwarks.", progress = "Help!", completion = "I tried to stop them but I couldn't. They've taken Master Ashton into the woods!" }
WordHunterWoW_QuestEN[50064] = { title = "Don't Go in the Basement", description = "We checked everywhere... well, <gulps> everywhere except the basement.\n\nB-b-but, dad told me never to go down there.\n\nHe said it's dark, scary, and dangerous to go alone... I could be eaten by a brue!\n\nI don't even know what that is, but I don't wanna be eaten! \n\n{name}, do you think you could go down first?", objectives = "Enter the basement.", completion = "The brue, I saw it. He didn't make it up!!" }
WordHunterWoW_QuestEN[50065] = { title = "A Reason to Stay", description = "<You find a pocketwatch on the ground. It is dirty, but still works. It was taken care of well.\n\nPerhaps there are other objects that Goldfield wasn't able to grab before he had to hole up in his house. He might appreciate it if you brought them to him.>", objectives = "Search the Goldfield Farmstead for additional keepsakes.", progress = "For the last time, I'm not leaving! I was here first, THEY can leave!", completion = "You... you found them. I..." }
WordHunterWoW_QuestEN[50069] = { title = "Goldfield's War", description = "I'm not leaving. I'm never leaving.\n\nThose quilboar, they killed them. I gave her the watch, told her to hurry. Grab our boy and get to the house while I got the gun...\n\n<Goldfield is choking back tears.>\n\nI won't leave. Our family has our roots here. They would want me to stay, don't you understand? This is our farm. My boy, he wanted to join the militia. I made him a sword...\n\n<Goldfield takes a deep breath.>\n\nNow you know. Help me retake my farm. Grab a gun and let's kill every last one.", objectives = "Defeat the quilboar invaders.", progress = "This is MY home!", completion = "It's done. My family is avenged." }
WordHunterWoW_QuestEN[50070] = { title = "Detective Mildenhall", description = "Hmm... okay, okay, let's think.\n\nIf you were my dad and you accidentally set loose a bunch of honey monsters all over the place, what would you do?\n\nWell, okay, you would probably beat all of them up. But he probably ran away.\n\nIf he left in a hurry, maybe he left something for us to find.", objectives = "Search the Mildenhall Meadery for clues.", progress = "Did you find anything else?", completion = "Hmm... we checked everywhere." }
WordHunterWoW_QuestEN[50071] = { title = "For the Light!", description = "The Lightforged Draenei will be happy to join the Alliance.\n\nOur cause is now yours, {name}.\n\nLet us return to Stormwind. Captain Fareeya will speak with our people.", objectives = "Return to Stormwind and speak with Aysa Cloudsinger to hear the end of his tale.", completion = "The stories of the Lightforged echo throughout the streets of Stormwind. An army of elite soldiers dedicated to fighting the Legion... they will be one of our strongest allies." }
WordHunterWoW_QuestEN[50074] = { title = "Brutal Boost", description = "The Aggression Formula is ready and I need you to inject Ben'jin with it. \n\nLet's show the world, and the witch doctor, that well researched, dramatically overpowered, double-blind, peer-reviewed, super goblin science is the right way to do, uh, pretty much anything!", objectives = "Administer the Aggression Formula to Gentle Ben'jin.", progress = "This is exciting, isn't it?", completion = "I spent several moments working out that formula! It should have worked! The reason these brutosaurs are endangered is clearly their unreasonable resistance to science!" }
WordHunterWoW_QuestEN[50076] = { title = "Rally the Warriors", description = "We have learned so much and came so far thanks to you and de Horde, but all of it will amount to nothing if de blood trolls defeat us here.  \n\nWe've all worked hard since we first set foot within dis accursed swamp, without a chance to even get any sleep or have a decent meal. Dey are some of de finest soldiers I've ever encountered, but even dey have their limits.  \n\nLet us remind dem what we are fighting for!", objectives = "Ring the Ancient Gong.", progress = "We must carry on. De fate of my home is in our hands.", completion = "We are ready. Now, it is time for us to bring our fight to de blood trolls!" }
WordHunterWoW_QuestEN[50078] = { title = "Undying Totems", description = "De blood trolls are putting up quite de fight. Dey are raising de very dead to go against us!\n\nTheir necromancers are raising de dead with de help of totems fueled with blood magic. Destroying dem should take de pressure off our troops.", objectives = "Destroy 3 Reanimating Totems.", progress = "Why are you talking to me when those totems are still out dere?", completion = "Good work, dat should make things easier on us." }
WordHunterWoW_QuestEN[50079] = { title = "Boom goes the Bomb", description = "Just look at 'em... those blood trolls are holed up pretty good down there in that fortress of theirs. Multiple defensive lines, lots of equipment, they got everything.\n\nThey're completely unprepared for us! I almost feel sorry for 'em!\n\nLet's start off by showing 'em what we think of their cute attempts at making barricades. Here, take these smoke grenades and put a signal right on top of them. We'll see how well they hold up to high explosives!", objectives = "Call artillery strikes on the Blood Troll Barricades in Zul'Nazman.", completion = "Good job! Now we can move deeper into dis den of evil." }
WordHunterWoW_QuestEN[50080] = { title = "Raiding the Raiders", description = "", objectives = "" }
WordHunterWoW_QuestEN[50081] = { title = "The Road of Pain", description = "My people continue to be captured and hauled into de blood trolls' village for de slaughter, to be used as fuel for their dark rituals. \n\nJust ahead, I can see some of de captives who fell along de path. I hear their cries as de blood trolls perform their vile rituals upon dem.\n\nWe cannot leave my people to die in de swamp, {name}!\n\nTake dese bandages and save any Zandalari you encounter down dere.", objectives = "Save 6 injured Zandalari Soldiers.", progress = "Were you able to help de others?", completion = "Our soldiers will return home stronger, wiser, and most importantly, alive.\n \nOn behalf of my people, I thank you." }
WordHunterWoW_QuestEN[50082] = { title = "Target of Opportunity", description = "It seems our actions here have not gone unnoticed, {name}. I feel a dark presence ahead.\n\nAteena is near! \n\nDis is our chance! If we strike now, we can deal a huge blow to de blood trolls!\n\nWe must move!", objectives = "Confront Grand Ma'da Ateena.", completion = "She is... so much stronger than I expected. But, we have some surprises of our own! \n\nLet us bring up dis gun of yours and see how well it performs." }
WordHunterWoW_QuestEN[50083] = { title = "The Crawg Ma'da", description = "No matter what we do, as long as dem blood trolls have their village here, dey gonna be a threat.\n\nWe gonna put an end to dat threat!\n\nAmaka be da strongest blood troll I ever seen, and she be right across da way there. She be feedin' da bodies of da Zandalari ta her pet crawgs, makin' dem big, fat, and deadly. It be time for revenge, and we be doin' it wit' da help of her own pets.\n\nGo kill a crawg and cut its poison gland out of its belly. With it, ya can weaken Amaka and put an end to her.", objectives = "Obtain a Crawg Poison Gland and slay Amaka the Crawg Ma'da.", completion = "Well done, <name>! \n\nDa blood trolls gonna be hurtin' wit' da death of their general. Now, let's keep da pressure on dem!" }
WordHunterWoW_QuestEN[50084] = { title = "Back On Your Feet, Soldier", description = "I figured any soldiers we be coming across might be wantin' some revenge, so I brought along some extra weapons just in case.\n\nSee up ahead? Dem cages be full of trolls awaitin' der turn ta die. We gonna swoop in der and be da answers to der prayers!\n\nGo and arm as many of dem as ya can, revenge gonna be sweet!", objectives = "Give weapons to 10 Zandalari Captives." }
WordHunterWoW_QuestEN[50085] = { title = "A Message of Blood and Fire", description = "Look at what I be findin' here. Dis one had a magic wand in his hand.\n\n<Rokhan shuts his eyes for a moment.>\n\nMmmmm... it be warm. Mojo of fire be within. Perfect!\n\nTake dis ting an' give 'em a taste of their own firepower.\n\nBurn da whole village down!", objectives = "Use the Wand of Embers to set ablaze 8  Blood Troll huts in Agwamar.", completion = "Good job, mon. Justice be served." }
WordHunterWoW_QuestEN[50087] = { title = "Ateena's Fall", description = "You have proven to be a much greater ally dan I could have ever hoped. Thanks to you and your Horde, we have come dis far. Now, there is only one thing dat remains. \n\nWe must confront de leader of de blood trolls and put an end to their dark plot once and for all.\n\nWithout Ateena's mojo to protect it, we can finally destroy dat monstrosity of theirs before it can be unleashed upon Zuldazar. \n\nYou know what must be done. \n\nFirst, I must prepare myself. Go. I will join you when de battle has begun.", objectives = "Slay Grand Ma'da Ateena.", completion = "Finally, our battle here is done!\n\nMore importantly, you have made good friends with de tortollans and have gained powerful allies in de loa. I feel dat we will need to call upon their aid in de future.\n\nIt is time for me to return to Zuldazar and let my father know of our victory. \n\nDo you hear dat? Rokhan appears to have a message for us." }
WordHunterWoW_QuestEN[50088] = { title = "Golden Fields Forever", description = "I can take care of the rest. That ettin would have given me trouble if I was by myself, so you have my thanks.\n\nI would ask you for one more favor.\n\nMy wife, she loved the carnations that grow by the water's edge. If you could gather some, there's a nice spot under a tree by the river. We loved to go there when the sun set after our days in the fields.\n\nOur boy would run around, catching bugs, making reed whistles...", objectives = "Lay Farmer Goldfield's family to rest.", progress = "That's that, then.", completion = "Thank you, <class>. They will rest now." }
WordHunterWoW_QuestEN[50090] = { title = "Building Defenses", description = "We'll be able to push those monsters back now, but my defenders won't stand a chance unless we build a forward barricade for protection.\n\nThere should be plenty of lumber to build a barricade near the entrance to town.", objectives = "Collect lumber to build forward barricades.", progress = "We've pushed the front line out. That will give us some room.", completion = "Thank you. We'll be better able to protect the town." }
WordHunterWoW_QuestEN[50091] = { title = "Village Repair", description = "", objectives = "" }
WordHunterWoW_QuestEN[50092] = { title = "Curiously Strong", description = "I imagine the fires spread while I was down here, yes? First order of business then; making sure the town doesn't burn down! Help solve that problem and I shall be free to assist you in... whatever it is?\n\nLet's see... Yes! Here! Take these. They proved to be bit too... intense for most people, but you seem like a stout sort.\n\nJust be sure you're facing the fires when you use them, and I'm certain those fires will be out in no time!", objectives = "Use the Frost Breath Potion to put out the fires.", progress = "If we don't stop the fires, they could spread!", completion = "Ah wonderful! The fires are out and your breath smells minty fresh!" }
WordHunterWoW_QuestEN[50110] = { title = "Bearers of Bad News", description = "We must report this attack to Lord Admiral Katherine Proudmoore and prove to her that Lady Ashvane is behind it.\n\nIt won't be easy... Lady Ashvane and Katherine Proudmoore have been close friends for years.\n\nQuickly, let us make for Boralus!", objectives = "Return to Boralus with Taelia.", completion = "It seems word of the attack has already reached Boralus." }
WordHunterWoW_QuestEN[50111] = { title = "Totems, Totems, Totems!", description = "<This totem pulses with energy, releasing it into the nearby idols and thorns.\n\nIt looks rather fragile... It would be a shame if something happened to it.>", objectives = "Destroy the Brambleguard Totems in Briarback Kraul.", completion = "Good idea! Smashing those will distract their mystics and set back their expansion." }
WordHunterWoW_QuestEN[50112] = { title = "Casting the First Stone", description = "Hey dere {name}, gimme a hand with dis, would ya?\n\n<Kumali motions you over to her.>\n\nI got dis recipe dat I've been trying to remember de rest of, but I'm having de hardest time coming up with de right ingredients.\n\nYa see, my partner ran off with de other half of de recipe on account of a disagreement we had. But dis stone, it's a treasure like no other.\n\nGrab some vials and start mixing dese ingredients together. Let's see if dey are de right ones.", objectives = "Craft a Potion of Durability and a Potion of Shifting States using the recipes given to you. You can find the ingredients you need in Kumali's shop.", progress = "I will never ask for de other half of de recipe back from dat... dat... imbecile. I'll figure it out, ya see.", completion = "Okay, <name>, let's see if dis works." }
WordHunterWoW_QuestEN[50113] = { title = "Ocular Extracts", description = "So dere's a creature in dese lands whose eyes are perfect for alchemical recipes.\n\nDey might just be de thing we need to finish dis project. Although, I don't remember seeing dem on de full recipe list de last time I saw it, ya see... But my memory isn't quite what it used to be.\n\nGah! I'm rambling too much. Get me some eyes, will ya, {name}?", objectives = "Gather 10 Razorwing Eyes and return them to Kumali. Then observe as she tries to make the stone with them.", progress = "Make sure to gather de eyes after de creature is dead, otherwise dey make de most horrible sound when ya try to take dem out.", completion = "Very good. Dese should be plenty!" }
WordHunterWoW_QuestEN[50114] = { title = "Hammering Out Information", description = "I guess you noticed it requires a special anvil to make it. And I suppose you want to know where to find a Khaz'gorian Smithing Anvil?\n\nWell, I don't know where you can find one, not to mention I never said you'd be able to actually craft the dang thing.\n\nNow if you wouldn't mind, I have more of these recipes to sell.", objectives = "Press Grix Barlow for more information about where to find a Khaz'gorian Smithing Anvil.", progress = "That recipe really is worth what you paid for it, regardless of whether you can craft it or not.", completion = "Alright, alright, fine! I'll tell you what I know." }
WordHunterWoW_QuestEN[50115] = { title = "Changing the Scenery", description = "Or maybe de problem is dat we don't need regular reagents. Maybe we need something dat only comes from being transmuted.\n\nAnything's worth a shot at dis point. Here is a recipe my old partner left behind.\n\nHe used to go out to de Slough and change de shrubs into bubbles, ya see.\n\nWhy, you might ask? 'Cause he loved transmuting everything. Part of de reason we never saw eye to eye.\n\nAnyways, bring me back some of dose bubbles and we'll see if we can use dem to make dis stone.", objectives = "Go to The Slough and transmute Barberry Shrubs into Shrubbery Bubbles and gather 6 of them.\n\nBring them back to Kumali and observe as she tries to use them to make the stone.", progress = "I've seen him using dem in lots of his projects, so there has to be some alchemical qualities to dem.", completion = "Dese bubbles seem...odd. But den again so is Zukashi." }
WordHunterWoW_QuestEN[50116] = { title = "A Possible Solution", description = "None of dese things are working. I can't believe I'm saying dis, but I think you're gonna have to find Zukashi.\n\nMaybe you could convince him to give up de other half of de recipe. He's pretty full of himself, but he isn't unreasonable.\n\nLast time I heard, he's staying in Nazmir near Gloom Hollow. Maybe it's best to tell him dis isn't about me.", objectives = "Travel to Nazmir and seek out Zukashi.", completion = "Who are you? Another one of Kumali's apprentices coming to learn de true art of alchemy?\n\nOr is dere someting else you're interested in?\n\n<You explain to Zukashi that you're researching a special transmutation stone and that he might be able to help you.>\n\nOh, dat thing, eh? Heh. Ya, dat's a fine thing to have.\n\nBut if you want de knowledge I have, you're gonna have to help me with someting first, little mixah." }
WordHunterWoW_QuestEN[50117] = { title = "A Deathly Draught", description = "De first thing I'd like you to do for me is to gather some deathshroom.\n\nDon't worry if you're not skilled at herbalism, they're very easy to pick. Dey typically grow where death lingers in the air.\n\nI'd try to de Frogmarsh to de southeast. De trolls dere have been making sacrifices of de creature dat inhabit de area.", objectives = "Collect 15 Deathshrooms.", progress = "Have you finally acquired my mushrooms?\n\nIt's a simple task, even for someone like you.", completion = "Well done, little mixah! Dat's plenty for what I need." }
WordHunterWoW_QuestEN[50118] = { title = "A Stone's Throw", description = "Now dis ingredient you might have some fun getting, little mixah. I'm gonna give you dese stones. They're able to turn things into other things.\n\nDose blood trolls, de ones giving de rest of us a bad name? Dey drink de weirdest things and it taints their bodies.\n\nI need their blood to finish my work here, but without de taint. Dese stones will turn dem into weaker creatures. Although, sometimes de stones turn dem into other things...\n\nBe careful with dem.", objectives = "Use the Bag of Transmutation Stones on blood trolls and kill them. Collect 8 Vials of Altered Blood from them.", progress = "Ya never know what you'll get with transmuting things until ya try. Ain't dat right?", completion = "How'd ya like dem stones? Pretty fun, ya?\n\nAnd dis is plenty of blood. Good job, little mixah." }
WordHunterWoW_QuestEN[50119] = { title = "Chemically Compounded", description = "Now dat I have everything I need, I can finish dis project. My latest transmuation will be my finest yet!\n\nBut dis is not de place to test it. It could draw too much attention.\n\nIf you want to see it for yourself, little mixah, meet me to de north. Dere is a cave dere dat should be a safe spot for testing dis out.", objectives = "Meet Zukashi at the cave he mentioned. And be ready for anything to happen.", completion = "This bag must have belonged to Zukashi. As you rummage through it, you see a slip of paper that appears to be torn.\n\nYou grab the parchment and begin reading." }
WordHunterWoW_QuestEN[50120] = { title = "A Recipe for Success", description = "Looking it over more closely, you're convinced that this must be the missing half of the recipe you came for.\n\nAn odd signature completes the recipe, signed, \"Silas Darkmoon\".\n\nKumali should be very pleased to see this once again.", objectives = "Bring the torn paper back to Kumali.", completion = "Ya did it, <name>! Dis is de other half of de recipe!\n\n\n\nHere. You take dis copy and don't lose it. I'll make another copy and keep it in a safe place.\n\nDis way, if one of us forgets it, we'll know how to get it back again, ya see? Also, you make a better partner dan Zukashi ever did. Pleasure working with ya, <name>." }
WordHunterWoW_QuestEN[50121] = { title = "Casting the First Stone", description = "Would you mind helping me out with something, {name}?\n\n<Elric motions you over to him.>\n\nYou see, I have this recipe that, well, I only have half of currently. I've been trying to remember the other half but just can't seem to recall it.\n\nMy EX-partner tore the recipe and ran off with the other half over a disagreement we were having. But the stone it makes is invaluable.\n\nHow about you grab some vials and start mixing the ingredients on this list. Perhaps together we can figure this out.", objectives = "Craft a Potion of Durability and a Potion of Shifting States using the recipes given to you. You can find the ingredients you need in Elric's shop.", progress = "I wouldn't dare ask for the other half back, not after what Quintin said to me. I'll get this mystery figured out, you'll see.", completion = "Let's give it a try, shall we?" }
WordHunterWoW_QuestEN[50122] = { title = "Ocular Extracts", description = "My next idea involves a creature whose eyes are useful for certain alchemical recipes. At least for potions they are.\n\nHopefully they're just what we need for this and there aren't any further... miscalculations. Although, I don't entirely recall seeing them on the recipe's ingredient list... but my memory isn't exactly as good as it used to be.\n\nOh, you caught me rambling. How about you get those eyes and I'll start making the preparations for them.", objectives = "Gather 10 Highlands Mauler Eyes and return them to Elric.", progress = "Oh, I do hope you gathered the eyes post mortem. Those creatures make the most awful sound if you try to extract them while they're still alive.", completion = "Very good. These should be plenty!" }
WordHunterWoW_QuestEN[50123] = { title = "A Recipe For the Ages", description = "Yo, {name}, over here! You've look like you've been hammering away for a while. I can smell the flux on ya!\n\n<Grix gives you a wide grin.>\n\nListen, I've got a recipe for the most amazing blacksmith hammer you've ever laid your eyes on. And I'd be willing to let it go for a bit of ore.\n\nRevlis ore to be exact. It's a little rare, but you can find plenty of it over in Gol Koval in Drustvar. The elementals there are practically made of it.\n\nBring me back a haul of it, and the recipe's yours!", objectives = "Bring Grix Barlow back 30 pieces of Revlis Ore from Gol Koval in Drustvar.", progress = "This recipe is probably worth a thousand, no TEN thousand gold! Blacksmiths all over will be envious of you, you'll see.", completion = "Yea, yea! That's the stuff!\n\nHere's your recipe, have fun with it." }
WordHunterWoW_QuestEN[50124] = { title = "Changing the Scenery", description = "The stone this recipe becomes is a transmutation stone. What if the missing reagents to make it come from something that's gone through the transmutation process?\n\nI'm willing to try anything at this point. Here's an old recipe my ex-partner devised.\n\nHe used to go out to Stormsong Valley, just south of the Highland Flats and change the shrubs there into bubbles.\n\nBring back some of those bubbles and we'll see if they're what we've been missing.", objectives = "Go to Stormsong Valley and transmute Barberry Shrubs into Shrubbery Bubbles and gather 6 of them.\n\nBring them back to Elric and observe as he tries to use them to make the stone.", progress = "I've seen him use those globes in some of his projects in the past, so there is clearly some alchemical properties to them.", completion = "These bubbles seem...odd. But then again so is Quintin." }
WordHunterWoW_QuestEN[50125] = { title = "A Possible Solution", description = "Nothing appears to be working. I can't believe I'm proposing this but I actually think we need to contact Quintin.\n\nWell, you should, as I doubt he'll speak to me. Perhaps you could convince him to part with the other half of the recipe?\n\nLast time I heard, he was staying in Drustvar near Arom's Stand. There's a lot of alchemists in those parts, but he shouldn't be too hard to find.\n\nBest not to tell him I sent you. He may not be as forthcoming with the recipe.", objectives = "Travel to Drustvar and seek out Quintin Whalgrene.", completion = "Who do we have here? I don't suppose you're an old apprentice of my little brother, Elric, come to learn true alchemy, are you?\n\n<You explain to Quintin that you're researching a special transmutation stone and that he might be able to help you.>\n\nOh, interested in making one of those, are you? Well, just like transmutation there must be some equivalent exchange.\n\nYou're going to have to do some things for me first. You can have the pleasure of being MY apprentice." }
WordHunterWoW_QuestEN[50126] = { title = "A Deathly Draught", description = "The first thing I'd like you to do for me is to gather some deathshroom.\n\nDon't worry if you're not skilled at herbalism, they're very easy to pick. They typically grow where death lingers in the air.\n\nI'd try to the Crimson Forest to the south. The creatures that have overrun it seem to be covered in deathly magics.", objectives = "Collect 15 Deathshrooms.", progress = "Have you finally acquired my mushrooms?\n\nIt's a simple task, even for someone like you.", completion = "Oh yes, that's plenty for what I need. Well done, apprentice." }
WordHunterWoW_QuestEN[50127] = { title = "A Stone's Throw", description = "You may enjoy getting this next reagent for me. I have some special stones that have transmutative qualities, especially on living things. It's not too unlike the one you're trying to make.\n\nThe witches that plague these lands are imbued with magic. As is their blood.\n\nI need their blood to finish my latest project, but in an altered form. These stones should turn them into weaker creatures. Although, sometimes the opposite occurs...\n\nI'd recommend handling them with care.", objectives = "Use the Bag of Transmutation Stones on witches and kill them. Collect 8 Vials of Altered Blood from them.", progress = "You never truly know what a transmutation will yield until you try it. Wouldn't you agree, apprentice?", completion = "How did you find the stones? Fun, aren't they?\n\nOh, and this is plenty of blood. Well done." }
WordHunterWoW_QuestEN[50128] = { title = "Chemically Compounded", description = "That appears to be everything. This latest transmutation will be my finest yet. And your prize waits at its completion, apprentice.\n\nBut I don't believe this is an appropriate place to test it out. It may draw too much attention.\n\nThere's a cave not terribly far from here which would prove to be a more suitable setting for such a test.\n\nMeet me there when you're ready to witness why transmutation is the only branch of alchemy worth learning.", objectives = "Meet Quintin at the cave he mentioned. And be ready for anything to happen.", progress = "This seems to contain some of Quintin's things.", completion = "This bag must have belonged to Quintin. As you rummage through it, you see a slip of paper that appears to be torn.\n\nYou grab the parchment and begin reading." }
WordHunterWoW_QuestEN[50129] = { title = "A Recipe for Success", description = "Looking it over more closely, you're convinced that this must be the missing half of the recipe you came for.\n\nAn odd signature completes the recipe, signed, \"Silas Darkmoon\".\n\nElric should be very pleased to see this once again.", objectives = "Bring the torn paper back to Elric.", completion = "You have it?! I'm impressed you were able to get it from Quintin.\n\n<Elric grabs your half of the recipe and fetches a fresh piece of parchment. He begins copying down the information and once finished, walks back to you with it in his hand.>\n\nHere, this copy is for you. I'll make another copy for myself and keep it safe this time.\n\nIf you don't mind me saying, you've made a much better partner than Quintin ever did. It was a pleasure working with you, <name>." }
WordHunterWoW_QuestEN[50130] = { title = "A Friendly Gesture", description = "Life in the marsh has not been easy, {name}. We want to live in harmony with those that call it home, but our enemies out here threaten our existence.\n\nWork with us. Help the people of Sporeggar thrive.", objectives = "Reach Friendly with Sporeggar.", completion = "Thank you for helping the people of Sporeggar, <race>. You are always welcomed here." }
WordHunterWoW_QuestEN[50131] = { title = "An Outside Perspective", description = "Thank you for everything you have done for my people, but they are still scared of outsiders.\n\nFight the bog lords and rescue the spore sacs in the Spawning Glen. The future of my people is at stake!", objectives = "Reach Neutral with Sporeggar.", completion = "Thank you, <name>! Thank you." }
WordHunterWoW_QuestEN[50133] = { title = "Weed Whacking", description = "", objectives = "" }
WordHunterWoW_QuestEN[50134] = { title = "Gadgets and Gizmos Aplenty", description = "The militia may have given up on us, but we haven't given up on me!\n\nI'm a bit of a tinker, and I find that my harvest golems are better than any hired help I've ever had. They just need regular maintenance to keep running.\n\nOf course the Briarback are now taking over my fields, and my farmhands have gone into disrepair.\n\nIf you head out into the fields, can you grab the inner mechanisms from any of them that you find? That will stop them from exploding as well as help me plan my revenge.", objectives = "Collect 10 Harvester Gizmos.", progress = "Do you have the parts yet?", completion = "Perfect! With these parts I can rebuild my entire workforce. Or make one of them REALLY powerful." }
WordHunterWoW_QuestEN[50135] = { title = "Stop Vining!", description = "You may have noticed that the fields are a little... unstable right now.\n\nThe Briarback have been busy, growing those large bramble vines and boring tunnels underneath the farm. The vines have always been an important part of their borders, and they're expanding!\n\nGo down into the lower area and see if you can find who or what is making those vines grow. There's no way that they're growing like that naturally. If we can stop the vines we can retake this area!", objectives = "Slay the three Vinemasters.", completion = "Mystics using magic to shape the vines? I don't know much about magic, but I'm glad you stopped them." }
WordHunterWoW_QuestEN[50136] = { title = "Farming Stimulator", description = "The plants have gone amok since you defeated their masters! Don't worry though, I've got a plan.\n\nI've been busy fixing up one of the farmhands that didn't go completely haywire. It should have enough juice for one more trip through the fields.\n\nWe've got some serious technology in these harvesters. Their tools should be more than enough to take care of some small plants and even a couple quilboar.\n\nWhat do you say? You up for some farming the Stormsong way? Hop on in and get to work!", objectives = "Use the Piloted Farmhand to slay 30 enemies.", progress = "Take out as many of them as you can!", completion = "Yeah, that'll show them! Those quilboar will think twice before invading my farm again!" }
WordHunterWoW_QuestEN[50138] = { title = "The Battle of Bloodfire Ravine", description = "It is time to strike out and end de blood troll threat once and for all!\n\nWe travel back to Bloodfire Ravine, and dis time it is de blood trolls who will be sent running.\n\nMount up, and together we will show dem we are a force to be reckoned with!", objectives = "Take Bloodfire Ravine from the Blood Trolls.", completion = "You fought well! \n\nDe blood trolls are on de run. We must keep de momentum!" }
WordHunterWoW_QuestEN[50139] = { title = "The Missing Link", description = "<Though burned, portions of the note in the architect's hand remain legible.>\n\nThey are... everywhere... disguised...\n\nEncrypted... blueprints...\n\nCipher...\n\nPontus... watching me...\n\n<The cipher must be needed to read the ship blueprints. It seems Pontus is the likely holder.>", objectives = "Obtain the Architect's Cipher from Tideguard Pontus.", progress = "We need to get to the bottom of all this before Lord Stormsong goes on the offensive!", completion = "A cipher? Of course! But by the great sea, what's it covered in?!" }
WordHunterWoW_QuestEN[50149] = { title = "A Weather Eye", description = "It would be wise to get a lay of the land before we put together a plan of action. \n\nInquisitor Notley is an expert falconer, and a reliable scout. He utilizes an ancient relic to see through the eyes of his falcon, allowing him to survey great distances. \n\nUnfortunately, Notley was injured during the fighting. Nothing serious, but it's left him unable to concentrate enough to control his falcon.\n\nPerhaps you could help?", objectives = "Speak with Inquisitor Notley at Watchman's Rise to scout the areas surrounding Corlain.", progress = "What news do you bring?", completion = "It is good to know that there are still some left to save in Corlain. \n\nWe should focus our attention on them until we can devise a plan to bypass that barrier.\n\nI'll make sure to get this whistle back to Notley. Thank you, <class>." }
WordHunterWoW_QuestEN[50150] = { title = "Setting the Mood", description = "De voodoo love incense and romantic meal are ready, {name}. Take dem and place dem at de feet of Maka'fon. \n\nQuickly, if you could. Dat smell is... overwhelmingly, horribly, disgusting. \n\nCould you move any faster? \n\nAway. \n\nFrom us.\n\nFor de sake of de brutosaurs, of course.", objectives = "Place and light the Voodoo Love Incense near Irritable Maka'fon and offer her the Romantic Brutosaur Meal.", progress = "Best get dese stinking things over to Maka'fon soon, <name>. I guarantee it will get her in de mood.", completion = "I am an expert on love and all of my previous mates can attest to dat. I have misread de reason for Maka'fon's mood. \n\nDe razorwings ate her last clutch of eggs and she will make no more until she feels safe and avenged." }
WordHunterWoW_QuestEN[50151] = { title = "A Steady Ballast", description = "The Armory presents us a ripe opportunity, {class}... one I suggest we take.\n\nIf this battle were to draw out, we have little means to repair our arms and armor. A blacksmith is invaluable to any war effort, and Ballaster is one of our best.\n\nThe Armory is but a short ride from here. I suggest you get to Ballaster before it's too late!", objectives = "Find Angus Ballaster at the Corlain Armory.", progress = "The blacksmith won't survive long with the coven hunting him down. \n\nI'd recommend leaving posthaste.", completion = "Our fortunes are turning up. \n\nHaving a blacksmith at the tower will ensure our Inquisitors stay equipped for battle." }
WordHunterWoW_QuestEN[50152] = { title = "Digging for Scraps", description = "Well met, {class}.\n\nI hope you don't mind that I took the liberty to scout ahead and assess the situation at the armory.\n\nThe good news is that there still seems to be some salvageable arms left in the armory. The bad news, of course, is that the coven is after them as well.\n\nAdditional weapons could be a great boon to our cause. I recommend we take all we can carry.", objectives = "Collect 10 Quality Salvage from the Corlain Armory.", progress = "What did you find at the armory?", completion = "So the coven didn't completely clean out the armory? This is good news for us.\n\nEven the most common villager in Drustvar can hold their own in a fight. With these arms we can turn each person we rescue to another soldier on the line." }
WordHunterWoW_QuestEN[50154] = { title = "They Say It's a Delicacy", description = "A romantic meal is de way to set up an evening for love. Dis is true for us, so why not for Maka'fon? Bring her something rare and pleasing to her palate. \n\nDiemetrodons near de water eat hard seed pods and partially digest them. With a little voodoo, something magical can happen to de pods. It may be disgusting to you and I, but de brutosaurs consider it a rare delicacy. Such is life. \n\nDere are plenty of diemetradons, so some must die dat de brutosaurs might live. Such is de purpose of death.", objectives = "Obtain 25 Partially Digested Pods from the bellies of nearby diemetradons.", progress = "De pods we need become edible only in de belly of de diemetradons. Watch your fingers in dere... de scales are sharp.", completion = "De pods may be unpleasant to us, but de brutosaurs like dem just fine." }
WordHunterWoW_QuestEN[50157] = { title = "There's Gold in Them There Fields", description = "We've still got some folks missing, and I could use your help finding them.\n\nWhile Brennadam is now secure, I worry for some of our farms closer to the quilboar kraul. We relied on the militia in the past to keep the quilboar back, but now that they've retreated to the east I worry that our outlying farms are in danger.\n\nGoldfield's farm is almost directly south of us, up the hill by the falls. While it's not surprising that he hasn't left, I would feel better if you checked in.", objectives = "Find Farmer Goldfield at his farm.", completion = "Roz always worries about me. I keep tellin' her I'm fine up here, but she never listens..." }
WordHunterWoW_QuestEN[50158] = { title = "Checking Out the Collapse", description = "If you've got a minute, there's a farmer out there who hasn't made it back yet.\n\nName's Burton and he's out by a farm right next to Briarback Kraul. If the quilboar were to strike out, his farm is one of the first in their way.\n\nI haven't heard anything from Burton. He mostly relied on his mechanical farmers to help him, so we don't know the situation out there.\n\nHead to the west and keep an eye out for him, would you?", objectives = "Find Farmer Burton at his farm.", completion = "I stayed behind to see if I could help... Everyone else made it back okay, right?" }
WordHunterWoW_QuestEN[50161] = { title = "Recovering Raimond", description = "The map we found earlier had some red markings, near the flower field. \n\nDo you think you could go up there and look for dad?\n\nI'm going to stay here and check out the rest of this stuff. \n\nI'd go with you... but, I'm sort of allergic to bees.\n\nOh, and take his boot. Just in case!", objectives = "Find Raimond Mildenhall.", progress = "It is about time someone came looking for me!", completion = "Ahh, hah! Ancel sent you to find me, huh?\n\nHey, you found my boots too!? Marvelous!" }
WordHunterWoW_QuestEN[50162] = { title = "Sticky Situation", description = "The scientific breakthroughs I've made, marvelous, absolutely marvelous... I'm so close to perfecting the formula!\n\nThe way the honey grows and crystallizes, simply beautiful. Well, as you can see, that's also part of my current predicament.\n\nPerhaps you can lend me a hand? Just fetch some royal jelly from the hives outside.\n\nOh, don't worry about the bees, they are sweet, gentle things. \n\nThey don't sting... much.", objectives = "Collect 60 Royal Jelly.", progress = "You get all the jelly yet?", completion = "Hope you didn't have any problems with bees. No, of course not... why would you? \n\nThey're totally harmless." }
WordHunterWoW_QuestEN[50164] = { title = "Polly Want A Cracker?", description = "", objectives = "" }
WordHunterWoW_QuestEN[50165] = { title = "The Bee Team", description = "We need to put things in order, and the next item on the list is these blasted wendigos terrorizing the farm. \n\nIf we can cull their numbers, it should be enough to drive them off!\n\nI've synthesized a superb solution that might be just what we need to solvent this sticky situation!\n\nToss these bottles at your foes and our friendly little apoideas should come to help.\n\nWhatever you do, please don't spill any on yourself...", objectives = "Kill 12 Highland Maulers.", completion = "Hah! Did you see the look of sheer terror on their faces when they saw the bee swarms? \n\nMarvelous!" }
WordHunterWoW_QuestEN[50168] = { title = "Royal Succession", description = "I know, I know, okay... the farm is overrun by living honey and the bees have grown to massive proportions.\n\nI'll admit, things didn't quite go according to plan, but, extraordinary advancements in science do not come without some risk!\n\nI've been up here attempting to reduce aggression in the hive, an unfortunate side effect of my miscalculation, but I need another favor...\n\nYou're going to have to kill the Hive Mother and retrieve her stinger for me.", objectives = "Retrieve the Hive Mother's Stinger.", progress = "Oooh, ooh, do you have it!?", completion = "I'm glad you still have both of your eyes!" }
WordHunterWoW_QuestEN[50172] = { title = "Into the Crimsonwood", description = "Master Ashton has been taken into the forest. He isn't the only one. Mayor Royston's headcount came up short.\n\nIt seems our next steps are clear. We must go into the woods and save Master Ashton.\n\nMarten and I will sneak into the forest and meet you near some ruins further in.", objectives = "Meet Inquisitor Cleardawn in the Crimson Forest.", completion = "The woods are crawling with witches. We'll have a fight on our hands if we're to save Master Ashton." }
WordHunterWoW_QuestEN[50173] = { title = "Precious Metals", description = "{class}, I have another objective we should consider. \n\nThe Bleak Hills Mine is not too far from our location. Though the miners there principally extract iron, they do on occasion find silver among the veins.\n\nWe do not know the current state of the mine, but it's unlikely that the coven has passed it over. However, it would be worth braving whatever dangers lie there to recover some silver to use against them.", objectives = "Collect 10 Silver Nuggets from the Bleak Hills Mine.", progress = "Did you have any luck with the mine?", completion = "You found some silver? Excellent!\n\nThough it isn't much, any quantity of silver should help our efforts against the coven!" }
WordHunterWoW_QuestEN[50174] = { title = "All Wrapped Up", description = "While I was able to get out of the mine, some of my friends weren't so lucky.  I saw those spiders wrap them up in their webs... probably to save them for a snack.\n\nIt was terrible, but all I could do was run.\n\nWill you help them?", objectives = "Destroy Writhing Cocoons to rescue 8 Bleak Hills Miners in the Bleak Hills Mine.", completion = "You saved them!\n\nYou're certainly a hero in my book!" }
WordHunterWoW_QuestEN[50175] = { title = "An Eight-Legged Curse", description = "Some terrible old hag unleashed a swarm of these horrible spiders in the mine!  I was barely able to make it out alive, but they've got me surrounded!\n\nYou can't leave me here! Please kill those things!", objectives = "Kill 20 Bilefang spiders in the Bleak Hills Mine.", completion = "You... killed them!?\n\nOh thank you so much! It's been like a living nightmare in here!" }
WordHunterWoW_QuestEN[50177] = { title = "Hold The Barricade!", description = "{name} they're rallying for a heavy assault!\n\nWe'll need to defend these barricades from attack! Are you with me?", objectives = "Defend the barricades from attack!", progress = "That earned us some breathing room.", completion = "That witch! She must be the one guiding these attacks!" }
WordHunterWoW_QuestEN[50178] = { title = "Trouble in the Rootway", description = "", objectives = "" }
WordHunterWoW_QuestEN[50181] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[50187] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[50195] = { title = "Bilgemaul's Brigade", description = "<According to these orders, these assassins are being hired by a Sea Dog captain who is establishing a beachhead in Drustvar.\n\nTaking him out would deal a great blow to the Horde�s war effort, and might just put a halt to these ambushes.>You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Defeat Captain Bilgemaul in the Brackish Coast and loot his War Spoils." }
WordHunterWoW_QuestEN[50206] = { title = "Strike Back", description = "", objectives = "" }
WordHunterWoW_QuestEN[50226] = { title = "The Source of Power", description = "Although the silithid disappeared for a time immediately following the destruction of Silithus, they have recently returned from beneath the ground.\n\nThese new silithid seem stronger than before!\n\nMy hypothesis is that the silithid are feeding on some kind of power source beneath the blade of Sargeras.\n\nI've been tasked with studying the effects that this mysterious power is having on the silithid hives.\n\nBring me as many intact silithid brains as you can carry and I'll begin the research!", objectives = "Collect 10 Silithid Brains.", progress = "Do you have the brains?", completion = "Oh! Look at these big, beautiful brains! I can't wait to dig in... thanks for your help, <name>! You can stay and watch if you want, but it may get a bit messy!" }
WordHunterWoW_QuestEN[50227] = { title = "Larvae By The Dozen", description = "How did the silithid survive the blade of Sargeras? I'm perplexed!\n\nI've never encountered a species that can adapt to changes in the environment as quickly as the silithid can.\n\nThe larvae, or broodlings as they are often called, can evolve into a variety of silithid creature types based on the needs of the hive.\n\nIs it the hive mind that signals the evolutionary development of the larvae, or is some environmental factor at play?\n\nScience must find the answer!", objectives = "Collect 12 Silithid Broodlings.", progress = "Do you have the silithid larvae?", completion = "I see you have the broodlings! These will do nicely. Would you like to stay and watch me carefully dissect and catalog every detail of their anatomy?" }
WordHunterWoW_QuestEN[50228] = { title = "The Twilight Survivor", description = "Silithus used to be overrun with members of the Twilight's Hammer.\n\nThe cult was presumed to be exterminated, but it has always survived in the shadows. Their numbers have dwindled, but the cult remains no less fanatical than at their peak.\n\nMost of the cultists here were destroyed by Sargeras in the attack, but a few still remain. Their leader, Michiel Voidstrider has been emboldened by the destruction of Silithus.\n\nWe cannot let Michiel rally the remaining survivors to action. He must be stopped!", objectives = "Retrieve Michiel Voidstrider's head.", progress = "We cannot allow the Twilight's Hammer to regain their foothold in Silithus.", completion = "I see you have brought the head of Michiel Voidstrider. A gruesome task, but a necessary one. The Alliance thanks you for your service, <name>." }
WordHunterWoW_QuestEN[50229] = { title = "A Wee Bit O' Cloth", description = "{name}, is that you I hear rustlin' about out there? It's me, Angus Stormbrew!\n\nThere are cultists everywhere, so ye best keep yer voice down. Lean in close and cover yer nose while we talk!\n\nThis is the only outhouse in all o' Silithus! Trust me I spent hours lookin' all through the night. I decided to sneak in for a wee drop-off before the cultists woke up, but I've got a uhh problem...\n\nThere's no cloth to... you know...\n\nSee if ye can find me a wee bit o' cloth and sneak it in through the door!", objectives = "Collect 8 scraps of Twilight Silk.", progress = "Did ye acquire \"the goods?\"", completion = "Aye! This'll do nicely! Just give us a wee minute here..." }
WordHunterWoW_QuestEN[50230] = { title = "The Source of Power", description = "The silithid are all riled up and stronger than ever!\n\nMy guess is that they are feeding off of some kind of power beneath the ground. Probably near the blade of Sargeras!\n\nI've been ordered to study the effects that this mysterious power is having on the sillithid.\n\nBring me as many intact silithid brains as you can carry and I'll begin the research!", objectives = "Collect 10 Silithid Brains.", progress = "Hey kid! You got the stuff?", completion = "Holy moly! Look at the size of these big, beautiful brains! Where's my scalpel?! Wait... no... bring me the electric hacksaw. It's time for the big guns baby!" }
WordHunterWoW_QuestEN[50231] = { title = "Larvae By The Dozen", description = "How did the silithid survive the blade of Sargeras?!\n\nI've never encountered a species that can adapt to changes in the environment as quickly as the silithid!\n\nThere's gotta be a way to tame these suckers! Harness their evolutionary biology for our profit!\n\nWe gotta start training 'em young! Forget about the old crusty adults, we need babies!\n\nSteal me as many of the silithid larvae as you can carry, and I'll find a way to train 'em!", objectives = "Collect 12 Silithid Broodlings.", progress = "Do you have the silithid larvae?", completion = "You've got the larvae! These are gonna make us a boatload o' money! I can already hear the gold jinglin' in my pockets!" }
WordHunterWoW_QuestEN[50232] = { title = "The Twilight Survivor", description = "This land was once overrun with members of the Twilight's Hammer.\n\nThe cult was presumed to be exterminated, but darkness always survives in the shadows.\n\nMost of the cultists were destroyed by Sargeras in the attack, but a few yet live. Their leader, Michiel Voidstrider has been emboldened by the destruction of Silithus.\n\nWe cannot let this fanatic rally the remaining survivors to action! Bring me his head!", objectives = "Retrieve Michiel Voidstrider's head.", progress = "We cannot allow the Twilight's Hammer to regain their foothold in Silithus!", completion = "I see you have brought the head of Michiel Voidstrider. It will look glorious mounted on a spike! The Horde thanks you for your service, <name>." }
WordHunterWoW_QuestEN[50234] = { title = "Crews of Freehold", description = "", objectives = "" }
WordHunterWoW_QuestEN[50235] = { title = "No Safe Haven", description = "I brought Rastakhan to Zeb'ahari to hide him, {name}. I did not dream Zul's followers would find us so soon.\n\nDe people of Zeb'ahari are being hunted by those who answer to de prophet. I have brought dis upon dem by keeping de king in their village.\n\nHelp me save dem, {name}. Gather those who can still walk and send dem to me.\n\nI can do nothing for those who died, but we can still rescue de living.", objectives = "Rescue 12 Zeb'ahari villagers.", progress = "I hope we can get dem out.", completion = "I will try to help dem secure their village.\n\nStay sharp, <name>. Zul will not stop while ol' Rastakhan's fate hangs in de balance." }
WordHunterWoW_QuestEN[50238] = { title = "Bramblethorn", description = "I was playing with Lord and Lady Sharptooth when Papa made me come with him. I dropped poor Lord Sharptooth and one of those big mean monsters grabbed him! \n\nPapa said he'd try to get him back but he's been gone a long time. I think he got busy. Mama and all the adults are busy doing stuff for Mayor Royston.\n\nLady Sharptooth and I are really sad. Can you beat up that mean monster and save my dino?", objectives = "Slay Bramblethorn and retrieve Lord Sharptooth.", progress = "Did you find Lord Sharptooth? I think one of the really big monsters has him.", completion = "Yay! Oh. Y-you saw someone? My papa?\n\n<Lynn hugs her toy and sniffs>\n\nI haven't seen my Mama in awhile. I hope she's okay." }
WordHunterWoW_QuestEN[50239] = { title = "A Choice of Allies", description = "I was chosen to act as an ambassador to our new allies due to my experience with the pandaren joining the Alliance.\n\nI've made some notes about some potential allies that may be willing to join the Alliance.\n\nLearn more about them, then speak with me.", objectives = "Learn more about potential allies.", progress = "Hard choices must be made, <class>.", completion = "Your wisdom is always appreciated, <name>. The choice you make today will strengthen the Alliance." }
WordHunterWoW_QuestEN[50240] = { title = "A Slip of the Tongue", description = "<As you approach, the blind Zandalari motions at you impatiently.>\n\nIt sounds like ya be headed somewhere in a hurry, little weed!\n\nSit down and share a tale with an old troll before ya head out on ya next adventa.\n\nI went on many adventas with my pterrordax when I was young. Explored dis whole valley!\n\nMy pterrordax died many years ago, but...\n\n<Blind Tra'wala smiles mischievously.>\n\nSometimes at night, I steal da guards' snacks to trick dese old pterrordaxes into lettin' me ride again. Ha!", objectives = "Steal a Pack of Pterrordax Snacks and use them to ride a pterrordax deeper into the city." }
WordHunterWoW_QuestEN[50242] = { title = "A Choice of Allies", description = "As ambassador, it is my duty to bolster the Horde's ranks and strengthen our numbers in the face of danger.\n\nYour adventures have led you to many different people who can aid the Horde if we can convince them to join our cause.\n\nI've kept a record of the most promising potential allies. The choice of which to approach first is yours.", objectives = "Learn more about potential allies.", progress = "Is there a problem with my notes?", completion = "I have come to value your wisdom, <name>. The choice you make today will strengthen the Horde." }
WordHunterWoW_QuestEN[50247] = { title = "The Mail Must Flow", description = "Due to all of the recent shenanigans, I'm running short on mailementals to sort letters.\n\nIt's a simple job, really - just toss the letter into the proper portal, where it will be whisked away to the far corners of Azeroth and beyond.\n\nI like to make a little game out of it. How many can you sort in one minute?", objectives = "Help the Postmaster sort at least 15 letters within the time limit.", completion = "Well done! \n\nIs it not fulfilling? To see each letter safely to its destination?\n\nCome by and help any time!" }
WordHunterWoW_QuestEN[50248] = { title = "A Second Ally For the Cause", description = "You have taken an important first step in strengthening the Alliance, <name>. Well done.\n\nBut I fear a single new ally will not deter the Horde. The warchief will not rest until Orgrimmar's forces vastly outnumber the defenders of Stormwind.\n\nI must ask that you work to secure our next ally. We cannot afford any delay.", objectives = "Choose a second ally to pursue." }
WordHunterWoW_QuestEN[50249] = { title = "A Boralus Triple Threat", description = "If Tallis honestly thinks that offing a few random soldiers is going to force us to give up Southwatch, he's in for a surprise. The reason why we haven't chased out the sorry troops in this camp is simply because we have more pressing plans.\n\nFernn has his lieutenants facing the Watch's cannons straight at Boralus as we speak. Those three are the real driving force of the attack.\n\n<The marine gives you a concerned look as he realizes what he said.>", objectives = "Take out Fernn's three lieutenants.", progress = "What is it?", completion = "We finally got some useful information from him?" }
WordHunterWoW_QuestEN[50250] = { title = "Posthaste", description = "", objectives = "" }
WordHunterWoW_QuestEN[50251] = { title = "Spell Bound", description = "<The villager is held captive by a binding rune. Destroying the rune should free the villager.>", objectives = "Destroy 8 Binding Runes to free captive villagers.", completion = "I shudder to think what they would have used those people for." }
WordHunterWoW_QuestEN[50252] = { title = "Mating Season Halftime", description = "Cala and I have both failed. Voodoo and science did not work. I am at a loss.\n\nI hope dat you can help us find a better path forward. De brutosaurs deserve a chance! \n\nPlease spend a little time with both of us. Perhaps you can find de way dat we cannot.", objectives = "Strategize with Cala Cruzpot and Witch Doctor Janagalar on how to use voodoo and science to get the endangered brutosaurs to mate.", progress = "Please strategize with both Cala and myself to find a new plan to help de brutosaurs.", completion = "Thank you, <name>, for your help. Dis is de best of both worlds and de brutosaurs may benefit from it." }
WordHunterWoW_QuestEN[50253] = { title = "An Improvised Arsenal", description = "I don't know much about blacksmithing, but I'm pretty sure this won't be enough silver to outfit all of the Inquisitors.  We will need to find another way to use this.\n\nLet us hope that Ballaster can come up with something... creative.", objectives = "Speak with Angus Ballaster to create a silver weapon at Watchman's Rise.", progress = "What can ol' Angus do fer ye?", completion = "Ah, she's a beaut'! Back in the navy we used te stuff our muskets with scraps when we ran outta bullets. \n\nThis'll do the damage ye need, te be sure!" }
WordHunterWoW_QuestEN[50254] = { title = "A Second Ally For the Cause", description = "One new ally will prove useful. A second will make us even stronger.\n\nEven now, the Alliance plots and schemes against us. We must move quickly, or they will strike before we are prepared to counter their aggression.\n\nSay the word when you are ready to begin pursuit of our next ally. There must be no hesitation.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Choose a second ally to pursue." }
WordHunterWoW_QuestEN[50264] = { title = "Free the Farmhands", description = "We were running around trying to get the farm under control, but the bees, oh my goodness, the bees!\n\nThe giant monstrosities came out of nowhere and started dousing everyone in honey.\n\nI came up here to find Raimond, but before I knew it, I was covered too. \n\nThen, the strangest thing happened, the honey started growing around me!\n\nPlease, the other farmhands are still in trouble, you've got to help them!", objectives = "Rescue the Honey Encased Farmhands.", completion = "Encased in honey, just waiting to be eaten. That must have been absolutely terrifying!" }
WordHunterWoW_QuestEN[50265] = { title = "Saving Master Ashton", description = "I believe I see Master Ashton in a cage. He must be freed!\n\nThose witches with the long masks appear to be in charge. I bet they would have the means to open his cage.\n\nI will remain here to protect Apprentice Webb and keep the area secure.", objectives = "Take a key from a Hexwood Binder and free Master Ashton.", completion = "We had a few visitors while you were gone but I took care of them. \n\nAshton's back and safe, though it appears he's seen some of the horrors here." }
WordHunterWoW_QuestEN[50266] = { title = "Bittersweet", description = "Hey!\n\nI need to get out of here and get back to Falconhurst! My husband and I were looking for my daughter's favorite toy when I was taken. Please, I need to get out of here! I need to know my family is safe. \n\nThey took my gear. It's all around camp. Get me out of here then bring back my gear, please!", objectives = "Free Samantha Sweet then recover her gear.", completion = "Thank you. I'll cut a path back to Falconhurst. They will pay for what happened to my family!" }
WordHunterWoW_QuestEN[50268] = { title = "Give it a Little Juice", description = "Well, I admit that I feel a little better about this. If Witch Doctor Jangalar's voodoo can make Ben'jin react correctly, as the science says he should, then what do we have to lose? \n\nBless my formula or hex it or whatever they call it with Jangalar's voodoo cauldron.", objectives = "Put some voodoo on Cala's formula using Witchdoctor Jangalar's cauldron.", progress = "Will voodoo make it smell funny? Nevermind, idle musings.", completion = "The consistency is the same... does it seem a little carbonated to you now? \n\nCan't wait to see if this works better than the original formula which, I feel like I need to say, SHOULD have worked fine." }
WordHunterWoW_QuestEN[50270] = { title = "Deep In the Core", description = "Look, you're gonna have to travel to some place called Deepholm and find an earthen down there.\n\nThe guy who sold the recipe to me said he got it from an earthen called...Ormhun! Ormhun something.\n\nI don't know too much about that place, but maybe you can ask the locals or something where he lives.\n\nNow if you don't mind, I have more recipes to sell.", objectives = "Travel to Stormwind and take the portal to Deepholm. Seek out Ormhun Stonehammer when you arrive.", completion = "Looking fer me, are ya? And what can old Ormhun be helping a fleshy out with?\n\n<You explain to Ormhun that you're trying to find a Khaz'gorian Smithing Anvil.>\n\nHa! Good luck with that! I haven't seen one of those in, oooh... centuries.\n\nLucky for you though, I know how ta make one. And I like the look of ya.\n\nI suppose I could come out of retirement and help ya for one last craft. It's been so long, it'll be nice to work the forge again. Just gotta find me hammer..." }
WordHunterWoW_QuestEN[50271] = { title = "Smash and Grab", description = "Most of the materials we'll need can be found right down here in the Deepholm.\n\nWe just need ta be discreet about it. If old Therazane catches wind of what we're up to, she might try ta put a stop ta it.\n\nBut let's not worry 'bout that. The first thing you'll need is diaminium. There are pillars that grow in the Alabaster Shelf rich with 'em.\n\nJust use yer old blacksmithin' hammer and smash those pillars ta bits. Don't worry about breaking the diaminium. We'll meld it all back tagether.", objectives = "Go to the Alabaster Shelf and smash Diaminium Pillars. Collect 60 Diaminium.", progress = "This'll be fun! I haven't made one of those anvils in ages!", completion = "Oh, did the drakes hear you smashing? Ha ha! Yea, I suppose that'd get their attention.\n\nStill though, this'll be plenty of diaminium." }
WordHunterWoW_QuestEN[50272] = { title = "An Ear to the Ground", description = "The next reagent ya need comes from the bellies of worms that burrow through this realm.\n\nWhile ya can find plenty o' worms all over, there's a certain type you'll need ta find. They're rarely seen above ground, but there are ways of coaxing 'em out.\n\nNamely making enough racket to piss 'em off! Ha ha! When ya see 'em rumblin' around beneath ya, use this thumper to draw 'em out.\n\nDeliver a killin' blow and get that metal from their wee bellies!", objectives = "Go to the Jagged Wastes and look for signs of worms. They usually kick up lots of dirt as they move around.\n\nDrop a thumper to make them surface, then kill them and collect 30 Endurite from them.", progress = "It's been a while since I went worm huntin'.\n\nWe used ta jump up and down ta rile them up before we made tha thumpers.", completion = "Now ya can't say ya didn't have fun throwin' those thumpers around, am I right?! Ha ha!\n\nGood haul you brought in, too. Should be plenty ta work with." }
WordHunterWoW_QuestEN[50273] = { title = "Atal'Dazar: Locking Horns", description = "We've got tha metal for tha base and tha body, but there's one last part...\n\nTha horn of tha anvil was ta be made of ukrite. But that metal's been gone for ages.\n\nThere is another metal tha's very close ta it in terms of its durability. A type of gold tha trolls mined in abundance. And I know where ye can find it.\n\nTha trolls control an area called Atal'Dazar, a great city made o' tha stuff. If ye can find something horn-shaped in there, that'll save us tha trouble of shaping it from scratch.", objectives = "Go to Atal'Dazar and recover The Golden Horn of Rezan." }
WordHunterWoW_QuestEN[50274] = { title = "Titanic Forging", description = "Are ya ready, lad?\n\nYou'll be doing the hammerin' while I take care of the last reagent we'll need.", objectives = "Meet Ormhun near the Shuddering Spires and help him craft a Khaz'gorian Anvil.", completion = "Now you'll be able to craft some rather durable equipment. But best you be getting on yer way back." }
WordHunterWoW_QuestEN[50275] = { title = "Anvil's Away", description = "Take your anvil, and never speak of its methods of creation to anyone.\n\nShould I find out otherwise, you may find your next visit to my realm an unpleasant one.", objectives = "Bring the anvil back to Grix Barlow in Boralus.", completion = "Wait, what?! You actually got one? And you brought it back here?!\n\n<Grix's eyes widen as you drop the anvil down next to him.>\n\nDo you know what this means? It means I can start charging DOUBLE for the recipes!\n\nThank you, <name>. You're an amazing blacksmith!" }
WordHunterWoW_QuestEN[50276] = { title = "A Recipe For the Ages", description = "Say, ya look like you been swingin' da hammah around quite a bit, brudda. I can smell da flux on ya!\n\n<Zak'aal gives you a wide grin.>\n\nListen, I've got a recipe for da most amazin' blacksmit hammah ya ever be layin' ya eyes on. And I'd be willing ta let it go for a bit of ore.\n\nRevlis ore ta be exact. It be a little rare, but ya can find some of it over at Atal'Gral. Da naga dere use it ta make deir weapons.\n\nBring me back a haul of it, and da recipe be yours!", objectives = "Bring Forgemaster Zak'aal 30 pieces of Revlis Ore from Atal'Gral in Zuldazar.", progress = "Dis recipe probably be wort a tousand, no TEN tousand gold! Blacksmits all over will be envious of ya, brudda.", completion = "Yea, yea! Dat's da stuff!\n\nHere be da recipe, have fun wit it." }
WordHunterWoW_QuestEN[50277] = { title = "Hammering Out Information", description = "Let me guess. You be lookin' at da recipe and noticed it require a Khaz'gorian Anvil ta make it. So now you be wantin' ta know where ta find a Khaz'gorian Smithing Anvil?\n\nLook, brudda, I never said anyting about bein' able ta craft da hamma. Now if ya don't mind, I have more of dese recipes ta be sellin'.", objectives = "Press Forgemaster Zak'aal for more information about where to find a Khaz'gorian Smithing Anvil.", progress = "Dat recipe really be wort what ya paid for it, no mindin' if ya be able ta craft it or not.", completion = "Easy, brudda. I'll tell ya what I know." }
WordHunterWoW_QuestEN[50278] = { title = "Deep In the Core", description = "Look, ya gonna have ta travel ta Deepholm and convince dem ta be givin' up deir secrets. Dat's where da last anvil was made, or so I be hearin'.\n\nAnd I only be knowin' of one earten down dere who might be willin' ta work wit ya. His name be Ormhun Stonehamma'.\n\nHe be kind of an outcast, but not too hard ta find.", objectives = "Travel to Orgrimmar and take the portal to Deepholm. Seek out Ormhun Stonehammer when you arrive.", completion = "Looking fer me, are ya? And what can old Ormhun be helping a fleshy out with?\n\n<You explain to Ormhun that you're trying to find a Khaz'gorian Smithing Anvil.>\n\nHa! Good luck with that! I haven't seen one of those in, oooh... centuries.\n\nLucky for you though, I know how ta make one. And I like the look of ya.\n\nI suppose I could come out of retirement and help ya for one last craft. It's been so long, it'll be nice to work the forge again. Just gotta find me hammer..." }
WordHunterWoW_QuestEN[50279] = { title = "Anvil's Away", description = "Take your anvil, and never speak of its methods of creation to anyone.\n\nShould I find out otherwise, you may find your next visit to my realm an unpleasant one.", objectives = "Bring the anvil back to Forgemaster Zak'aal in Zuldazar.", completion = "Wait, what?! Ya actually got one? And ya be bringin' it back here?!\n\n<Zak'aal's eyes widen as you drop the anvil down next to him.>\n\nDo ya know what dis means, brudda? It means I can be charging DOUBLE for da recipes!\n\nTank ya, <name>. You be an amazing blacksmit!" }
WordHunterWoW_QuestEN[50287] = { title = "Unending Gorilla Warfare", description = "", objectives = "" }
WordHunterWoW_QuestEN[50288] = { title = "Therazane's Choice", description = "<You explain that you meant no disrespect to Therazane or to steal their secrets.>\n\nInteresting...\n\nI have a wonderful idea on how to solve this issue. Would you like to hear it?", objectives = "Listen to Therazane's proposition.", progress = "To think a creature such as yourself would be freely given our secrets.\n\nI suppose I'll have to keep a closer eye on the goings on within my realm.", completion = "Your choice has been made. And an interesting one at that." }
WordHunterWoW_QuestEN[50295] = { title = "Like Pulling Teeth", description = "", objectives = "Kill 25 wendigo." }
WordHunterWoW_QuestEN[50296] = { title = "Billy Goat Barber", description = "", objectives = "Use the Goat Shears on 6 Gentle Goats." }
WordHunterWoW_QuestEN[50297] = { title = "The Head of Her Enemy", description = "You have done a wonderful thing, {name}. With de destruction of Gloomtail, Maka'fon is no longer bothered by de presence of de razorwings. It seems dat Gloomtail destroyed her eggs some time ago. \n\nTake Gloomtail's head to Maka'fon as proof dat he is gone. When she finds de scent of Ben'jin on it, she will once again seek a worthy mate. \n\nWhen Ben'jin senses dat, he will approach and nature will take over.", objectives = "Place Gloomtail's head in front of Maka'fon so that she knows her territory is safe and that Ben'jin is the reason.", progress = "Take Gloomtail's head and offer it to Maka'fon. Let us see what happens next.", completion = "Dis is a wonderful moment and I feel hopeful dat dis species of brutosaur will survive and thrive here in de jungle." }
WordHunterWoW_QuestEN[50299] = { title = "Gryphon Wranglin'", description = "", objectives = "" }
WordHunterWoW_QuestEN[50300] = { title = "The Speaker's Call", description = "I been travelin' the land, seekin' out anyone who might know how ta heal Azeroth. I've consulted ancient sages, druids, shamans... from dragons ta titan keepers. Nobody's seen anythin' like this before.\n\nWent ta Karazhan ta speak with Khadgar. Studyin' those old tomes o' his, we came up with an idea. No tellin' if it's gonna work, but we gotta try.\n\nCome ta Silithus. Meet me at the wound. Time is runnin' out fer Azeroth, $p.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Meet Magni Bronzebeard at the Wound in Silithus." }
WordHunterWoW_QuestEN[50303] = { title = "Stranger in a Strange Land", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", objectives = "Talk to Chromie in Orgrimmar.", progress = "Not quite as beautiful as Suramar, is it?", completion = "So this is Orgrimmar. The orcs have made some... interesting aesthetic choices. Be careful of the spikes, <name>.\n\nAnd the smells. So many smells." }
WordHunterWoW_QuestEN[50305] = { title = "Stranger in a Strange Land", description = "Welcome to Stormwind, {race}. I invite you to explore our fair city. Say, you look like someone who enjoys the night life. We have many popular taverns and a vibrant music scene! \n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of the ren'dorei is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay, {name}!", objectives = "Talk to Chromie in Stormwind City.", progress = "So, how does Stormwind suit you?", completion = "Welcome to Stormwind. Though it is no Silvermoon, the city does have its charms.\n\nIf you came here expecting a warm welcome, I cannot say I have received one myself. But most folk are polite enough.\n\nNo matter. I am off to seek adventure! And perhaps a stiff drink." }
WordHunterWoW_QuestEN[50306] = { title = "Odds and Ends", description = "Master Ashton's going to probably need something bracing once we get him free. I know of a quick potion guaranteed to get anyone to snap out of it, but I'm going to need a few things first.\n\nThose wicker dogs down there have some organic parts I can use and the witches are carrying bags of reagents. They'll almost certainly have what I need.\n\nBring those to me and I'll handle the rest once we get Master Ashton back.", objectives = "Collect 4 Organic Matter Samples and 3 Bags of Reagents.", progress = "Did you have any luck?", completion = "Hmm... Very interesting. And pungent. Perhaps my first order of business will be something to remove the smell." }
WordHunterWoW_QuestEN[50313] = { title = "Stranger in a Strange Land", description = "Welcome to Stormwind, {race}. I invite you to explore our fair city. Say, you look like the devout sort. We have a lovely cathedral that will no doubt be of interest! \n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of the Lightforged is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay, {name}!", objectives = "Find Chromie in Stormwind City.", progress = "I can feel the Light in this place.", completion = "Welcome to this beautiful city, <name>. I am sure you will feel as welcome by the other members of the Alliance as I do.\n\nI have met a number of the city guards. Good people, though there are a few things they could learn from us." }
WordHunterWoW_QuestEN[50315] = { title = "Not On the Itinerary", description = "", objectives = "" }
WordHunterWoW_QuestEN[50316] = { title = "Disturbance Detected: Ulduar", description = "You're late. Don't you remember the last time we had to deal with the tampering that allowed Yogg-Saron to escape from his prison underneath Ulduar? You were late then too. You should really try to be more punctual.\n\nWell, get going! Old gods! Keepers! Titan stuff! Get this one checked off your list so we can move on. We've got times and places to be.\n\n<Vormu gestures impatiently for you to leave.>", objectives = "Relive the expedition to Ulduar.", progress = "Exactly the same number of dwarves must be roasted as last time. Medium rare, of course - well done would be insanity.", completion = "Well this is worrisome. The Titan locks holding Yogg-Saron in place seem to have been artificially aged - these should have held for at least another forty millennia. The only ones with such power are dead.. aren't they? Or perhaps... no, that doesn't make any sense at all." }
WordHunterWoW_QuestEN[50318] = { title = "A Timely Summons from Northrend", description = "The blazing wanes in the shadow of a celestial mass, striking fear in to the seers. Seek out the sage Vormu in Dalaran, and lend her your aid.\n\nNo, not this Dalaran, the other one. Yes I know, it's terribly confusing.", objectives = "Meet with Vormu in Dalaran above Crystalsong Forest.", completion = "We're behind schedule - let's get moving." }
WordHunterWoW_QuestEN[50319] = { title = "Stranger in a Strange Land", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", objectives = "Talk to Chromie.", progress = "Not quite as beautiful as Highmountain, is it?", completion = "So many tauren! I think I've seen more tauren since I got here than in my entire life in Highmountain.\n\nThey all ask to touch my antlers. It's weird at first, but now I kind of like it." }
WordHunterWoW_QuestEN[50321] = { title = "Mojo Mischief", description = "De soldiers you rescued spoke of de raids on Zandalar. Blood troll raiders, frothing at de mouth and possessing supernatural strength, overwhelmed de defenders. \n\nDey say dat their strength came from flasks of mojo dat de raiders drink before going into combat. We cannot allow de blood trolls to continue to possess them.\n\nGo down into de camp and destroy any of their flasks you may find.", objectives = "Destroy 6 Flasks of Viscous Mojo." }
WordHunterWoW_QuestEN[50322] = { title = "A Feathery Fad", description = "", objectives = "" }
WordHunterWoW_QuestEN[50324] = { title = "Picturesque Fizzsprings Resort", description = "", objectives = "" }
WordHunterWoW_QuestEN[50325] = { title = "Stopping the Grand Rite", description = "The witches of the Crimsonwood are planning a Grand Rite, a powerful ritual. They intend to rip open reality and bring their dark master through!\n\nI suspect they may be in communion with Gorak Tul. We cannot allow their ritual to succeed.\n\nI need you to be the tip of the spear while I protect Master Ashton and Marten. Cause havoc and disrupt their rituals!", objectives = "Destroy the Ritual Foci.", progress = "Destroy the Ritual Foci.", completion = "Damn!. We've slowed them down, but they are still working. To fully stop them we'll need to do more." }
WordHunterWoW_QuestEN[50326] = { title = "Ain't No Place Like Home", description = "Let me tell you, this is a big place, this Arathi Highlands, and I've no doubt at some point you are going to need to quick step it back to our lovely new base.\n\nHow about I help you out with that?", objectives = "Talk to Wistel Silversnitch", completion = "You know what you need? You need a good, easy way to get back to me to buy your things whenever you want. I can help ya there." }
WordHunterWoW_QuestEN[50327] = { title = "A Little 'Pick Me Up'", description = "Now to mix this up. \n\n<Marten begins to combine the components in a mug>\n\nI'm using some rather strong grog as a base, a drop of chilli extract and a handful of hearthbloom... There!\n\n<Marten hands you a mug>\n\nIt will taste worse than it smells, but it will bring Master Ashton to his senses. Please give this mug to him.", objectives = "Give the mug to Master Ashton.", progress = "<Ashton stares into the distance, eyes wide, muttering under his breath.>", completion = "Oh! I say!\n\n<Ashton shudders and coughs>\n\nA bit less hearthbloom next time, Marten, but that did just the trick. Well done both of you." }
WordHunterWoW_QuestEN[50328] = { title = "Unconventional Aromatics", description = "A deal's a deal. You got the stingers for me, so here's that big batch of honey I promised.\n\nI hope you and Rhan'ka enjoy it... slowly. Seriously, do not eat this all at once.\n\nOh, and I'm always looking to trade. Swing by anytime you got something to sell or want to pick up some more honey!", objectives = "Deliver the Batch of Bilewing \"Honey\" to Rhan'ka at the Goldtusk Inn.\n\nProvided item:", completion = "Thank de loa dat de Sandfury didn't kill you and take dese.\n\nDe drinks are almost ready and dey really add the perfect flavor." }
WordHunterWoW_QuestEN[50329] = { title = "Matrons of the Crimsonwood", description = "The witches in charge, the matrons...\n\n<Ashton shudders for a moment then composes himself.>\n\nThe matrons are the ones leading the Grand Rite. They are fearsome but not invulnerable. Removing some of them from the equation will bolster our chances of stopping this. \n\nTake this potion. It will be able to weaken the matrons so you might have a better chance of dispatching them.", objectives = "Kill Matrons Elsbeth Garrick, Stefania Denholm, and Wilona Blackwood.", progress = "Did you kill them?", completion = "The potion worked even better than anticipated! It is heartening to know my time spent in the witches'... care has yielded positive results.\n\nLosing some of their leadership will certainly set them back." }
WordHunterWoW_QuestEN[50331] = { title = "A Different Outcome", description = "There is no way to know when these orders were sent, or received.\n\nRokor took some Seekers north some time ago. They must be in that region by now. \n\nIf the temple still stands, warn Gral and his followers.\n\nIf it is lost, we must do what we can.", objectives = "Find Rokor near Atal'Gral, to the north.", completion = "I fear those orders were found too late to help those that served here... about five years too late." }
WordHunterWoW_QuestEN[50332] = { title = "Big Hunter Mon", description = "In these valleys, the Mon be kepin' beasts alive only to serve as sport. For his entertainment.\n\nThe lives of others not be so cheap. Even the smallest creature can cause a whole lotta trouble. The Mon gonna be learnin' to respect that.\n\nI think this be a good time to teach this Big Hunter Mon a lesson, don't you? Be you my faithful messenger?", objectives = "Survive Jani's prank on Nesingwary.\n\nIf you lose your saurid disguise, return to Jani for another.", progress = "You taken my present to that big hunter mon yet, richmon?", completion = "Haha! Well done, richmon. It gonna take that Big Hunter Mon weeks to get de smell outta his ammo stores. Not to mention his feet. You have earned my favor." }
WordHunterWoW_QuestEN[50335] = { title = "Grant Me Revenge", description = "I don't care who you pledge allegiance to, {race}. I need Hogger dead!\n\nHe--and the other cretins in this Light-forsaken place--have slain my men. The Alliance and the Horde may not see eyes-to-eye, but you must know that murdering my people in cold blood cannot stand.", objectives = "Defeat Randolph Moloch, Lord Overheat, and Hogger.", progress = "Is it done? Is Hogger dead?", completion = "The uprising quelled, the elements calmed, and Hogger slain... I cannot thank you enough, <name>. My people have been avenged.\n\nThank you." }
WordHunterWoW_QuestEN[50336] = { title = "The G-Team", description = "I'd keep my distance from B.E Barechus and Murd Doc, neither is terribly stable.\n\nLet's get you to work! Go down into this tunnel until you get to Tinkers' Court. Hopefully you'll know what to do when you meet Mekgineer Thermaplugg.\n\nOur leader, Commando Hann Ibal waits somewhere in there. He'll reward you handsomely for all your work.\n\nProbably....", objectives = "Kill Mekgineer Thermaplugg.", completion = "I'd love for you to come aboard as a full G-Team Commando, but our bylaws specifically prohibit Horde team members; however, I CAN enroll you in the G-Team Fan Club!\n\nHere's something for your trouble." }
WordHunterWoW_QuestEN[50337] = { title = "The G-Team", description = "That Murd Doc is crazy, {class}. Never, ever, let you find yourself in an aircraft with that gnome.\n\nStealth usually isn't my thing, and it's certainly not going to be yours. Go down this hallway to the Launch Bay and dispose of the Electrocutioner 6000.\n\nThe Electrocutioner is in charge of the aircraft...\n\n...and I hate aircraft. I'm not getting in any sort of aircraft!\n\nUse this parachute to drop down afterwards and speak with Commando Face for your next job.", objectives = "Kill the Electrocutioner 6000.", progress = "Woah! How did you see me!?", completion = "Took you long enough. Get behind the pillar before you blow our cover!" }
WordHunterWoW_QuestEN[50338] = { title = "The G-Team", description = "How did you get in here, {name}?\n\nI'm Murd Doc of the G-Team and we could use the help of a {race} like you.\n\nHelp us defeat the irradiated inhabatants that now call Gnomeregan home, and I'll make you an honorary G-Team Commando!\n\nTake this parachute, jump down into the Hall of Gears, and take out the Viscous Fallout. After you're done, report to Commando B.E Barechus by the west hallway. You two will get along great, I'm sure.", objectives = "Kill the Viscous Fallout.", completion = "The mission is far from over!" }
WordHunterWoW_QuestEN[50340] = { title = "Steal Them Back", description = "<This empty crate of supplies is clearly marked with Kul Tiran signage. These must be the spoils of their raids on the farms of the valley.\n\nThe citizens would probably like their supplies back if there are any left.>", objectives = "Retrieve 5 Stolen Crates.", progress = "Keep an eye out for anything useful. This place is very dangerous.", completion = "It's not stealing if we're stealing them back. Hey! Are those my lucky anchors?" }
WordHunterWoW_QuestEN[50341] = { title = "A Recent Discovery", description = "Earlier today, the leaders of the Horde gathered together for a feast in celebration of our victory over the Burning Legion.\n\nAs the others were feasting, Gallywix requested a private audience with the Dark Lady.\n\nIt seems that he has found a mysterious substance in Silithus... a magical ore unlike any we have ever encountered before. \n\nThe warchief has ordered me to fill you in on the details, in preparation for a special assignment.", objectives = "Speak with Nathanos Blightcaller.", completion = "The Dark Lady has given orders that you are to personally oversee the operation in Silithus." }
WordHunterWoW_QuestEN[50343] = { title = "Mayhem at Mildenhall Meadery", description = "Ahhhh! Sir, please, I need some help!\n\nMy dad hasn't come back from the meadery and, and... well, when I went to look, there were giant globs of honey everywhere. \n\nBut... but, somehow, they were moving on their own. I even saw one eat a bunny, I swear!\n\nI'm scared to go back by myself, but I think dad is in trouble.\n\nCan you go with me?", objectives = "Investigate the Mildenhall Meadery.", completion = "Where did all of these things come from?" }
WordHunterWoW_QuestEN[50349] = { title = "An Overrun Mine", description = "It was horrible! I was in the mine nearby, just picking away at a rock and it jumped up and bit me in the neck! Since when can rocks walk around and bite people?\n\nI hightailed it outta there, but some crazy fools are sticking around trying to take the mine back. If you're eager to punch rocks you can find them down the road to the south.", objectives = "Find Chief Miner Theock at Winterdeep Mining Camp.", completion = "Why aren't you wearing a miner's cap!? It's dangerous out here! Here, put this on.\n\nNow, I got a job for you. Real easy." }
WordHunterWoW_QuestEN[50350] = { title = "We Need a Chemist", description = "All this chaos started when we were picking at a large Azerite node deep in the mine. The mine began to rumble and all of these blasted creatures burst from the ground. If we could just get rid of that vein, I am sure we could retake the mine.\n\nFirst, we need a chemist. The best one we got is in his lab across the river. Find him and he'll give you more instructions.", objectives = "Find Head Chemist Walters.All this chaos started when we were picking at a large Azerite node deep in the mine. The mine began to rumble and all of these blasted creatures burst from the ground. If we could just get rid of that vein, I am sure we could retake the mine.\n\nFirst, we need a chemist. The best one we got is in his lab across the river. Find him and he'll give you more instructions.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[50351] = { title = "Miner Operation", description = "The mine is in real trouble. We've been excavating for a short while, but never seen anything like this. Azerite doesn't just get up and walk around.\n\nIf we are going to take the mine back, we're going to need more help. We'll need an engineer and an explosives expert. I have two in mind, sisters actually, but they are caught behind the river in all the chaos.\n\nLocate the sisters and they'll help you with the next phase of the plan.", objectives = "Locate Civil Technician Alena and Ordnance Handler Prim.", completion = "Good. We're all here." }
WordHunterWoW_QuestEN[50352] = { title = "Pinch of Azerite", description = "I don't have time for idle chit chat! If you haven't noticed, rocks are running around doing who knows what?!\n\nHow about you help out and retrieve my chemistry kit. While you're out, smash some of those creatures and collect their dust. Prim will need both of those for the next step of the plan.\n\nMaybe we can figure out what has animated the Azerite.", objectives = "Collect 45 Azerite Dust and Walters' Chemistry Kit.", progress = "Did you bring the dust?", completion = "Great job! We are going to put this to good use." }
WordHunterWoW_QuestEN[50353] = { title = "Boaring Company", description = "I don't see her body anywhere. That means she could still be alive.\n\nThe Briarback have been taking prisoners, and anyone who has ever been taken by them was never seen again.\n\nWe have a single chance here and we need to take it!\n\nCome with me into the kraul and free as many of the survivors as you can. And if you can, find Farmer Deal. See if she's still alive.", objectives = "Find and rescue 7 Captured Farmers and Farmer Deal.", completion = "I was sure they were done for. You have my thanks." }
WordHunterWoW_QuestEN[50354] = { title = "Look Out!", description = "Some of these quilboar are clearly lookouts. Those horns make it obvious, almost like I could see their task floating above their heads.\n\nI was able to kill one, but not before he blew that horn of his and summoned backup. I suggest you keep them silent before they do the same with you.\n\nIf we're going to get anywhere in there, you'll need to do it quietly. Here, Hobbs gave me a few of his sleeping darts. That should keep them quiet.", objectives = "Kill 6 Briarback Lookouts.", completion = "I'm amazed I made it here. This place is so heavily guarded..." }
WordHunterWoW_QuestEN[50356] = { title = "Rock Meet Dynamite", description = "Thanks for your help out there, but we have to ask another favor from you.\n\nThese elementals must be coming from somewhere in the mine and we need you to locate that source. \n\nYou seem more than capable of handling yourself in there, but just for extra security I am going to send you with some of Prim's special dynamite. It has an extra kick from the Azerite dust that you gathered.\n\nGet in. Find the source. Put a stop to these elementals.", objectives = "Eliminate the source of the Azerite creatures.", completion = "A trogg? Hmmm... He may have eaten quite a bit of Azerite to be able to cause all this.\n\nWith him gone, now we can clear out the remaining creatures here and get back to digging! Thank you for your help." }
WordHunterWoW_QuestEN[50358] = { title = "Desert Research", description = "The dark blade of Sargeras has cast a shadow of destruction over this land.\n\nIt seemed that the silithid hives were destroyed in the attack, but I have received reports that the silithid are returning.\n\nIf it were up to me, I'd burn those wretched hives once and for all! However, it is not up to me.\n\nThe Dark Lady wants the surviving silithid dissected and studied. \n\nPixni Rustbomb is conducting the research and is in need of a \"collector.\"", objectives = "Speak with Pixni Rustbomb.", completion = "You're here to collect the samples? It's about time they sent someone to help me out!" }
WordHunterWoW_QuestEN[50359] = { title = "Cleanup Duty", description = "Wh...why, why is all of the honey alive and what happened to everybody?\n\nYou don't think... oh no! Please, {name}, tell me they haven't been eaten!\n\nAhhhh! That would be terrible. Please don't let me be eaten too!", objectives = "Kill 4 Flowing Honey and 4 Bubbling Mead.", completion = "Thanks for getting rid of those things, <name>." }
WordHunterWoW_QuestEN[50360] = { title = "Khadgar's Request", description = "Archmage Khadgar arrived while you were away. It seems that he is here to speak with you, {name}.\n\nHurry and see what it is that he wants. I want him gone as soon as possible.\n\nThe last thing we need is a human nosing around in Horde business!", objectives = "Speak with Archmage Khadgar.", completion = "It's good to see you, <name>. I suspect that my welcome among the Horde is wearing thin..." }
WordHunterWoW_QuestEN[50363] = { title = "War Pigs", description = "They look cute enough now, but that's a new herd of battleboars in training.\n\nFarmers don't like waste, and it would be a shame to get rid of such useful creatures.\n\nEither way, we could use those pigs, and I'd rather have them with us rather than face a bloodthirsty one in a few years. You should find them up on top of the cliffs overlooking the center of the kraul. Go round up as many piglets as you can take with you and we'll make good use of them.", objectives = "Collect 8 Grazing Battle-Piglets.", completion = "I will take these and make sure they get to the farms for proper training." }
WordHunterWoW_QuestEN[50364] = { title = "The Blood of Azeroth", description = "Do the leaders of the Alliance and Horde even know what they're fightin' over?\n\nThis substance that is risin' up from the wound is the lifeblood of Azeroth!\n\nWe need ta heal the wound, not exploit it fer power! Azeroth is the only home we've got. We cannot allow her ta die!\n\nI trust ye, {name}, and I know that yer voice carries great weight among the Horde. Ye must reason with 'em ta stop this madness!\n\n'Tis the only hope our world has...", objectives = "Deliver Magni Bronzebeard's message.", completion = "The blood of Azeroth? Hmph.\n\nI'll make sure this news reaches the warchief, but this operation must continue until I'm ordered to cease!" }
WordHunterWoW_QuestEN[50365] = { title = "Run For the Hills", description = "The quilboar are up to something, something big. You need to stop it!\n\nThey've been busy bringing supplies up to the caves above their sanctum. Preserved thorns, cauldrons of venom, giant totems...\n\nThey're preparing for war.\n\nGet up there and destroy those stockpiles before they can be used against the citizens of the valley!", objectives = "Destroy the stockpiles of supplies.", completion = "Those supplies you destroyed should set them back. They must have been saving them for a while..." }
WordHunterWoW_QuestEN[50367] = { title = "Anger in a Bottle", description = "<The bottle the quilboar was carrying contains a foul-smelling, orange liquid. You're not sure if it's safe to drink, but it can't hurt to gather some samples to bring back to the citizens of Brennadam.\n\nMaybe their alchemist can come up with an antidote to counter its effects.>", objectives = "Collect 10 Foul-Smelling Samples.", progress = "Do you have something for me?", completion = "This stuff smells awful. Maybe Hobbs will know what to do with it. Once we get out of here I'll make sure these samples get to him." }
WordHunterWoW_QuestEN[50368] = { title = "Terror of the Kraul", description = "By all the gods of the sea, what a monster!\n\nI can barely believe what I am seeing, {name}. This ettin has undergone the same ritual that the brutes do, and it seems even angrier! If he gets out of here, we won't stand a chance.\n\nI know I ask the impossible, but I must: kill this monstrosity and save the whole valley from its wrath! Here, take one of the potion samples you brought me. It's probably dangerous, but you might need it to defeat this beast.", objectives = "Defeat Bramblefist the Maddened.", progress = "We have to kill that thing!", completion = "It's done! I was afraid you were done for, but you've saved us all!" }
WordHunterWoW_QuestEN[50369] = { title = "Bruin Potions", description = "", objectives = "" }
WordHunterWoW_QuestEN[50370] = { title = "Deeper into the Woods", description = "We need to go deeper into the forest. The witches are clearly up to something even worse than I'd imagined.\n\nAs much as I have a duty to return to Lady Lucille with Master Ashton, I also have a duty to find out more about this threat to our people, and stop it if I can.\n\nGoing further into the forest is not without risk, but I believe it is one worth taking.", objectives = "Travel with Cleardawn, Ashton, and Webb deeper into the forest.", progress = "The risk has paid off", completion = "By my ancestors' anchors that is a large army! At least it doesn't appear to be mobile yet. And the tree... Clearly it is the focus of their efforts." }
WordHunterWoW_QuestEN[50371] = { title = "Summons to Stormwind", description = "King Wrynn has requested that you return to Stormwind as soon as possible. There is an urgent matter that requires your attention.\n\nI will fill you in on the details as soon as you arrive.\n\nYou will find me at Lion's Rest. Be swift... our window of opportunity may already be closing!", objectives = "Meet with Mathias Shaw in Stormwind.", completion = "At last you have arrived, <name>. The very future of the Alliance may depend on what I am about to tell you..." }
WordHunterWoW_QuestEN[50372] = { title = "Desert Research", description = "The dark blade of Sargeras has cast a shadow of destruction over this land.\n\nIt seemed that the silithid hives were destroyed in the attack, but I have received reports that the silithid are returning.\n\nWe need to find out how the silithid avoided destruction and what effect the blade is having on their hives.\n\nThe crown wants the surviving silithid dissected and studied. \n\nTammy Tinkspinner is conducting the research and is in need of a \"collector.\"", objectives = "Speak with Tammy Tinkspinner.", completion = "You're here to collect the samples? Let's get started!" }
WordHunterWoW_QuestEN[50373] = { title = "A Recent Arrival", description = "The situation in Silithus appears to be gaining more attention.\n\nArchmage Khadgar just arrived while you were away. It seems that he is here to speak with you, {name}.\n\nIt appears urgent. I would speak with him as soon as possible.", objectives = "Speak with Archmage Khadgar.", completion = "It's good to see you, <name>. I wish that I were here under more pleasant circumstances..." }
WordHunterWoW_QuestEN[50374] = { title = "The Blood of Azeroth", description = "Do the leaders of the Alliance and Horde even know what they're fightin' over?\n\nThis substance that is risin' up from the wound is the lifeblood of Azeroth!\n\nWe need ta heal the wound, not exploit it fer power! Azeroth is the only home we've got. We cannot allow her ta die!\n\nI trust ye, {name}, and I know that yer voice carries great weight among the Alliance. Ye must reason with 'em ta stop this madness!\n\n'Tis the only hope our world has...", objectives = "Deliver Magni Bronzebeard's message.", completion = "The blood of Azeroth? I'll make sure this news reaches Stormwind, but I must continue the operation until I am ordered otherwise." }
WordHunterWoW_QuestEN[50375] = { title = "Ride With Me", description = "I have hunted many powerful foes, {name}. My pack has defended this island and its people from countless outside threats and foreign invaders.\n\nBut there is a darkness growing in Zandalar. A corruption so deep and relentless that it consumes the minds of the Zandalari.\n\nI cannot hunt intangible darkness, but I can hunt those who wield it against my people.\n\nCome, ride with me and my pack. I smell the foul stench of blood trolls nearby. We will see how well you hunt with the pack.", objectives = "Ride Gonk as he investigates the source of corruption nearby." }
WordHunterWoW_QuestEN[50376] = { title = "Deadliest Cache: Reel Big Fish", description = "Can ye believe the nerve of these scallywags? Questioning the very Coxswain of this here wharf?\n\nBah!\n\nLend me your ear for a moment or three. I've got a tale that'll put brew in your mug and a quiver in your boots!\n\nIt was the biggest, deadliest cache I ever did loot on these seas...", objectives = "Listen to Coxswain Hook's tale.", progress = "Want to hear more?", completion = "Don't listen to either of 'em. True every word, I tell ya!" }
WordHunterWoW_QuestEN[50377] = { title = "Strength of the Pack", description = "It's time to prove your worth to the pack, {name}.\n\nThe blood trolls of Nazmir have invaded this land. My people here have suffered greatly.\n\nLead the pack. Find survivors. Make the blood trolls pay for what they've done. Wipe their corruption off this land.\n\nYou will have every opportunity to prove yourself, but remember, we hunt as a pack. You must accept that others have strengths you do not. Allow them to lead when the time is right and the pack will be stronger.", objectives = "" }
WordHunterWoW_QuestEN[50381] = { title = "The Great Hat Robbery", description = "Along this road the merchants ride. Taking dere wares from one place to another and lining them own pockets. \n\nOne Big Mon named Tik'su be the worst of all. He charge arms and legs outright and it even take trolls some time to regrow them parts.\n\nHis biggest pride? His hat. \n\nGo be my messenger, Rich-mon. Scare his burdened beast and knock off Tik'su. Then bring me his hat.", objectives = "Successfully steal Tik'su's Hat.\n\nIf you lose your saurid disguise, return to Jani for another.", progress = "You had a chat with Tik'su about his hat yet, richmon?", completion = "Haha! Well done, richmon. You bruised Tik'su's pride and his backside. He gonna be hurtin' for a while. You have earned my favor." }
WordHunterWoW_QuestEN[50384] = { title = "[DNT] Test Quest", description = "{name}, while you were out being one hell of a {class}, Baron Sablemane sent his pet dragon up here with a message.\n\nHe's asked for you personally.  From what I understand, he wants you to head up his own fight against the gronn.\n\nI guess you're the most qualified person in all of Outland to help him, but if I were you, I'd get in contact with a couple of friends first and ask them to join you at the Circle of Blood.", objectives = "" }
WordHunterWoW_QuestEN[50385] = { title = "Indefatigable Purpose", description = "Its grip weakens, if only briefly. We must claim this place anew!\n\nFlopping, nightmarish horrors have infested the caves amongst the cove. Take the sacred blessings. Venture forth into the dark and find their altars. \n\nPurge their blasphemous constructions from our lands!", objectives = "Cleanse 3 Drowned Altars.", completion = "A victory... perhaps a turning point." }
WordHunterWoW_QuestEN[50386] = { title = "Flush Them Out", description = "They lurk in the shadows, in the salt-soaked caverns. The dark brine beneath the pure gleam of the surface.\n\nI have seen them. They plague my dreams, their whispers are maddening. They speak of their master, clawing at the barrier...\n\nSearch the cliffs for their warrens. Find what lurks within and obliterate them all.", objectives = "Investigate and defeat what lies within 4 structures in the Forgotten Cove.", progress = "Ignorance of our enemy will invariably lead to defeat.", completion = "The things are driven back, for a time." }
WordHunterWoW_QuestEN[50387] = { title = "Trinkets and Baubles", description = "Beneath the tides, these terrors do not see fit to stay within their warrens.\n\nThey have emerged in the night, stealing away to the villages and indulging in their avarice. They will use the provisions against us, to serve in their rituals. Rituals of summoning and communion with powers too terrible to comprehend. \n\nThe populace is no concern of mine anymore, but I would not see these briny thieves to have their way. Relieve them of their plunder, and let them learn a bitter lesson.", objectives = "Recover 3 crates of Stolen Supplies.", progress = "Where there is no peril, there can be no glory!", completion = "Paid for in blood." }
WordHunterWoW_QuestEN[50388] = { title = "The Weight of My Ambition", description = "As with the other settlements, I too relied on the services of sailors and watercraft to deliver supplies. They proved very useful in their diligence, and their silence.\n\nPredictably, they drew the attention of enemies, including those below the waves. Their anchor was hexed, dragging them beneath the ocean before they could so much as cry out.\n\nI have seen them, hoisting ethereal sails and singing shanties of the damned. If these waters are to be safe again, they must be silenced again. For good.", objectives = "Defeat the Drowned Captain.", completion = "Finally, a sailor's death." }
WordHunterWoW_QuestEN[50389] = { title = "Malign Inspiration", description = "A long time ago, there was a maiden.\n\nA precocious child fond of song, she made it her hobby to shadow my every move. Charming at first.\n\nWalking on the pier's edge, she became entangled within the ropes surrounding a leering idol. At that time a tremor ran through the waves, giving the small push needed to send them both beneath the surface.\n\nI can hear her song still. At first I thought it a passing fancy, music upon the waves. I realize now the voice comes with sinister purpose.\n\nShe must die.", objectives = "Kill the Enchanting Siren.", completion = "She was made their queen, and their slave." }
WordHunterWoW_QuestEN[50391] = { title = "Deadliest Cache: Gun Fishin'", description = "Hook's got a screw loose in her head, I tell ya. Sharks workin' together on somethin'... phooey!\n\nIt does remind me of one of my favorite tales, though. Have I ever told ya 'bout the time I caught THE single largest, deadliest, most tentacled beast in all o' Azeroth?!\n\nAye, I thought not. It's not a story I'd tell ya sober. It was a day unlike any other...", objectives = "Listen to Master Gunner Line's tale.", progress = "Aye, lad?", completion = "Ozumat ain't around on account of I shot the blasted beast in its slimy face! Swear on me beard every word is true!" }
WordHunterWoW_QuestEN[50393] = { title = "A Child of Pa'ku", description = "<The pterrordax egg is warm and trembling. It will hatch soon.>\n\nPerhaps a certain pterrordax loa can help you.", objectives = "Take the Pterrordax Egg to Pa'ku at Pterror Rise.\n\nProvided item:", completion = "An egg? It does not appear to be one of my brood.\n\nWhere did you find this?" }
WordHunterWoW_QuestEN[50394] = { title = "Your Problem Now", description = "Hm. This egg does not belong to one of my brood, and I have no broodlings that need another sibling.\n\n<Pa'ku might be smiling or snarling. She is showing an awful lot of teeth.>\n\nYou will care for this little one. And you had better hurry.\n\nIt will hatch very soon.\n\nOh, and a little advice. If you want the little one to like you, you had better be the first thing it sees upon hatching.", objectives = "Place the Pterrordax Egg at the empty nest and wait for it to hatch.", completion = "<The tiny Pterrordax stares adoringly at you.>\n\nSkreeeee." }
WordHunterWoW_QuestEN[50395] = { title = "The Call of the Skies", description = "<Kua'fon turns his head toward the cliff and chirps eagerly. He spreads his tiny wings and flaps vigorously.>\n\nIt is time to leave the nest.", objectives = "Watch your hatchling take its first leap into the great unknown.", progress = "What do you need, grounded one?", completion = "I regret to say that this is life in the skies, sometimes. Not all hatchlings live to adulthood." }
WordHunterWoW_QuestEN[50396] = { title = "A Pterrible Fate", description = "<Kua'fon peers longingly toward the horizon and gives a keening cry.\n\nYou can take the pterrordax from the sky, but not the sky from the pterrordax. It's time to do something.\n\nPerhaps Pa'ku could offer some advice.>", objectives = "Ask Pa'ku for help.", completion = "It is good that you came to me. I was considering throwing the thing off the roost again.\n\nPerhaps there is another way." }
WordHunterWoW_QuestEN[50397] = { title = "Aerial Aspirations", description = "<Kua'fon studies you intensely. One single golden eye is trained on you, unwavering.>\n\nSkree.\n\n<He then turns his maw toward the horizon and spreads his wings wide.>\n\nSkree!\n\n<Is it finally time?>", objectives = "Fly?", completion = "<Kua'fon wheezes.>" }
WordHunterWoW_QuestEN[50401] = { title = "Fear of Falling", description = "Some young find their wings sooner than others. At least yours had the sense to keep them open.\n\nI would not worry too much about its safety- little ones tend to bounce.\n\nAs for this failure... the young must keep trying, and they must learn not to fear falling. It is now your task to teach it.\n\n<The loa smiles at you, all teeth.>\n\nIf it is reluctant to learn, you might consider bribery.", objectives = "Find your hatchling and convince it to return to the nest.", progress = "<Kua'fon quivers in fear and chirps at you in distress.\n\nPerhaps a treat could soothe your hatchling?>", completion = "<The hatchling inspects your hands warily.>" }
WordHunterWoW_QuestEN[50402] = { title = "SKREEEEE!", description = "<Kua'fon stares at you for a moment, then opens his maw and unleashes a continuous screech.\n\nYou need help.>", objectives = "Find out what is distressing your hatchling and address it.", progress = "<The hatchling's gaze scours your person in search of anything edible. It may be best to keep your fingers out of reach.>\n\nSkree!? Skree!", completion = "<Kua'fon swallows the dino chow whole.>\n\nSkree." }
WordHunterWoW_QuestEN[50412] = { title = "Back to the Nest", description = "<Kua'fon peers up at you trustingly.>\n\nNow would be a good time to take him back to the nest.", objectives = "Return Kua'fon to his nest in Pterror Rise.", completion = "<The hatchling settles into the nest.>\n\nSkree." }
WordHunterWoW_QuestEN[50417] = { title = "Ruin Has Come", description = "There is a terror beneath the waves. It seeks to destroy my family, my house, and my legacy.\n\nYou must come, claim your destiny and deliver us from the terrors of the deep!\n\nFind our estate to the east, among the isles. We lived opulently in the shadow of the great fortress. We believed the priests would deliver us from the darkness below. Now that darkness has bubbled to the surface, whispering madness in our dreams.\n\nHurry. The air turns the darkest I have seen in my cursed existence.", objectives = "Find the author of the Mysterious Letter.", completion = "You have answered the letter. Now you are bound to this place." }
WordHunterWoW_QuestEN[50418] = { title = "Deadliest Cache: Sink and Swim", description = "Mph mph!\n\nMph mph mph mph mph. Mph mph mph.\n\nMph.\n\nMph mph? Mph!", objectives = "\"Listen\" to \"Sinker's\" \"tale\".", progress = "Mph?", completion = "Mph mph mph. Mph." }
WordHunterWoW_QuestEN[50420] = { title = "A Gently Shaken Gift", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[50421] = { title = "Sparring on the Spar", description = "", objectives = "" }
WordHunterWoW_QuestEN[50432] = { title = "Titanic Innovation", description = "", objectives = "Spectacular! Marvelous! At last, I understand fully, and the titans themselves speak to me! They have shown me how to use the essences to craft the finest armors the world has ever seen, though I think the results may be... somewhat unpredictable.\n\n<Vridiel beams with pride.>\n\nWell, what are you waiting for? Bring me as many Wakening Essence as you can find!" }
WordHunterWoW_QuestEN[50433] = { title = "Zanchuli Disbanded", description = "I would like to say we are doing well, but we are not.\n\nDe Zanchuli Council is broken. Raal and I are all dat remain who are still loyal to King Rastakhan. You best bring news to your Horde and tell dem what transpired here.\n\nRaal and I will rally what support we can and head for de Zocalo.\n\nAnd hero, thank you for saving my life and my loa.", objectives = "Speak with Baine Bloodhoof in Dazar'alor.", completion = "Only two of their six most sacred advisors? I had hoped more would have revoked the dark path they are on." }
WordHunterWoW_QuestEN[50443] = { title = "Down to the Roots", description = "", objectives = "" }
WordHunterWoW_QuestEN[50444] = { title = "Taking the Loa Road", description = "This road not be traveled much anymore. Except by those that serve the blood Loa. They be fools.\n\nI be wantin' my fun from those fools. Go to the spot I be markin' for you and plant this cursed coin. The silly blood trolls be seein' it and give us a laugh when they try to pick it up.\n\nJust be makin' sure that no other creature see you. Or else it be a quick trip back to the arms of Jani.", objectives = "Survive Jani's prank on the Amaki trolls.\n\nIf you lose your saurid disguise, return to Jani for another.", progress = "You taken that cursed coin to the pranking-place yet, richmon?", completion = "Haha! Well done, richmon. It gonna take those idiots forever to be gettin' outta this mess. You have earned my favor." }
WordHunterWoW_QuestEN[50445] = { title = "Controlling the Situation", description = "I have been observing this macabre army of, wood, flesh, and bone and how the witches and servitors control the lesser creations with charms. I believe I can craft an even more powerful charm - one we can use.\n\nIn the hearts of the servitors are the very strongest charms. They are used to anchor the Ancient Drust into their physical forms. They are precisely what we need.\n\nGood luck. It is doubtful that they will part with them easily.", objectives = "Collect 5 Control Charms from the Haunted Servitors.", progress = "Were you able to collect enough charms?", completion = "Excellent. I should be able to do some... Interesting things with these." }
WordHunterWoW_QuestEN[50446] = { title = "Witchrending", description = "A blunderbuss? I'd have to say, I wasn't quite expecting that.\n\nNonetheless, now that we have a weapon, we have an advantage. I think it's time we take the fight directly to the coven.\n\nMarshal Reade informed me that several of their Matrons have been spotted throughout Corlain. Let's show them what happens to an enemy of House Waycrest.", objectives = "Use Witchrend to defeat Matrons Ceridwen, Adeline, and Letitia in Corlain.", completion = "Let us hope this sends a message to the coven.  As long as we have weapons to fight them, we will persevere.\n\nSpeaking of weapons, I believe our blacksmith has an idea on how to take down that barrier. You should have a word with him." }
WordHunterWoW_QuestEN[50447] = { title = "Remembering the Fallen", description = "<This villager died clutching a brooch with what looks like a family crest. It looks like several villagers didn't survive the coven's occupation of Corlain.\n\nIt might be possible to identify the fallen by the keepsakes they carried. The survivors would likely be grateful to learn the fate of their loved ones.>", objectives = "Collect 8 Personal Keepsakes from fallen Corlain Villagers in Corlain.", progress = "What's this?", completion = "I don't know what to say. That you would risk your life to bring these items to me speaks greatly of your character, mainlander.\n\nI will make sure these keepsakes make it to the friends and families of the fallen, as well as news of their fate. On their behalf, I thank you for your compassion." }
WordHunterWoW_QuestEN[50448] = { title = "Reclaiming Corlain", description = "", objectives = "" }
WordHunterWoW_QuestEN[50449] = { title = "Reeking Refuge", description = "Oh good, maybe you can make sense of this.\n\nI was just carving through a swath of the coven's lackeys when I stumbled across this field. Something here has knocked these guys completely out of commission!\n\nI can't seem to find the source, but maybe you'll have better luck. I'm more used to hitting things than investigating them.", objectives = "Investigate what is disabling the coven's minions in Hocking's Plot.", completion = "You don't look like you're in league with the coven, so what are you doin' in Corlain?" }
WordHunterWoW_QuestEN[50450] = { title = "An Offensive Harvest", description = "So you're takin the fight to the coven with the Waycrest girl, eh?  Ya might just be able to take advantage of their apparent onion aversion.\n\nWhile you're out rootin' in the field, keep an eye out for any onions bulging out of the ground. Those ones should be particularly aromatic, and should cause some fits in the coven's minions if you keep it on ya.\n\nJust try not to take too much, right? I need enough left in the fields to keep the farm safe.", objectives = "Collect 7 Aromatic Onions from Hocking's Plot.", progress = "Did ya find any good ones?", completion = "That bunch should serve ya well." }
WordHunterWoW_QuestEN[50451] = { title = "Eating Through the Defenses", description = "Not sure why and don't rightly care, but for some reason the coven can't come near my onion field. So long as my crop doesn't give out, I can hole up in here as long as it takes.\n\nUnfortunately, those boars got the same idea and now they're eatin' up my harvest! If they keep that up, soon there'll be nothin' keepin' the coven at bay!\n\nIf you can do me a favor and thin them out, I'd be happy to let you take some of these onions with you.", objectives = "Kill 8 Scavenging Boars in Hocking's Plot.", progress = "How's the boar situation?", completion = "That oughtta do it for a spell.\n\nThanks for the help, stranger." }
WordHunterWoW_QuestEN[50452] = { title = "Potent Protection", description = "Here ya go, I got them onions bundled up nicely for ya.\n\nGive my regards to Miss Waycrest, will ya? Her allies are welcome on my farm anytime.", objectives = "Deliver the Sack of Aromatic Onions to Lucille Waycrest at Watchman's Rise.\n\nProvided item:", completion = "The coven is vulnerable to onions!?  I remember my nan used to tell stories about them warding off evil, but I never thought to take it literally!\n\nThis is quite the discovery!" }
WordHunterWoW_QuestEN[50453] = { title = "Barrier Buster", description = "Oy, {name}! I think I might have a solution te that pesky barrier keepin ye out of Corlain proper! \n\nI took the silver we had left 'ere an' doctored up one o' these cannonballs. The walls surroundin' Corlain are festooned with defensive cannons. Get one pointed at the gate, ye can send this beauty right into the barrier!\n\nYe'll need a hefty pinch of powder te get this thing movin', though - it's a bit on the heavy side. Ye can likely find some in the camp outside the walls.", objectives = "Collect 5 Blasting Powder from Pikeman's Ridge and bring them to Inquisitor Sterntide outside the gate into Upper Corlain.", progress = "I don't think these guys will be needin' this cannon anymore.", completion = "Quite a bit of powder ya got there.\n\nCareful ya don't take the whole wall down." }
WordHunterWoW_QuestEN[50454] = { title = "A Traitor's Death", description = "It has come to my attention that you intend to assault the camp outside of the walls. If this is so, I have a request.\n\nThough most of the guardsmen who fight against us were turned to the coven against their will, Captain Goodspeed and his brigade of halberdiers gave their souls willingly to the Heartsbane. They are traitors and an affront to the Waycrest Guard.\n\nYou will find Goodspeed and his men stationed at the camp.  I would consider it a personal favor if you would cut them down to the last.", objectives = "Kill Captain Goodspeed.", progress = "Is it done?", completion = "Captain Goodspeed was a stain on the reputation of the Waycrest Guard.\n\nI hope his end was painful." }
WordHunterWoW_QuestEN[50455] = { title = "Leaving the Nest", description = "It looks like the coven hasn't managed to enthrall all of our falcons. I can see some untainted ones still in cages in the training yard.\n\nOur falcons are well trained, and should know to fly to one of our other yards if something happens to their handlers. \n\nIf you can just release them from their cages, they should be able to make it to safety.", objectives = "Open 5 Falcon Cages in the Corlain Aviary.", completion = "Nice work!  With any luck, the falcons should head back to roost at Arom's Stand.\n\nThough really, I'd prefer they be anywhere other than in the coven's clutches.\n\nYou have my thanks." }
WordHunterWoW_QuestEN[50456] = { title = "Hexed Hatchlings", description = "I've found where those evil witches have been tainting our falcons! You see those charms? \n\n<Notley motions toward the high perches and roofs nearby.>\n\nThey're using those to infect our flock with their evil magic as they hatch.  I think Winston can get up there to take out the charms, but someone will need to direct him.\n\nI'm not quite healed up enough to take on a whole camp of falconers. Can you help?", objectives = "Use the Falconer's Whistle to destroy 7 bewitching charms in the Corlain Aviary.", progress = "Have you taken care of the charms?", completion = "The charms are broken? That's a relief!\n\nWe may just be able to save our flock after all." }
WordHunterWoW_QuestEN[50457] = { title = "Break On Through", description = "Cannon's ready, boss.\n\nCare to do the honors?", objectives = "Use the Ramparts Cannon to break the barrier at the gate to Upper Corlain.", completion = "Ballaster's plan worked! He is certainly a resourceful blacksmith.\n\nCome, Inquisitor. Waycrest Manor is just ahead!" }
WordHunterWoW_QuestEN[50459] = { title = "Vugthuth", description = "", objectives = "" }
WordHunterWoW_QuestEN[50461] = { title = "Zujothgul", description = "", objectives = "" }
WordHunterWoW_QuestEN[50466] = { title = "He's Gone Mad!", description = "Ol' Wildtusk has withstood years of attacks by young hunters that are overeager and underskilled.\n\nNone could take him.\n\nHis wounds have finally done him in. He just won't go down. Find that crazy riverbeast bull, and help him let go of his mortal shell.", objectives = "Kill Wildtusk.", completion = "Thank you for helping him on his way.\n\nDat Wildtusk, he has been watching dese hills for years long past. Some beast will have big shoes to fill!" }
WordHunterWoW_QuestEN[50468] = { title = "Shul-Nagruth", description = "", objectives = "" }
WordHunterWoW_QuestEN[50474] = { title = "The Other Side", description = "", objectives = "" }
WordHunterWoW_QuestEN[50476] = { title = "The Warchief Awaits", description = "{name},\n\nThere are important matters I would like to discuss with you, but discretion is of the utmost importance. \n\nMeet me in my chambers in the Undercity where I can assure our privacy has not been compromised. \n\nEnsure that you are not followed; Orgrimmar has become riddled with SI:7 spies. It would seem that that King Anduin and Mathias Shaw are desperate to know what our next move is. How admirable.", objectives = "Report to Warchief Sylvanas Windrunner in the Undercity.", completion = "Glad you could make it so quickly, <name>." }
WordHunterWoW_QuestEN[50481] = { title = "In the Hall of the Drust King", description = "I've been watching a lot of activity going on at the ruins at the base of the massive tree by the lake. What Master Ashton reported is accurate - something important is going on down there. \n\nWe've disrupted their rituals but I worry we might have been too late.\n\nWe need to go over there. If there is anything remaining, we must destroy it.", objectives = "Confront Gorak Tul.", progress = "We must confront Gorak Tul.", completion = "We've wounded him or he wouldn't have retreated as he did. Our victory won't last long unless we do something about his army." }
WordHunterWoW_QuestEN[50483] = { title = "Underlord Xerxiz", description = "", objectives = "" }
WordHunterWoW_QuestEN[50488] = { title = "Ancient Jawbreaker", description = "", objectives = "" }
