WordHunterWoW_QuestEN[50492] = { title = "Cursed Chest", description = "", objectives = "" }
WordHunterWoW_QuestEN[50493] = { title = "Fetching Wrex", description = "When all the commotion started, Ancel's pup ran off. The poor thing was terrified!\n\nA couple farmhands went to look for him, but with all of these monsters terrorizing the farm, I fear the worst!\n\nCan you keep an eye out for Wrex while you're up in the hills? He might have gotten trapped in the honey too.", objectives = "Crack open Crystallized Honey to search for Wrex.", completion = "Ancel will be happy to know that Wrex is safe and sound!" }
WordHunterWoW_QuestEN[50496] = { title = "Glompmaw", description = "", objectives = "" }
