WordHunterWoW_QuestEN[50504] = { title = "Honey Glazed Sam", description = "Think I heard someone shouting down yonder.\n\n{name}, there might be trouble. Let's go!", objectives = "Rescue Sam Robinson.", completion = "I thought I was a goner for sure!" }
