WordHunterWoW_QuestEN[50530] = { title = "Witch Way Out?", description = "There are other Falconhurst citizens to be freed before they become sacrifices.\n\nFree anyone you come across.\n\nThe key used to free Master Ashton should still work. Good luck!", objectives = "Free 10 Captive Villagers.", completion = "Well done! Not only did you save innocents, you denied the witches fuel for their Grand Rite." }
WordHunterWoW_QuestEN[50531] = { title = "Under Their Noses", description = "Figures they wouldn't just put the destination on the crates for us. \n\nNothing's ever easy, is it?\n\nIf the weapons aren't moving on Cagney's ferry, they must be passing through Bridgeport, the shipping hub just up the road.\n\nBridgeport is protected by a garrison of Proudmoore marines. The Ashvane Company has a lot of nerve moving illegal weapons right under their noses.\n\nCome on, let's check it out.", objectives = "Speak with Flynn Fairwind in Bridgeport.", completion = "<Flynn pretends not to notice you, but whispers at you.>\n\nOf course it's her." }
WordHunterWoW_QuestEN[50533] = { title = "Stick It To 'Em!", description = "We have been able to stop the Grand Rite but the witches will try again unless we act.\n\nWe have to destroy them. Utterly.\n\n<Cleardawn smiles.>\n\nHow kind of them to give us the means.\n\nYou've helped us get this far, {name}. You control the Demolisher. Destroy everything you see! \n\nOnce we've finished we can signal for help out of here!", objectives = "Use the Crimsonwood Demolisher to destroy witch forces in the Crimson Forest.", completion = "The plans for the Grand Rite are ruined and their rutial sites are in shambles. Master Ashton will be safe here in Arom's stand and we can finally send reinforcements to Falconhurst by gryphon.\n\nIn all, a job well done! Thank you for your vital help." }
WordHunterWoW_QuestEN[50534] = { title = "Wendigo Away", description = "If the unearthly howls coming from the Highlands at night are any indication, the wendigos must have some sort of leader or alpha.\n\nI tell you, it's the sort of sound that could only come from some sort of massive, hulking, flesh-eating abomination.\n\nDefinitely something that could tear us limb from limb, and munch on our frail bones, all without breaking a sweat. How exhilarating!\n\nI'm sure it'll be no problem for us to handle though.", objectives = "Kill Bonerender.", completion = "Marvelous! Slaying their leader ought to put some fear into 'em." }
WordHunterWoW_QuestEN[50535] = { title = "Power of the Overseer", description = "Overseer Nerzet is very cruel, and oh so easy to provoke!  \n\nIt makes her very angry when things go missing, or move, or change... my crew and I are having a yip of a time! That you got this device to work was certainly a bonus!\n\nIt will be much easier for us to finish up what we need to do here, with her out of the way. \n\nUm, and maybe go ahead and grab that neat power rock she carries. It could come in handy.", objectives = "Kill Overseer Nerzet and take her power rock.", progress = "Were you able to end her reign?", completion = "Hmmm. I am tempted to sell this stone, it must be quite valuable. \n\nHowever, with what you have shown us today, I think there may be more value in having it with us." }
WordHunterWoW_QuestEN[50536] = { title = "Magic Decoder Device", description = "We retrieved this device from the sethrak in the ruins to the east, but have not been able to use it.\n\nWhen you approached, it started to glow. Something about you...\n\n<Maaz pauses and eyes the stone on your neck.>\n\n...or on you... is waking it up!\n\nPlease, {class}, use the scepter and examine the statues of the Keepers, in the central courtyard of the ruins. Something there got their overseer very excited.", objectives = "Examine the Keeper statues in the ruins.", progress = "What did you discover?", completion = "Oh, thank you, danger noodle. This will give us just the angle we need to get the most out of what we find here. Your arrival was most fortuitous!" }
WordHunterWoW_QuestEN[50538] = { title = "The Missing Handler", description = "I just received word from Warbeast Kraal dat one of their handlers is missing.\n\nDis is not usually a problem, but dey are expecting a large hatching dis year. Dey will need all de hands dey can get!\n\nGo on and see if you can find de handler, name of Bazo or something, and tell him to get back to de Kraal.", objectives = "Look for Handler Bazkoji near Warbeast Kraal.", completion = "<Handler Bazkoji rests with his sword still held in hand. He died fighting.>" }
WordHunterWoW_QuestEN[50539] = { title = "The Secrets of Zul'Ahjin", description = "You're not the only one who came to Zul'Ahjin looking for answers. The place is crawling with looters and assassins, all searching for something... \n\nSo far, they've come up empty handed, but that's because they don't know where to look.\n\nI do. \n\nInvestigate the statue at the center of the ruins. It is the key to uncovering the city's ancient secrets.", objectives = "Investigate the statue.", completion = "<The ancient stones hum with magic.>" }
WordHunterWoW_QuestEN[50540] = { title = "Rally the Rastari", description = "", objectives = "" }
WordHunterWoW_QuestEN[50542] = { title = "An Explosive Opportunity", description = "You there!\n\nDo I have the most AMAZING opportunity for you? A gnome named Wulferd Fizzbracket is on the eve of a breakthrough and could use an intrepid business partner that's on the brawnier side. Such as a {class} like yourself.\n\nJust follow the road east until you reach Fizzsprings Resort, the most fantastical wonder of nature. Wulferd is the type that stands out from the crowd.", objectives = "Speak with Wulferd Fizzbracket at the Fizzsprings Resort.", completion = "A willing assistant? Well I can't turn you down now, can I?" }
WordHunterWoW_QuestEN[50544] = { title = "The Hunters of Kennings Lodge", description = "HELP WANTED!\n\nAs we turn into the busy season, Kennings Lodge is looking for recreational hunters to assist with fulfilling the ever growing list of orders from Boralus. These are short term positions which will be paid relative to performance. \n\nKennings Lodge can be found by following the south road past the mining yard. Report to Alanna Holton on arrival.", objectives = "Speak with Alanna Holton.", completion = "You came from Bridgeport? Let's get you working, then." }
WordHunterWoW_QuestEN[50545] = { title = "Forked Lightning", description = "", objectives = "" }
WordHunterWoW_QuestEN[50547] = { title = "Knives of Zul", description = "", objectives = "" }
WordHunterWoW_QuestEN[50548] = { title = "Enforcing the Will of the King", description = "", objectives = "" }
WordHunterWoW_QuestEN[50549] = { title = "Absolutely Barbaric", description = "", objectives = "" }
WordHunterWoW_QuestEN[50550] = { title = "The Fall of Emperor Korthek", description = "Korthek finally approaches.\n\nIt's been many years since I've faced him in battle. When he first rose to power, I failed my people. I will not falter again.\n\nI am prepared to do what must be done. What I should have done long ago.\n\nWe must kill Korthek and take his key to prevent him, Jakra'zet, or anyone else from ever resurrecting Mythrax.\n\nWhen you are prepared, we will face him together.", objectives = "Defeat Emperor Korthek.", completion = "Do not waste time mourning my old friend now. His foolish crusade has left us a larger problem that demands our full, immediate attention." }
WordHunterWoW_QuestEN[50551] = { title = "Temple of Sethraliss: Avatar of the Loa", description = "We cannot let Mythrax bring his destruction upon this world once more. \n\nWe need our loa now more than ever, but she has yet to return to us.\n\nThe time of her rebirth has passed. Someone, or something, must be preventing her awakening.\n\nEnter her resting place and see what you can uncover.", objectives = "Enter the Temple of Sethraliss and heal the avatar of the loa.", progress = "We cannot let Mythrax bring his destruction upon this world once more.", completion = "Behold, <name>. Sethraliss has returned." }
WordHunterWoW_QuestEN[50553] = { title = "Back to the Lab", description = "Our work here is done!\n\nWell, at least until another one of my humble experiments goes horribly awry, rapidly spiraling out of control into a chain reaction of catastrophic failures.\n\nBut, let's worry about that another time, {name}.\n\nI'll meet you back at my lab!", objectives = "Meet Raimond Mildenhall in his Raimond's Laboratory.", completion = "Well, we had quite the adventure <name>.\n\nLet's try not to do that again anytime soon though!" }
WordHunterWoW_QuestEN[50559] = { title = "Getting Out of Hand", description = "", objectives = "" }
WordHunterWoW_QuestEN[50561] = { title = "Sulthis' Stone", description = "<The ancient reliquary contains a single stone, humming with magic. Perhaps Serrik will know what it is?>", objectives = "Deliver Sulthis' Stone to Serrik within Zul'Ahjin.", progress = "What have you found?", completion = "This stone... I've seen one like it before." }
WordHunterWoW_QuestEN[50562] = { title = "Champions of Azeroth", description = "Assist Magni by completing 4 Azerite world quests.", objectives = "Complete 4 Azerite world quests.", progress = "Return to me when you have finished aiding Azeroth, <name>.", completion = "Azeroth and myself thank you." }
WordHunterWoW_QuestEN[50564] = { title = "Azerite Infused Slag", description = "", objectives = "" }
WordHunterWoW_QuestEN[50566] = { title = "Lost Scroll", description = "", objectives = "" }
WordHunterWoW_QuestEN[50568] = { title = "Chag's Challenge", description = "", objectives = "" }
WordHunterWoW_QuestEN[50570] = { title = "Azerite Infused Elemental", description = "", objectives = "" }
WordHunterWoW_QuestEN[50571] = { title = "Eggstermination", description = "", objectives = "" }
WordHunterWoW_QuestEN[50572] = { title = "Bloody Intrusion", description = "", objectives = "" }
WordHunterWoW_QuestEN[50573] = { title = "Message from the Management", description = "<This letter from Priscilla Ashvane to her employees appears to be posted all over the foundry.\n\nIt sounds like Cagney's information was accurate, Ashvane is working their people around the clock.\n\nPriscilla mentions a Forgemaster Farthing and a Taskmaster Williams. They may have more information about her plans.>", objectives = "Collect Priscilla's Orders from Forgemaster Farthing and Taskmaster Williams.", progress = "Find anything useful in there?", completion = "Most folks workin' for the Ashvane Trading Company don't know how rotten they are, or don't have any other choice.\n\nThe sooner we take down Priscilla the better." }
WordHunterWoW_QuestEN[50574] = { title = "Preservation Methods", description = "", objectives = "" }
WordHunterWoW_QuestEN[50576] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[50577] = { title = "Unaccounted For", description = "", objectives = "" }
WordHunterWoW_QuestEN[50578] = { title = "Bring Ruin Again", description = "", objectives = "" }
WordHunterWoW_QuestEN[50581] = { title = "Scrolls and Scales", description = "", objectives = "" }
WordHunterWoW_QuestEN[50583] = { title = "To the Other Side", description = "It looks like the coven is using Corlain as a base of operations. There's no way we'll be able to cut through this many of them without the rest of the Inquisitors.\n\nThey must still be stuck behind the wall. \n\n{class}, there are three smaller footmen gates along the walls into Corlain. See if you can get them open so our allies can make their way through.", objectives = "Open the Eastern, Southern, and Western Gates in Upper Corlain.", progress = "What news of the other inquisitors?", completion = "All here and accounted for?\n\nVery well, we've no time to waste. We must ride to Waycrest Manor!" }
WordHunterWoW_QuestEN[50584] = { title = "Ruinous Rituals", description = "Take a look in the city square, {class}.\n\n<Marshal Reade gestures toward a ritual being performed by some disciples in the distance.>\n\nIt appears the coven has gone beyond dark constructs, and are now conjuring creatures of nightmare with their rituals. Let us not wait to see what these monsters are capable of. We should put an end to them right here.\n\nFortunately, the disciples seem too focused on their spell to notice us. Maybe you can use that to your advantage.", objectives = "Kill 4 Blighted Horrors in Upper Corlain.", progress = "Have the monsters been abolished?", completion = "I am glad we were able to stop those things here, before the coven could unleash them on Drustvar's unsuspecting citizens." }
WordHunterWoW_QuestEN[50585] = { title = "Hexecutioner", description = "It would appear that this is where the coven is training their new acolytes. Our efforts may be for naught if they continue to expand their numbers.\n\nI cannot leave Lucille's side in this place, but you have already shown yourself a formidable combatant. \n\nCut them down.", objectives = "Kill 13 witches of the Heartsbane Coven in Upper Corlain.", completion = "The people of Drustvar will sleep more soundly with less witches in the world." }
WordHunterWoW_QuestEN[50586] = { title = "The Fall of Corlain", description = "<This discarded journal looks like it belonged to one of the residents of upper Corlain. Within it details some early signs of the Heartsbane's appearance in Corlain.\n\nIf you can find more writings like this, you might be able to piece together the events that led to Corlain's current state.>", objectives = "Examine 6 Corlain Citizen's Journals in Upper Corlain.", completion = "This tale... such a tragic fate to befall my home...\n\nWe must make this right, <class>!  For the people of Corlain and all of Drustvar!" }
WordHunterWoW_QuestEN[50587] = { title = "Nagative Feedback", description = "", objectives = "" }
WordHunterWoW_QuestEN[50588] = { title = "Storming the Manor", description = "Now is our chance. Waycrest Manor is just up that hill, and hopefully inside we'll find my mother and father. \n\nIf we also manage to find the \"Mother\" that's leading this horrible coven, then we will make her regret the day she ever set foot in Drustvar.\n\nAre you with me, {class}?", objectives = "Follow Lucille Waycrest toward Waycrest Manor in Upper Corlain.", completion = "I'm sorry... this is all a bit too much...\n\nThank you, <class>, for protecting me.  I think I'm going to need a moment..." }
WordHunterWoW_QuestEN[50591] = { title = "Son of a Bee", description = "", objectives = "" }
WordHunterWoW_QuestEN[50592] = { title = "Tiny Terror", description = "", objectives = "" }
WordHunterWoW_QuestEN[50593] = { title = "A Bloody Mess", description = "<The vial is filled with a viscous, bubbling substance. It bears a striking resemblance to the animated horrors around you.\n\nIt struggles against the container, as if trying to escape. Pike would surely be interested in more samples.>", objectives = "Collect 20 Tideblood.", progress = "What is that you have there?", completion = "This tideblood is saturated with dark magic. Thank you for bringing it to me." }
WordHunterWoW_QuestEN[50594] = { title = "Beneath the Veil", description = "We must board the Abyssal Melody and save the myriad souls in her decks before they too disappear into the Shrine. We will not be able to enter so long as the barrier surrounding it stands.\n\nThe tidesages are using forbidden magic to summon extensions of their will. It is these grasps that maintain the barrier.\n\nTake my beacon and mark each grasp. I will rain vengeance down upon them from here.", objectives = "Use the Abyssal Beacon to dispel the Writhing Grasps.", progress = "Have the grasps been dealt with?", completion = "The Abyssal Melody lies unprotected. Now is our chance." }
WordHunterWoW_QuestEN[50595] = { title = "No Quarter", description = "We arrived just in time. These abominations have already taken control of the docks; we're all that's left to keep them at bay!\n\nYou need to cull their numbers before we're overwhelmed. We don't exactly have an army here!", objectives = "Kill 8 Skeletal Sailors and 4 Tidesage Seacallers.", completion = "We're holding out alright thanks to you, but Sam is still missing!" }
WordHunterWoW_QuestEN[50596] = { title = "Exterminate the Vermin", description = "On top of the fury of the overseer, and this \"key\" not being here, we have a pest problem.\n\nSneaky little vulperan thieves keep ransacking our site. We have taken some prisoner.\n\nWe have them around the upper level of the dig site, working off their misdeeds. However, I believe a more permanent solution would be preferred. \n\nPlease, oh mighty cobra, give us the honor of getting rid of our prisoners with your most potent venom!", objectives = "Rescue 3 captive excavators.", progress = "They had what?", completion = "Well played on the rescue. I can't decide if you're clever, or they're stupid. I like your odds, though!" }
WordHunterWoW_QuestEN[50598] = { title = "Zandalari Empire", description = "Assist the Zandalari Empire in Zuldazar by completing 4 world quests.", objectives = "Complete any 4 world quests in Zuldazar.", progress = "Return to me when you have finished aiding da Zandalari Empire, <name>.", completion = "Da Zandalari Empire thanks you." }
WordHunterWoW_QuestEN[50599] = { title = "Proudmoore Admiralty", description = "Assist the Proudmoore Admiralty by completing 4 world quests.", objectives = "Complete any 4 world quests in Tiragarde Sound.", progress = "Return to me when you have finished aiding the Proudmoore Admiralty, <name>.", completion = "Good work!" }
WordHunterWoW_QuestEN[50600] = { title = "Order of Embers", description = "Assist the Order of Embers by completing 4 world quests.", objectives = "Complete any 4 world quests in Drustvar.", progress = "Return to me when you have finished aiding the Order of Embers, <name>.", completion = "The Order of Embers thanks you." }
WordHunterWoW_QuestEN[50601] = { title = "Storm's Wake", description = "Assist Storm's Wake by completing 4 world quests.", objectives = "Complete any 4 world quests in Stormsong Valley.", progress = "Return to me when you have finished aiding Storm's Wake, <name>.", completion = "The tides spoke of your triumphs. Thank you." }
WordHunterWoW_QuestEN[50602] = { title = "Talanji's Expedition", description = "Assist Talanji's Expedition by completing 4 world quests.", objectives = "Complete 4 Talanji's Expedition world quests.", progress = "Return ta me when you have finished aiding Talanji's Expedition, <name>.", completion = "I thank you in da name of da princess." }
WordHunterWoW_QuestEN[50603] = { title = "Voldunai", description = "Assist the Voldunai by completing 4 world quests.", objectives = "Complete 4 Voldunai world quests.", progress = "Return to me when you have finished aiding the Voldunai, <name>.", completion = "The Voldunai thank you." }
WordHunterWoW_QuestEN[50604] = { title = "Tortollan Seekers", description = "Assist the Tortollan by completing 3 world quests.", objectives = "Complete 3 Tortollan world quests.", progress = "Return to me when you have finished aiding the Tortollans, <name>.", completion = "You young-shells continue to surprise me." }
WordHunterWoW_QuestEN[50605] = { title = "Alliance War Effort", description = "Assist the Alliance by completing 4 world quests on Zandalar or occupied warfront zones.", objectives = "Complete 4 world quests on Zandalar or occupied warfront zones.", progress = "Return to me when you have finished aiding the Alliance, <name>.", completion = "For the Alliance!" }
WordHunterWoW_QuestEN[50606] = { title = "Horde War Effort", description = "Assist the Horde by completing 4 world quests on Kul Tiras or occupied warfront zones.", objectives = "Complete 4 world quests on Kul Tiras or occupied warfront zones.", progress = "Return to me when you have finished aiding the Horde, <name>.", completion = "For the Horde!" }
WordHunterWoW_QuestEN[50608] = { title = "Forbidden Rites", description = "These k'thir have been hiding among us, sowing the seeds of their dark masters with us none the wiser.\n\nWith the barrier around the Abyssal Melody lowered I can peer within; its bowels toil with my own people giving themselves to the shadow!\n\nTake my tidal kris; its blade is now coated in purified tideblood. Put an end to these fiends and their foul rituals.", objectives = "Kill 15 K'thir and disrupt 6 rituals.", completion = "Good. Each death brings this valley one step closer to redemption." }
WordHunterWoW_QuestEN[50609] = { title = "From the Maw of Madness", description = "Sam is still out there somewhere. We can't just leave him to die!\n\nIf he wasn't in the assembly yard, he must be on that ship. You have to find him!", objectives = "Find Samuel Williams.", completion = "That was a tight spot you got me out of back there. I owe ya my life." }
WordHunterWoW_QuestEN[50610] = { title = "Gathering Storm", description = "This depravity goes against every oath we take as tidesages. To protect our people... to guide and sustain them... to make our ships strong.\n\nThis is nothing but darkness. It must all be destroyed.\n\nBoard the Abyssal Melody and place these focusing rods at any critical points you find. I will prepare the ritual.", objectives = "Place 4 Focusing Rods on the Abyssal Melody.", completion = "Now to finish the deed." }
WordHunterWoW_QuestEN[50611] = { title = "Storm's Vengeance", description = "I know not what horrors await us ahead, but the Abyssal Melody must never follow its sister into the Shrine of the Storm.\n\nWe will deny these monsters all that they have wrought here by burning it with the very magic they seek to corrupt.\n\nThe ritual is ready, but requires a conduit to stabilize. If you are willing, I would have you guide my magic.", objectives = "Destroy the Abyssal Melody.", progress = "Whenever you are ready.", completion = "A pivotal step, but our work is far from finished." }
WordHunterWoW_QuestEN[50612] = { title = "A House Divided", description = "Not all of House Stormsong have followed my Lord down this dark path. They know not - I knew not - the truth of his depravity.\n\nSagehold looms above us. It is where all tidesages study to wield the sea's power.\n\nWe will build upon the Storm's Wake and make my shattered home whole once more. We will save all who are willing. \n\nThe rest will perish.", objectives = "Join Brother Pike outside Sagehold.", completion = "With any luck we will end this matter here." }
WordHunterWoW_QuestEN[50614] = { title = "Freedom for the Sea", description = "The naga along this coast appear to be trying to push the shoreline up the hill here. We've been able to keep them back at the beach so far, but they've been binding more elementals than we can keep up with.\n\nWithout a tidesage, we have no way to free the elementals from their bindings, but we cannot allow them to push forward anymore. The spirit of the sea should not be contained by anything. Slay them, and let them return to the ocean.", objectives = "Slay 6 Bound Seasurges.", progress = "For a people that live in the sea, the naga seem to have little respect for it.", completion = "That should slow down their progress quite a bit. You have my gratitude." }
WordHunterWoW_QuestEN[50616] = { title = "A Bit of a Bind", description = "The naga sorceress leading this excursion seems to be in the process of binding a larger elemental. If she succeeds, we will no doubt lose our foothold here.\n\nStrike out at her, perhaps you can catch her off guard and interrupt the ritual. Remove the head from these snakes.", objectives = "Slay Binder Sa'thress.", progress = "Is the seawitch dead?", completion = "I have no idea what this might be, but I don't like the looks of it." }
WordHunterWoW_QuestEN[50617] = { title = "Atul'Aman", description = "Jakra'zet and his troops attacked while we were away. \n\nSerrik fought well, but it wasn't enough. The keys are gone, and it's only a matter of time before the barrier is broken.\n\nYour friends have already given chase. \n\nJakra'zet must not be allowed to resurrect Mythrax the Unraveler. He must be stopped before it's too late!\n\nWe don't have much time. \n\nMeet me at Atul'Aman! We must catch up with Kaja and Rakera and stop the ritual!", objectives = "Meet Vorrik at Atul'Aman.", completion = "We must hurry. Your friends are already inside!" }
WordHunterWoW_QuestEN[50619] = { title = "What Goes Up", description = "", objectives = "" }
WordHunterWoW_QuestEN[50621] = { title = "Caught in the Net", description = "When the naga force first arrived, there were a handful of the local fishermen out on boats. One of our scouts reports that most of them have been captured and are currently being kept in cages around the beach.\n\nFree any of them you happen to find and point them back here. We'll get them armed and remind the naga that you don't mess with sailors!", objectives = "Free 5 villagers.", completion = "With these numbers, we should be able to hold our own here. Oars and fishing nets make surprisingly effective weapons." }
WordHunterWoW_QuestEN[50622] = { title = "Deal's Off", description = "There's one more farm left, far to the west. They're real close to the kraul.\n\nDeal works the land by herself. If anyone got hit bad, it'd be her. It's just past the worst part of the collapse, so keep an eye out for the quilboar.", objectives = "Search the Deal Farmstead for any survivors.", completion = "I'm glad to know the others are safe. But not for long if we don't do something about these quilboar!" }
WordHunterWoW_QuestEN[50625] = { title = "LFGDungeons - BFA - Normal Random - Nth", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[50626] = { title = "LFGDungeons - BFA - Normal Random - 1st", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[50627] = { title = "LFGDungeons - BFA - Heroic Random - 1st", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[50628] = { title = "LFGDungeons - BFA - Heroic Random - Nth", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[50632] = { title = "Battlefield Scavenging", description = "The battle rages on, but our inventory suffers.\n\nScavenge the camps for supplies. I'll make use of what you find.", objectives = "Gather supplies from Newstead, High Perch and the Circle of Elements." }
WordHunterWoW_QuestEN[50633] = { title = "Pterrible Ingredients", description = "", objectives = "" }
WordHunterWoW_QuestEN[50634] = { title = "Save Our Scrolls!", description = "", objectives = "" }
WordHunterWoW_QuestEN[50635] = { title = "The Shifting Tides", description = "I'm no tidesage, but even I can tell that whatever you have there is probably not a good sign for the bastion. \n\nThere's one of those Tortollans, Rikal, who's been helping us figure out a solution to whatever the naga are planning in front of the levee. He'd probably like to see this.", objectives = "Speak with Rikal at Fort Daelin.", completion = "Hmm.... This is concerning. Very concerning." }
WordHunterWoW_QuestEN[50636] = { title = "Ravoracious", description = "", objectives = "" }
WordHunterWoW_QuestEN[50639] = { title = "Waycrest Manor: The Fallen Mother", description = "This is all a lot to process...\n\nThe Marshal... gone? My mother... the leader of the coven? It's just too much...\n\n...but we have come too far to turn back now. It is clear that my mother and father, as I knew them, are gone.  It is time we cleansed the taint from this land.\n\nWe must take the inquisitors and find them in Waycrest Manor. We will end this, once and for all.", objectives = "Defeat Lady Waycrest in Waycrest Manor.", progress = "This must be done.", completion = "I do not relish what we've done, but it was necessary for the good of Drustvar.\n\nI only hope the sacrifices we've made will be worthwhile in the end..." }
WordHunterWoW_QuestEN[50640] = { title = "A Question of Quillpower", description = "I can't believe you managed to kill that thing. You're quite impressive, you know that?\n\nEither way, we should be getting back to Roz with our report. We're stuck in the middle of the kraul, surrounded by angry quilboar. But I have a plan!\n\nSome of the boars seem reasonable enough. I gave them a bit of my rations and they've been following me around. I bet we can use them to hitch a ride out of this place. You in?", objectives = "Ride the Ornery Battleboar out of Briarback Kraul and report to Mayor Roz.", completion = "Calvin has briefed me, but I am eager to hear your report." }
WordHunterWoW_QuestEN[50641] = { title = "Break Their Ranks", description = "This temple is our last bastion against the Faithless. We need every able fighter to defend its walls. \n\nIf you're offering to help, we won't turn you away. \n\nHead into battle and do what you can to break their ranks!", objectives = "Kill 10 Faithless attackers within the Temple Grounds.", progress = "We must defend the temple at all costs!", completion = "Our temple will not fall at the hands of the faithless!" }
WordHunterWoW_QuestEN[50642] = { title = "The Warchief Commands", description = "Silithus. That has been the name of the game... or rather, that is what I wanted the Alliance to believe. \n\nMake no mistake, Azerite is just as powerful as it is rumored to be but I have bigger plans in mind.\n\nHigh Overlord Saurfang is leading an army towards Silithus. By now, he should be in the Northern Barrens. I want you to intercept him and notify him that the preparations are complete.\n\nPreparations for what, you ask? Why, we are going to capture the World Tree.", objectives = "Find Saurfang in the Northern Barrens.", completion = "I have been awaiting your arrival, <name>." }
WordHunterWoW_QuestEN[50644] = { title = "Facing the Invaders", description = "While we try to figure out what to do with those channelers, we'll have to take shots where we can get them.\n\nOur men could use some assistance retaking parts of the lower walls. Kill some naga for me, would you?", objectives = "Slay 15 of the naga forces invading Fort Daelin.", completion = "Each one you killed is one less my men have to worry about. Thanks." }
WordHunterWoW_QuestEN[50645] = { title = "Eeling in a Big One", description = "If you are up to it, I have an idea to give the naga an amusing surprise.\n\n<Rikal slowly pulls out a scroll and waves it in your face.>\n\nI need some teeth from marine predators to cast the spell though. Luckily, the naga brought some disgusting eels with them. Go gather their fangs, and bring them back to me.", objectives = "Collect 16 Abyssal Fangs.", progress = "I can't wait to see how this goes.", completion = "That's exactly what I'm looking for. Give me a bit of time to prepare the spell." }
WordHunterWoW_QuestEN[50646] = { title = "A Quick Diversion", description = "I have halted our march until I received word that we were ready to divert.\n\nWhat comes next will be a coordinated, synchronized attack on key outposts in Ashenvale. If we act quickly, we will destroy the kaldorei's defenses and clear a path all the way to Darkshore. \n\nStormwind will surely send reinforcements to stop us. We have to conquer Teldrassil before they arrive.\n\nI will divert the troops. Meet with our operative, Lorash, outside Astranaar for further instruction.", objectives = "Find Lorash in Astranaar.", completion = "Saurfang says it's time? Excellent." }
WordHunterWoW_QuestEN[50647] = { title = "Everybody Has a Price", description = "Hundreds of rogues have already attacked kaldorei outposts in Ashenvale. On my signal, they will begin the next phase of this war: sowing chaos.\n\nMy colleague died not far from here, {name}, so I could use your help. If we stay out of sight, the town won't even know it's under attack before we have all of its guards down.\n\nI have a poison that will kill them quickly and silently. If you signal to me which targets are safe to attack without being noticed, I will put them down.\n\nWhat do you say?", objectives = "Work with Lorash to disarm Astranaar.", completion = "We did it! Hopefully the other outposts fared as well as we did." }
WordHunterWoW_QuestEN[50648] = { title = "Bubbles and Trouble", description = "", objectives = "" }
WordHunterWoW_QuestEN[50649] = { title = "Filching from Thieves", description = "The naga oft take what they want with little care for who they are taking it from. Perhaps we should do the same for them.\n\nThe sorceresses use powerful beacons to assist with their spellcasting. I could use these relics to strengthen my own ritual.", objectives = "Collect 7 Tidal Beacons.", progress = "Make sure you don't drop any of the beacons. I cannot say I know what will happen.", completion = "Ah! How powerful! These will be a great help." }
WordHunterWoW_QuestEN[50650] = { title = "Smashing Zalamar", description = "", objectives = "" }
WordHunterWoW_QuestEN[50651] = { title = "Cut Off Potential", description = "", objectives = "" }
WordHunterWoW_QuestEN[50652] = { title = "Biting the Hand that Feeds Them", description = "", objectives = "" }
WordHunterWoW_QuestEN[50653] = { title = "Reclaiming our Defenses", description = "We were holding off the naga up until the latest attack. A few of our forces are still out there.\n\nThe tidemaidens seem to be slowly torturing them to death. If you could save as many as you can find, we'd be one step closer to gaining the upper ground again.", objectives = "Save 8 stranded battalion soldiers.", completion = "That should slow down their progress quite a bit. You have my gratitude." }
WordHunterWoW_QuestEN[50656] = { title = "Risky Rescue", description = "The Faithless incursion is just up ahead. \n\nWe tried to get ahead of the siege by attacking their camp in the dead of night, but they knew we were coming. \n\nOur troops were quickly overwhelmed. \n\nWe called for a retreat, but only a few of us made it out. The fate of those that didn't is unknown...\n\nWe don't have the numbers to attempt a rescue ourselves. We can't afford to lose any more fighters. \n\nYou're their only hope.", objectives = "Free 4 Temple Defenders.", completion = "We are in your debt, <name>." }
WordHunterWoW_QuestEN[50660] = { title = "Survival Strategy", description = "", objectives = "" }
WordHunterWoW_QuestEN[50665] = { title = "Cancel the Blood Troll Apocalypse", description = "", objectives = "" }
WordHunterWoW_QuestEN[50667] = { title = "Past Due", description = "", objectives = "" }
WordHunterWoW_QuestEN[50668] = { title = "Battle for Azeroth: Tides of War", description = "Champion, the Horde is now at open war with the Alliance.\n\nOur success in this conflict may depend on your skills.\n\nI require your immediate presence in Orgrimmar for a mission of the utmost urgency. Do not keep me waiting.", objectives = "Speak with Nathanos Blightcaller in Orgrimmar.Champion, the Horde is now at open war with the Alliance.\n\nOur success in this conflict may depend on your skills.\n\nI require your immediate presence in Orgrimmar for a mission of the utmost urgency. Do not keep me waiting.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[50670] = { title = "Doug Test - Gossip Test 3", description = "", objectives = "" }
WordHunterWoW_QuestEN[50672] = { title = "Any Ammo Will Do", description = "I'll have some men move some cannons down to the sea wall in preparation of whatever ritual is going on down in that delta.\n\nWe could use some extra ammo before we spread ourselves too thin though. Luckily, those naga harpoons work well enough with our mortars. Take down those lances and bring back any harpoons that you find.", objectives = "Collect 20 Zeth'jir Harpoons on the coast south of Fort Daelin.", progress = "We can use the naga's weapons against them!", completion = "Great work! Let's hope these harpoons can fire from our cannons." }
WordHunterWoW_QuestEN[50674] = { title = "Two-Faced Pirate Scum", description = "We've been holding the Irontide off for days, but now they've brought in an ettin for reinforcements. We can't let him attack the town. \n\nA few of my best men just went up the hill to try and kill him. You look pretty capable, they could sure use your help?", objectives = "Eliminate Two Face Tom.", progress = "Hurry <name> you've got to kill the ettin.", completion = "You've got skills we could use. You want join us and find the treasure before the Irontide?" }
WordHunterWoW_QuestEN[50675] = { title = "Treasure Hunting", description = "The workers are digging day and night out there to find the lost treasure. You'd get an equal share like everyone else, if ya wanna help out.\n\nTalk to Nedly about joining up.", objectives = "Speak to Nedly.", completion = "I saw you killing those Irontide, you want in on our action?" }
WordHunterWoW_QuestEN[50676] = { title = "River Toll", description = "", objectives = "" }
WordHunterWoW_QuestEN[50679] = { title = "Piercing the Shield", description = "I've been talking with Rikal, and the tortollan says that our problem in the delta can probably be solved by turning the naga's magic back on them.\n\nA few of the sorceresses on the south coast have a channeling wand that we may be able to use to break the head priestesses' ritual channeling. Find one, and bring it back here.", objectives = "Find an intact Zeth'jir Channeling Rod.", progress = "We cannot allow this fort to fall!", completion = "Even I can feel how much power this thing contains." }
WordHunterWoW_QuestEN[50689] = { title = "It's the Pits", description = "", objectives = "" }
WordHunterWoW_QuestEN[50690] = { title = "A Flickering of Hope", description = "This pervasive darkness continues to cast shadows over our fields, hindering our harvests.\n\nCheck with Keyrra Flamestonge and see if you can help restore some order.", objectives = "Check in with Keyrra Flamestonge.", completion = "There is always work to be done, <name>. Your assistance in illuminating additional keyflames would instill hope and allow many here to return to work." }
WordHunterWoW_QuestEN[50691] = { title = "Not On Our Payroll", description = "The workers are complaining about elementals coming into the area while they're digging for treasure.  \n\nJust this morning, I had two people crushed to death! It's slowing down the hunt! \n\nYou can earn your share by getting rid of those elementals!", objectives = "Eliminate 10 Restless Stones.", completion = "I almost trust you <race>." }
WordHunterWoW_QuestEN[50694] = { title = "A Bloody Mess", description = "My order blesses every Kul Tiran ship within the halls of the Shrine of the Storm. Our blessings make our ships the strongest in all of Azeroth; the fleet of legend.\n\nThe ritual requires a substance known as tideblood. It is a viscous, powerful substance dredged from the depths of the sea and infused into the very hull of each ship.\n\nSomething has caused the tideblood here to become animate. Studying it may help us better understand our enemy.", objectives = "Collect 20 Tideblood.", progress = "The more tideblood you can bring me, the better.", completion = "Thank you. This will help us indeed." }
WordHunterWoW_QuestEN[50695] = { title = "It's Never Time for Cannibalism", description = "", objectives = "" }
WordHunterWoW_QuestEN[50696] = { title = "Fun With Magnets", description = "My last time in Tol Barad I had to leave in a big hurry, but I grabbed a few gadgets on the way out.  \n\nThis device is one of my favorites, so don't break it! It'll suck the treasure right out of the mud. It may make you tingle some, that's just the radiation.\n\nFind lost coins using the metal collector near the signs I've placed.", objectives = "Collect 60 Lost Coins.", progress = "I like gold, let's find some!", completion = "You got the coins, and only mild radiation poisoning." }
WordHunterWoW_QuestEN[50697] = { title = "Bomb Beats Rock", description = "I stole an old treasure map off an Irontide pirate. The map marks several caves on it with circles. \n\nThe caves are blocked by boulders, but now that you're here, we're going to open them up.\n\nYou get to do all the dangerous stuff, plant explosives, kill things, and cave exploring.  I'll supervise.", objectives = "East and West Caves blown open!", completion = "Boom!  Problem solved." }
WordHunterWoW_QuestEN[50698] = { title = "Problem Solving with Gunpowder", description = "Fort walls only go so far when it comes to defense. We've got cannons in position to fire if the naga get too close, but we need some fortifications further out.\n\nThere should be a few good areas to set up some traps further down the beach. Those naga will never know what hit them!", objectives = "Set 5 Explosive Traps.", completion = "If you run across any other opportune spots, feel free to set up more mines." }
WordHunterWoW_QuestEN[50699] = { title = "Worker's Rights", description = "Hey, you! You lookin' for work?\n\nI ain't got a job for ya, but I can tell ya to stay away from Algerson Lumber!\n\nAlgerson'll promise ya some solid labor work and decent pay, but it's a lie I tell ya!\n\nThe conditions are terrible, we're gettin' attacked, and Algerson ain't even battin' an eye!\n\nHe don't care 'bout us little people. I'd stay away if I were you!", objectives = "Talk to Maynard Algerson at Algerson Lumber Yard.", completion = "Why hello! Welcome to Algerson Lumber. How may I help you?" }
WordHunterWoW_QuestEN[50700] = { title = "Drust in Time", description = "A few days ago, a band of Alliance researchers that called themselves the \"Explorers' League\" took a contingent of Kul Tiran soldiers to the old Drust ruins down the road.\n\nWe haven't really heard from them since, and I'm growing a bit concerned. I can't leave my post, so can you check up on the team?", objectives = "Find the Explorers' League members at the Thovas Base-Camp.", completion = "We might have a wee problem on our hands." }
WordHunterWoW_QuestEN[50702] = { title = "Defeat Jakra'zet", description = "Jakra'zet is summoning Mythrax the Unraveler!\n\nWe cannot allow the ritual to continue. Jakra'zet must be stopped before it's too late!\n\nLead the way, {name}. We'll be right behind you.\n\nLet's go!", objectives = "Defeat Jakra'zet.", completion = "It's a miracle we survived..." }
WordHunterWoW_QuestEN[50703] = { title = "Informing the Horde", description = "General Jakra'zet has been defeated, but his plan to summon Mythrax succeeded despite our best efforts.\n\nWere it not for the mercy of Sethraliss, I doubt we would have made it out of Atul'Aman alive.\n\nWe must inform our allies of what has transpired in Vol'dun.\n\nI'll speak with princess Talanji myself. You should go and speak with the Horde. We need all the help we can get now.\n\nI'm sure our paths will cross again, {name}. It was an honor fighting with you.", objectives = "Speak with Baine Bloodhoof.", completion = "I shall inform the Dark Lady of your activities in Vol'dun at once. She will know how to best proceed against this  new threat." }
WordHunterWoW_QuestEN[50704] = { title = "Anchors Aweigh Too Much", description = "I got a little deal on the side, selling used ship parts to Addington Shipyards.\n\nWhile you're out looking for the treasure, see what sort of useful parts you can salvage from the mud: anchors, cannons, whatever!\n\nWe'll sell them to Addington and cut you in for a share of the profits.", objectives = "Find 12 Old Ship Parts.", progress = "See what you can find out in the mud.", completion = "We'll make good money off these. No one will know they are used parts." }
WordHunterWoW_QuestEN[50705] = { title = "A Snake with Three Heads", description = "Now that all of the preparation has been done, it's time to tackle the main threat.\n\nYou can use the channeling rod you just found in conjunction with this scroll I got from Rikal to break the shields around the naga leaders in the delta.\n\nHurry! Stop them before they finish their summoning!", objectives = "Slay the three naga channelers.", completion = "Well, the bubble seems to be gone, but I don't like the looks of that whirlpool." }
WordHunterWoW_QuestEN[50706] = { title = "Clearing the Delta", description = "The greatest of the Zeth'jir offensive sits within the delta as we speak, waiting for the summoning ritual to be finished. If we can clear out a number of them, we'll finally have the upper hand.\n\nGet down there and cause as much chaos as you can!", objectives = "Kill 15 naga forces in the Eventide Delta.", progress = "This fort will always stand in defense of Kul Tiras!", completion = "Good work! That should deter the naga for now." }
WordHunterWoW_QuestEN[50709] = { title = "Resourceful Recon", description = "We received word an Alliance surveyin' party was spotted leavin' Drywhisker Mine in a hurry. Now I don't know what they was up to, but I'll bet ya they didn't gather all their belongings before headin' out.\n\nHurry on over and see what you can find.\n\nI'll talk it over with Pixy and see what materials we can shore up in case ya stumble upon something particularly interesting.", objectives = "" }
WordHunterWoW_QuestEN[50717] = { title = "Don't Stalk Me, Troll", description = "", objectives = "" }
WordHunterWoW_QuestEN[50718] = { title = "Agent of Death", description = "", objectives = "" }
WordHunterWoW_QuestEN[50733] = { title = "A New Dawn", description = "House Stormsong may be lost, but this valley still holds so much hope. \n\nSam knew that from the beginning.\n\nWe have to continue to help the Storm's Wake in any way we can. There are still remnants of the fallen house everywhere, and whoever turned them to this darkness is out there as well.\n\nCyrus and the others will want to hear about everything that happened. We should tell them together.", objectives = "Meet Taelia in the Harbormaster's Office in Boralus.", completion = "I've filled them in on most of the details already. The Storm's Wake will be an invaluable ally if we're to reunite Kul Tiras." }
WordHunterWoW_QuestEN[50735] = { title = "Burial Detail", description = "", objectives = "" }
WordHunterWoW_QuestEN[50737] = { title = "Silence the Speakers", description = "", objectives = "" }
WordHunterWoW_QuestEN[50738] = { title = "A Timely Arrival", description = "My end of the bargain is done, {race}. \n\nI am going to check on the other outposts to make sure none of my brothers and sisters are in trouble. Meet with the Warchief and inform her that Astranaar has been secured. If everything has gone according to plan, she should be well on her way.\n\nOh, and try not to hog all the glory, yeah? \n\n<Lorash smirks at you>.", objectives = "Greet Warchief Sylvanas Windrunner in Astranaar.", completion = "That was a perfectly executed strike, <name>." }
WordHunterWoW_QuestEN[50739] = { title = "Missing Business", description = "Poor little Coda has been in quite the tizzy since his friends vanished. \n\nI found him here, out cold, after a sting from one of those awful wasps. Just a tiny bit of our sandstinger remedy got Coda right up, though!\n\nTake some with you, and keep an eye out for other little ones out there.", objectives = "Rescue 7 Sable Polecats.", progress = "Did you find them all?", completion = "Oh thank goodness! We'll have to keep these little guys away from anything with a big mean stinger out here. Man, I'm going to be busy. \n\nIf you could protect Coda's little brother, that would help us out a lot!\n\nThis is Poda!" }
WordHunterWoW_QuestEN[50740] = { title = "Zoram'gar Outpost", description = "Saurfang shall establish our troops here, now that Astranaar is ours. I shall continue my hunt for the only creature that can stop our march to victory: Malfurion Stormrage.\n\nOur next order of business will be to establish a foothold at the base of Darkshore. Commander Grimfang of the Zoram'gar Outpost should be able to accommodate an incoming army.\n\nInform him of our arrival and ensure the necessary preparations are made.", objectives = "Make the necessary preparations at the Zoram'gar Outpost.", completion = "A force this large has not moved in Ashenvale in a long time. I hope Zoram'gar is ready to accommodate the might of the Horde." }
WordHunterWoW_QuestEN[50741] = { title = "Don't Turtle", description = "There's a Tortollan who's trying to get our treasure! He's over on the west side of town.  He's nosey and he may have found something!\n\nTalk to Moxie. Come up with a plan to get rid of him.", objectives = "Speak with Moxie.", progress = "You deal with that Tortollan yet?", completion = "Worm meat for the box full of treasures!  You sure you're not a Goblin?" }
WordHunterWoW_QuestEN[50742] = { title = "All Laid Out For Us", description = "<This is all the treasure Calico McGee's found so far. Packed up and ready to move out. More like all laid out for you to take!\n\nYou'll need a few extra hands to carry this much loot. There should be some Treasure Hunters from Deadwash around.\n\nAsk Big Find Balor, Toothless Eddard, and Chopper Darry to help.>", objectives = "Get three treasure hunters to help you.", completion = "Plundered McGee's treasure? Who's the pirate now!" }
WordHunterWoW_QuestEN[50743] = { title = "The Immediate Problem", description = "I sent one of my lieutenants, a woman by the name of Bauer, to the fishermen's hamlet just down the road. We received a few reports of naga activity spreading down the coast in that direction.\n\nWe need those forces back as soon as possible. I would ask that you join her in assisting the villagers of the hamlet.", objectives = "Speak with Lieutenant Bauer.I sent one of my lieutenants, a woman by the name of Bauer, to the fishermen's hamlet just down the road. We received a few reports of naga activity spreading down the coast in that direction.\n\nWe need those forces back as soon as possible. I would ask that you join her in assisting the villagers of the hamlet.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[50744] = { title = "Refresh Their Memory", description = "", objectives = "" }
WordHunterWoW_QuestEN[50745] = { title = "Infiltrating the Empire", description = "The heart of the Faithless empire rests just beyond this ridge. We will need to move swiftly and quietly to avoid detection once inside.\n\nThankfully, my former dwelling is nearby. I know a passage that should allow us to advance into the fortress with minimal resistance. When you are ready, speak with me and I will show you the way.\n\n<Vorrik looks around suspiciously.>\n\nI expected the Faithless to patrol this area... Keep your eyes open for anything suspicious along the path.", objectives = "Accompany Vorrik to his sanctum.", completion = "It's unconventional, but I believe Sethraliss would be pleased to see her shrine used to protect innocents in need.\n\nAnd if these vulpera are fighting the Faithless, they will be useful allies." }
WordHunterWoW_QuestEN[50746] = { title = "Crater Conquered", description = "I can take it from here, {name}. I'll rally these vulpera and march through the trenches creating chaos. Korthek and his armies will be forced to deal with us!\n\nIf you and Vorrik are going to make a move, you should do it now.", objectives = "Return to Vorrik.", completion = "I can hear the vulpera battle cries from here. It seems your friends have given us a window of opportunity. We musn't waste it.\n\nI have a plan." }
WordHunterWoW_QuestEN[50747] = { title = "No Good Amani", description = "", objectives = "" }
WordHunterWoW_QuestEN[50748] = { title = "Don't Drop It... Yet", description = "The Faithless are training pterrordaxes as mounts so that they can rain down death from the skies.\n\nTheir skycallers have developed a means of storing volatile lightning magic into fragile crystals. Lightning bombs, in the simplest sense. The magic behind it is quite brilliant, really.\n\nThe bombs will be exceptionally useful if we can secure the aid of Rakjan, the powerful and fierce pterrordax at the top of this mountain.\n\nAcquire as many as you can carry, while I will do my best to recruit Rakjan.", objectives = "Collect 6 Volatile Lightning Bombs from Faithless.", progress = "There are no end to the Faithless, so grab as many as you can carry.", completion = "Excellent! Rakjan appears willing to aid us, so we will certainly make good use of these." }
WordHunterWoW_QuestEN[50749] = { title = "Free Ride", description = "One thing I've learned during my time in Vol'dun is to not stay in one place for too long. And doubly so when the Faithless are involved.\n\nWe've done our damage here. Let's move before we get caught.\n\nI procured a mount to take us back to Meerah and the others in Vorrik's Sanctum quickly. Don't worry, this Faithless won't be needing it anymore.", objectives = "Steal the Battle Krolusk mount and return to Meerah.", completion = "I'll have some of the vulpera stable that krolusk outside, in case we need to use it again." }
WordHunterWoW_QuestEN[50750] = { title = "Infuriating the Emperor", description = "It seems I underestimated Korthek's cowardice. I expected him to be behind the barrier, ready to ambush us. Yet, still he hides.\n\nThat allows us a few moments to prepare. We musn't waste them.\n\nWhile I siphon power off of these immense crystals, you must thin the numbers of the Faithless here. I will grant you a powerful boon to speed you in your task.\n\nWhen Korthek arrives, he will require our full attention.", objectives = "Use Vorrik's Bulwark to defeat 75 Faithless within the Sacred Sands.", completion = "Excellent. Now we may focus on Emperor Korthek without distractions." }
WordHunterWoW_QuestEN[50751] = { title = "Sanctuary Under Siege", description = "I fear that Emperor Korthek was not lying when he boasted of his foolish plan.\n\nIf General Jakra'zet attacked the Sanctuary of the Devoted while we were away, there is a good chance that he now has everything needed to resurrect Mythrax.\n\nWe must hurry to the Sanctuary and stop Jakra'zet. Mythrax must not be reborn!", objectives = "Meet Vorrik at the Sanctuary of the Devoted.", completion = "We're too late. The keys are gone. \n\nSethraliss... What have I done?" }
WordHunterWoW_QuestEN[50752] = { title = "Relics of Sethraliss", description = "It may surprise you to learn that the Faithless hoard ancient relics of Sethraliss. I assure you that they do not do so out of reverence or respect, as is proper.\n\nKorthek's brood is driven only by greed and an insatiable lust for power. They rip whatever magic they can from the relics, even if it means destroying them in the process.\n\nRescue the ancient artifacts of Sethraliss in the Sacred Sands nearby. We will honor and preserve them in the Sanctuary of the Devoted.", objectives = "Recover the Skull of the First Skycaller, Rebirth Creed, Sethraliss Sight Stone, and Blood of the Fallen Loa.", progress = "Do you have the artifacts?", completion = "Incredible! I remember when some of these were first found...\n\nYou've done all followers of Sethraliss a kindness this day, <name>." }
WordHunterWoW_QuestEN[50753] = { title = "Earl-E Bot Gets the Worm", description = "It could take you days to get that much meat, and I don't want to wait around. So, we'll use a Bot as bait!  \n\nYou send EARL-E towards any disturbances you see in the mud. He'll make enough noise to scare any worms out.  \n\nThen kill the worms, get the meat. I'll watch from here.", objectives = "Get Mud Worm Meat for Maokka.", progress = "Do you have the meat yet?", completion = "This will make a nice Mud Worm Soup. I wasn't liking this box anyway." }
WordHunterWoW_QuestEN[50754] = { title = "To Have Loved and Lost", description = "I have a favor to ask you of a... personal nature.\n\nWhitegrove Chapel lies to the north, just past the town of Corlain. Someone... important to me rests in the graveyard on its grounds.\n\nI've been unable to visit his grave for some time, and I would like to pay my respects. If you come upon Whitegrove Chapel, could you lay these flowers next to his headstone?\n\nJust look for the most recent grave there...", objectives = "Lay the Crimson Bouquet next to the Simple Gravestone in Whitegrove Chapel.", completion = "Lucy sent you? I am relieved to hear she yet lives. \n\nMy name is Alexander Treadward. I am... well, I was Lucy's fiance." }
WordHunterWoW_QuestEN[50755] = { title = "A Meal for Birds", description = "I don't know why I agreed to this. We weren't supposed to be scavenging. \n\nKiro gave me specific instructions to head to the basin and feed the buzzards.\n\nI can't go back to camp until they eat, but I'm not heading into that basin while the sethrak are still swarming. \n\nHave you ever fed a buzzard? It's easy, I promise. \n\nYou kill it, they eat it. That simple.", objectives = "Kill wildlife within The Brine Basin so Mekaru's buzzards can eat.", progress = "They still look hungry to me.", completion = "I don't think I've ever seen these buzzards so satiated. How much did you feed them exactly? \n\nDoesn't matter. You saved my tail, for sure." }
WordHunterWoW_QuestEN[50756] = { title = "Subterranean Evacuation", description = "", objectives = "" }
WordHunterWoW_QuestEN[50757] = { title = "Untame Slaughter", description = "The Faithless rely on their krolusks for everything. They are mounts, battle companions, beasts of burden, and often even food to fuel the sethrak empire.\n\nIf we can disrupt their krolusks, we'll disrupt their whole empire. One broken wheel stops the caravan, eh?\n\nTake out as many of their krolusk tamers as you can. That'll have a longer impact than just killing the krolusks.", objectives = "Kill 8 Faithless within the Feeding Pits.", completion = "The Faithless will be nursing that wound for awhile. Well done." }
WordHunterWoW_QuestEN[50758] = { title = "Painful Memories", description = "A terrible thing happened in this place, and it has doomed me to an eternity of walking these grounds.\n\nAll I remember is that Lucille and I were to be wed, but instead I met my end.\n\nIf you have an ounce of sympathy in your heart, then I beg you to help me. Find out what happened that night, so I might leave here.\n\nI know my strongest memories are tied to the ring I bore for Lucy that day. Find it among my bones, and maybe it will lead you to the answer.", objectives = "Search the Forgotten Bones for Treadward's Ring in Whitegrove Chapel.", completion = "Welcome, kind sir!\n\nThe ceremony should begin as soon as the good Lord Waycrest arrives." }
WordHunterWoW_QuestEN[50759] = { title = "Running Late", description = "I beg your pardon, but I am a little concerned at Lord Waycrest's tardiness.\n\nI'd hate to be a bother, but would you mind checking on him? The ceremony awaits his presence.\n\nYou can find him in the bride's room, at the top of the tower.", objectives = "Speak with Lord Arthur Waycrest in Whitegrove Chapel.", progress = "It must be around here somewhere...", completion = "Splendid! I'll just need to take a few moments to go over this and I'll be right down.\n\nPlease let Lucy and Alexander know I will be ready shortly." }
WordHunterWoW_QuestEN[50760] = { title = "From This Day Forward", description = "Lord Waycrest is on his way? Excellent!\n\nYou have my thanks, sir. Please, take a seat.", objectives = "Take a seat and observe the wedding ceremony in Whitegrove Chapel.", completion = "What is going on here!?" }
WordHunterWoW_QuestEN[50761] = { title = "Blood in the Chapel", description = "Sir, you have helped me before and I beseech you to do so again.\n\nMy guards are clearly outnumbered by these brigands. I must stay here to protect Lucille, so I will need you to assist in protecting the guests.\n\nAre you able?", objectives = "Defeat 10 Red Hand Assassins in Whitegrove Chapel.", progress = "We must rout these knaves!", completion = "Well done! My guards seem to have gained the upper hand, thanks to you.\n\nBut wait... where is Meredith?" }
WordHunterWoW_QuestEN[50762] = { title = "The Lady's Fate", description = "Meredith never joined the ceremony. She might be in trouble!\n\nLucy is in shock, and I cannot leave her here. You must go in my stead to the tower, and ensure the safety of your Lady.\n\nDo this for me, and you will be rewarded.", objectives = "Find Lady Meredith Waycrest in Whitegrove Chapel.", progress = "What have you found?", completion = "Her mother ordered the assassination!?\n\nI had known that she didn't agree with Lucy marrying a merchant, but I would never suspect she would go so far to prevent it!\n\nThank you, <class>." }
WordHunterWoW_QuestEN[50763] = { title = "One Last Request", description = "I can feel my bonds to this place slipping, and I have you to thank.\n\nI would like to ask one more favor of you though. Please bring the ring you found to Lucille. It was meant for her to hold, not my dusty bones.\n\nAnd {class}, do not tell her what has transpired here. She has enough tragedy weighing down her heart. I do not wish to add to it.", objectives = "Bring Treadward's Ring to Lucille Waycrest at Watchman's Rise.", progress = "What... what's this?", completion = "This... this is the ring Alexander was to give me at our wedding.  I had thought it long lost...\n\nI do not know how you found this, <class>, but words cannot say how grateful I am. Alexander was very dear to me, and this ring was a symbol of the strength of our love.\n\nIt is good to feel that again..." }
WordHunterWoW_QuestEN[50764] = { title = "Redemptive Refurbishment", description = "Looks like our boys took down a few of those pesky flying machines.\n\nIf ya stumble across any spare parts while you're out I can continue my work on our secret weapon.", objectives = "" }
WordHunterWoW_QuestEN[50765] = { title = "Herding Children", description = "", objectives = "" }
WordHunterWoW_QuestEN[50767] = { title = "The Scrimshaw Gang", description = "", objectives = "" }
WordHunterWoW_QuestEN[50769] = { title = "The Stormwind Extraction", description = "My lady is shrewd indeed. If we are to infiltrate Stormwind City, we will need the very best the Horde has to offer, and yet a team so small as to be able to infiltrate the heart of Alliance territory unseen.\n\n<Nathanos peers at the gathered group, stroking his chin.>\n\nYes, I see.\n\nThe path ahead is clear. Speak to me when you are ready to undertake the Warchief's mission, {name}.", objectives = "Complete \"The Stormwind Extraction\" scenario.", progress = "We must not fail the Warchief.", completion = "Well, here we are. Zuldazar. We had better stick with Talanji and Zul for now. The Warchief will be interested to know what happens next." }
WordHunterWoW_QuestEN[50770] = { title = "Effective Antivenom", description = "The salve is ready. \n\nI work fast. Hopefully faster than the scorpid poison. \n\nTake this antivenom to your friend and see that he swallows every last drop. \n\nYou should know within moments if it's been effective.", objectives = "Administer the Antivenom to Serrik.", completion = "Thank you for saving my life. I'm afraid we don't have time for formal introductions." }
WordHunterWoW_QuestEN[50771] = { title = "Calldown: Cleaner", description = "With these dust blowin' siro-ma-whosits all over this beach front, it's a pain to get our cleaners out onto the nodes.\n\nSome of the crew wanted to check somewhere else, but no way we're leaving without those rocks for Gallywix. \n\nBetween you and me, {class}, we're gonna be gettin' some serious hazard pay for this gig.", objectives = "Identify and mark 5 Azerite deposits for the extraction team.", progress = "All the resources been harvested?", completion = "Not bad, chief! The crew should be wrapping it up soon." }
WordHunterWoW_QuestEN[50772] = { title = "On The Prowl", description = "Do you see all of the wisps about? I have seen this once before, when the demon Archimonde was felled by the sting of hundreds - no - thousands of wisps.\n\nThis can mean only one thing. Malfurion is beckoning the aid of his ancestors.\n\nThe Warchief has already taken a scouting party ahead to Darkshore to intercept him. Please, {name}. Find the Warchief and see if she has yet caught her prey. \n\nWe have secured all of Ashenvale, but we must keep the pressure on.", objectives = "Find Warchief Sylvanas Windrunner in Darkshore.", progress = "You may approach, <name>.", completion = "I've been tracking Malfurion's every movement. The lord of the forest cannot hope to outmatch one who served as Ranger-General of Silvermoon." }
WordHunterWoW_QuestEN[50773] = { title = "You're a Shark", description = "Have you ever been bitten by a shark? I have, numerous times. It stings.\n\nMurlocs don't usually survive shark attacks.\n\nThe ritual I had in mind is ready to cast. Let me know when you're prepared.", objectives = "Kill 20 murlocs.", progress = "I can't wait to see how this goes.", completion = "How did it feel to be a murloc's greatest fear?" }
WordHunterWoW_QuestEN[50774] = { title = "No Bot Left Behind", description = "You left Earl-E behind, and a giant worm ate him! He's got sentimental, uh... monetary value. \n\nWe don't leave any bots behind!\n\nKill that worm and get Earl-E back.", objectives = "Help Earl-E.", progress = "What? Earl-E isn't going to help himself!", completion = "You saved Earl-E! I am forever grateful <race>." }
WordHunterWoW_QuestEN[50775] = { title = "Get Us Some Beach", description = "These guys are running out of \"ammo\" faster than we can replace it! \n\nI tells 'em, we're on a beach, you're in a sandblaster, suck it up!\n\nThey says it's against the cleaner driver rules for their local chapter.\n\nI'm not buyin' it.\n\nGrab us some more sand. Them sand monsters have gotta be full of the stuff!\n\nWe'll make it worth your time.", objectives = "Collect 20 piles of sand.", progress = "Ya get us the dirt yet?", completion = "That should fill us up a few more bags. If they run out again, I'll make 'em break out the pickaxes.\n\nI bet then a little self-fueling won't sound so bad!\n\nUngrateful sons of bellybutton lint..." }
WordHunterWoW_QuestEN[50776] = { title = "False Prophets", description = "", objectives = "" }
WordHunterWoW_QuestEN[50777] = { title = "The Storm Awakens", description = "I must watch over Samuel for now. I fear for the darkness assaulting his mind.\n\nThe fallen men and women around us were defectors from the house. There will be more like them within Sagehold. \n\nFind them, and tell them 'the storm awakens'. Knowledge of our cause has spread; we need to bring all we can to our side.", objectives = "Rally 12 Defectors.", progress = "Find all you can who will stand with us. We are stronger united.", completion = "I saw some of the defectors leaving. I'm glad we got to them before Lord Stormsong did." }
WordHunterWoW_QuestEN[50778] = { title = "Twisted Intentions", description = "Sails... in the fog...\n\nA light below... in the darkness.\n\nWater rising... given form... the pain... \n\nAHHHH, THE PAIN!\n\nMake it stop. Make it stop. Make the pain stop!", objectives = "Kill the Bound Tempest and Enthralled Tidefury.", progress = "I know Sam is unwell, but I think he's onto something.", completion = "Their rituals are growing bolder. Sooner or later they're going to summon something they can't control." }
WordHunterWoW_QuestEN[50779] = { title = "A Clean Slate", description = "", objectives = "" }
WordHunterWoW_QuestEN[50780] = { title = "Oathbound", description = "I took oaths, damn it. We all did.\n\nWhen Lord Stormsong sent the first orders... well, you saw what happened. What matters is that our oaths are to our people, not Lord \"Sells His Soul\".\n\nYou won't find him here - he's deep in the Shrine by now, and no outsider will make it across the channel alive...\n\nNot without a Tideguard to open the way.\n\n<Victoria locks eyes with you.>\n\nThe Rod of Tides is the key to the front door, and it's kept here. Retrieve it and I can get you to him.", objectives = "Retrieve the Rod of Tides.", progress = "You do have the rod, right?", completion = "I see it deemed you worthy. Good." }
WordHunterWoW_QuestEN[50781] = { title = "A Bridge Too Far", description = "The bridge that once crossed this span is the only land route to the Shrine. \n\nIt appears Lord Stormsong has sealed it to buy himself more time. We have been attempting to reopen the way to no avail.\n\nHowever, the Rod of Tides you recovered may prove our solace. Veteran tideguards use it as a key of sorts to maintain the Path of Storms across these dangerous waters.\n\nWe will begin the ritual once more... if you will wield the rod.", objectives = "Use the Rod of Tides to open the Path of Storms.", progress = "Now that Lord Stormsong is aware of our intentions every moment is precious.", completion = "The way is opened at last." }
WordHunterWoW_QuestEN[50782] = { title = "Word on the Streets", description = "", objectives = "" }
WordHunterWoW_QuestEN[50783] = { title = "The Abyssal Council", description = "The tidesages have a leading council beneath Lord Stormsong. They each oversee a different aspect of the order's work.\n\nWavespeaker Reid trains initiates here in the oldest form of tidesage magic: communing with the sea.\n\nThese deaths are on his hands. It's up to us to take him down.", objectives = "Kill Wavespeaker Reid.", completion = "Well, Lord Stormsong's definitely aware of us now." }
WordHunterWoW_QuestEN[50784] = { title = "Eye of the Storm", description = "If Lord Stormsong wasn't aware of you yet, he is now. Your best shot is to reach him at the Shrine of the Storm before more of his followers fall back to his defense.\n\nI can get you in, but you'll have to protect me. I'm in no shape to take down any more of these fiends.\n\nAnd try to keep a low profile. The closer we get to the Shrine, the more power Lord Stormsong has at his disposal.", objectives = "Escort Tideguard Victoria.", completion = "This is the only way into the Shrine of the Storm." }
WordHunterWoW_QuestEN[50786] = { title = "Revenge of Krag'wa", description = "", objectives = "" }
WordHunterWoW_QuestEN[50787] = { title = "Make Our Case", description = "Katherine has trusted Priscilla Ashvane as an advisor and a close friend for many years, even before they both lost their husbands at Theramore.\n\nShe's heard the rumors about Ashvane, just like anyone. Whether by fear or loyalty, she's chosen to ignore them.\n\nIt's time to finally open her eyes.", objectives = "Reveal Lady Ashvane's treason to Katherine Proudmoore.", completion = "Damnit! Where'd she go?!" }
WordHunterWoW_QuestEN[50788] = { title = "Enemies Within", description = "We need to get Katherine to safety.\n\nHelp us take out some of these traitors!", objectives = "Slay 6 Ashvane combatants in Unity Square." }
WordHunterWoW_QuestEN[50789] = { title = "Clear the Air", description = "Looks like Priscilla had a backup plan. Her goons set off some kind of smokescreen to cover her escape.\n\nClear out that smoke so the civilians can evacuate and we can secure the area!", objectives = "Destroy 4 Smoking Payloads in Unity Square." }
WordHunterWoW_QuestEN[50790] = { title = "Hot Pursuit", description = "Priscilla's escaping on horseback! Grab one of our chargers and chase her down!", objectives = "Mount a Proudmoore Charger and chase Priscilla Ashvane.", completion = "I don't know how anyone could survive a fall like that.\n\nStill, we should be careful not to let our guard down." }
WordHunterWoW_QuestEN[50791] = { title = "Skree...", description = "<Kua'fon rests with his head under his wing.>\n\nSkree...\n\n<Perhaps the little guy could use a display of affection to raise his spirits.>", objectives = "Soothe Kua'fon by picking him up.", completion = "<Kua'fon rubs his face against your hand.>\n\nSkree." }
WordHunterWoW_QuestEN[50792] = { title = "Taking Bribes", description = "", objectives = "" }
WordHunterWoW_QuestEN[50793] = { title = "Cave Commotion", description = "Killing that worm stirred up a commotion in the caves below. The Irontide seem pretty excited. We better check it out.\n\nNedly's on his way, meet us near the caves.", objectives = "Meet up with Nedly and Moxie near the caves.", completion = "It's the Irontide! They've found treasure in the caves below us!" }
WordHunterWoW_QuestEN[50794] = { title = "Seeking Shelter", description = "I must head back to de arena. Razgaji will want to know what happened here. \n\nIf you seek shelter, you will find it at de outpost not too far from here.\n  \nI will let our leader know you're coming.\n\nBe safe, {name}.", objectives = "Find Razgaji at the Scorched Sands Outpost.", completion = "Yes, Julwaba told me to expect you." }
WordHunterWoW_QuestEN[50795] = { title = "Prepare for Trouble", description = "With the evidence you've gathered, we can prove that the Ashvane Company was behind the attack.\n\nI would have preferred to do this in private, but I don't think we'll have the luxury. Look around - company men everywhere. \n\nPriscilla's got something up her sleeve...\n\nLet's get some backup before we go in there and cause a scene.", objectives = "Speak with 4 Proudmoore Guards in Unity Square.", completion = "Alright. It's time." }
WordHunterWoW_QuestEN[50796] = { title = "SKREEEEE!", description = "<Kua'fon opens his maw and issues a continuous screech.>\n\nSKREEEEEEEEEEEEE!!!\n\n<You know what to do.>", objectives = "Feed Kua'fon.", progress = "SKREEEEEEEEEEEEEEEEEEE!!", completion = "<Kua'fon licks his chops and sighs contentedly.>\n\nSkree." }
WordHunterWoW_QuestEN[50797] = { title = "A Turtle's Invitation", description = "You have been most helpful {race}. Please visit me and the other Tortollans along the Jeweled Coast.  \n\nWe'll discuss soup and other pressing matters.", objectives = "Visit Maokka and the other Tortollans at the Jeweled Coast.", completion = "You're arrival is most timely. We could use your help!" }
WordHunterWoW_QuestEN[50798] = { title = "Out on a Limb", description = "Ah, there you are.\n\nKua'fon ran off into de jungle. I saw him head down de western path out of the Kraal but beyond that I could not say where he may have gone.\n\nThis kind of thing happens with the young. Our winged companions have a keen sense of adventure!\n\nIt would be helpful if yours could fly, but it is not yet time. I would check any reasonably high place that he could climb to, as a start.", objectives = "Find and rescue Kua'fon in the Slough.", completion = "<Kua'fon seems mighty pleased with himself.>\n\nSkree." }
WordHunterWoW_QuestEN[50800] = { title = "Into the Woods", description = "Careful, {name} -- the forest is still brimming with Stormrage's forces...\n\nLook out behind you!", objectives = "Defeat the Alliance ambush.", completion = "Malfurion will soon return with an army." }
WordHunterWoW_QuestEN[50801] = { title = "A Nose for Ptrouble", description = "Ah, yes, I was wondering when you would come to check on your little one.\n\nAs you have likely noticed, he is not here. Little ones are very curious and often seek to leave the nest before they are ready. It is often the brooding mother's job to keep them from wandering.\n\nWhat, did you think I was going to stop him?\n\n<Wingminder Goja laughs.>\n\nI heard some screeching to de west. Best hurry, or you may not have a hatchling to look after!", objectives = "Find Kua'fon in the Slough and rescue him from danger.", completion = "<Kua'fon makes a soft sound deep in his throat. He seems very pleased with himself.>" }
WordHunterWoW_QuestEN[50802] = { title = "Iron Low Tide", description = "A few years ago I tried to join the Irontide. They said I wasn't \"Irontide material\", not cruel or heartless enough! \n\nSo I teamed up with Nedly and Moxie here in Deadwash, and we started looking for treasure on our own.  \n\nLet's show these Irontide they're not \"Deadwash material\".", objectives = "Kill 10 Irontide Pirates.", completion = "No one's gonna cry about a few less pirates.  I may even dance about it!" }
WordHunterWoW_QuestEN[50803] = { title = "I Want It All Now", description = "These Irontide Raiders think they can just come in and take the treasure we've been hunting for months!\n\nBy rights, that treasure is ours! Get in there and get our share of it, before it's gone.  \n\nBy share, I mean all of it!", objectives = "Collect 12 Irontide Coin Bags.", progress = "I want every piece of that treasure in there.", completion = "I'm going to be a rich man! You're not holding out on me are ya?" }
WordHunterWoW_QuestEN[50805] = { title = "Skycaller Shutdown", description = "", objectives = "" }
WordHunterWoW_QuestEN[50808] = { title = "Halting the Empire's Fall", description = "Nazmir be havin' problem after problem, {name}. I not be knowin' how it can get much worse dan an Old God tryin' ta take over.\n\nI be makin' me way back ta Zul'jan ta lead our efforts ta keep Nazmir safe.\n\nYa should return ta Zuldazar and let Baine know what be goin' on here. Maybe he be likin' dis here underrot, who knows?\n\nI can get ya outta here and back ta Zul'jan, if ya be needin' it.", objectives = "Speak to Baine Bloodhoof within Zuldazar.", completion = "So, an Old God lurks beneath the swamp and it's barely being contained?\n\nUnbelievable. Princess Talanji was right in calling her father a fool. How could he let such a thing stay so close to his empire?\n\nI will ensure that the warchief knows of your victory... and of our new problem." }
WordHunterWoW_QuestEN[50810] = { title = "Break 'Em Out", description = "An Irontide captain \"Calico McGee\" has been trying to scare us off for days now, but it's not working.\n\nHe's ordered his men to lock everyone up and sell us as slaves! They've brought enough chains for everyone!\n\nBreak the chains and set our workers free.", objectives = "Free 10 workers.", completion = "With everyone free, we can get back to finding the treasure!" }
WordHunterWoW_QuestEN[50812] = { title = "Awakened Elements", description = "It seems that all of this infernal blasting and hammering has stirred up... something.\n\nI heard some screaming from over in that direction.\n\n<He gestures vaguely to the north.>\n\nIf you could go take care of the situation, that would be most appreciated.", objectives = "Investigate the disturbance.", progress = "Did you remove the impediment?", completion = "That's better. Not sure how we were going to turn a profit if we had to keep replacing workers." }
WordHunterWoW_QuestEN[50813] = { title = "Cargo Reclamation", description = "", objectives = "" }
WordHunterWoW_QuestEN[50814] = { title = "A Horrible Place", description = "This town is a horrible place full of bad people. All they care about is money! No one cares about the turtles!\n\nThe turtles are out there, thirsty, drying up, and getting stepped on by monsters!\n\nYou have to save the turtles for me!", objectives = "Collect 6 Wetshell Turtles.", completion = "They're still moving! Emma's going to be so happy they are still fresh!" }
WordHunterWoW_QuestEN[50817] = { title = "A Charming Tail", description = "I think they would make great guardians, when they get older... with the proper training.\n\nHowever, it seems some of my trainees have wandered off. There are so many things nearby that could harm them!\n\nBetween the walking sandstorms and angry plants... it's been safer to hide out here and look at night.\n\nI'm so exhausted! \n\nCould you take this flute with you and play them a little tune? It will remind them to come back to me.", objectives = "Send 15 cobras to Jenoh.", completion = "Yes! Thanks, <name>! They are so much happier now!" }
WordHunterWoW_QuestEN[50818] = { title = "A Lost Flute", description = "<This little flute, while dusty, appears to be well cared for.\n\nIts owner can't be too far away.>", objectives = "Find the owner of the Desert Flute.\n\nProvided item:", completion = "My flute! I've been looking everywhere!\n\nWell, sort of..." }
WordHunterWoW_QuestEN[50823] = { title = "Ripe for the Picking", description = "The kaldorei have finally halted our progress. In a perfect world, we could have marched all the way to Auberdine and taken Teldrassil before they could even slow us down - but it matters little.\n\nMalfurion will try to hold us back until his fleet returns from Silithus. Until then, his army is too small - if only we could find a path through these damned wisps.\n\nI have an idea. Let's have a chat with Saurfang.", objectives = "Meet with Saurfang and Sylvanas in the Zoram'gar Outpost.", completion = "The kaldorei have begun to reinforce Darkshore. Our path to Teldrassil will be more difficult than we had anticipated." }
WordHunterWoW_QuestEN[50824] = { title = "Storm's End", description = "I've no doubt he can feel our presence, but so long as Lord Stormsong maintains his spell the first move is ours. \n\nWe have him surrounded, cornered like the rat he is. We must end this together.", objectives = "Confront Lord Stormsong.", completion = "Samuel was a good man, with a true heart. A fool... but our fool." }
WordHunterWoW_QuestEN[50825] = { title = "Shrine of the Storm: Whispers Below", description = "We must not let Lord Stormsong finish his work.\n\nIf he delivers the fleet to Azshara, all of Kul Tiras will be vulnerable. Countless innocents will perish -- or worse.\n\nThere is no time to wait for more of the Storm's Wake to arrive. We finish this now, for the good of all who call this valley home.\n\nWe finish this for Samuel.", objectives = "Defeat Lord Stormsong in the Shrine of the Storm.", completion = "I pray we are not too late. The fleet must return home." }
WordHunterWoW_QuestEN[50834] = { title = "Keep It Down!", description = "There is a lot of noise and light coming from those filthy mechs down by the shore. No wonder my  little hatchlings get so cranky!\n\nThey are shaking up a coast that is already unstable. You never know what one might wake up that way! \n\nLet them know they should be careful.", objectives = "Warn the goblins of danger.", completion = "Dangerous? Violence incoming? Tell us somethin' we don't know!\n\nWe ain't goin' nowhere until we get what we came for!" }
WordHunterWoW_QuestEN[50835] = { title = "The Port of Zandalar", description = "King Rastakhan has given me orders to investigate de Harbor of Zandalar. De claim Princess Talanji has levied against General Jakra'zet for failing to maintain de safety of our kingdom is a serious accusation.\n\nFor dis task, I would have you join me so dat I might have an outside perspective. When you are ready, meet me in de Grand Bazaar.", objectives = "Meet Zolani in the Grand Bazaar.", completion = "Let us get to work." }
WordHunterWoW_QuestEN[50837] = { title = "A Quick Flyover", description = "Malfurion knows that his wisp wall is a temporary measure. He is buying time for reinforcements to arrive in Teldrassil.\n\nIt is imperative that we find a way through that wall, and quickly.\n\nI want you to take our explosive reserves and apply pressure. You will not be able to bring it down, but you may be able to find us an opening. I will have a squadron ready to strike once you break ground.\n\nZarvik Blastwix should have a few bombardiers for the job.", objectives = "Use explosives to fend off the Alliance army in Darkshore.", progress = "Done?", completion = "How did it go?" }
WordHunterWoW_QuestEN[50838] = { title = "A Nose for Ptrouble", description = "Ah, so you noticed he is missing again.\n\nI would check de east this time. I heard some screeching from that direction.\n\nI am sure he will be fine- after all, what sort of trouble could he get in with you looking after him?\n\n<Wingminder Goja smiles just a touch sarcastically.>\n\nBest find out.", objectives = "Find Kua'fon in Atal'Gral and rescue him from danger.", completion = "<Kua'fon casually inspects his wings for damage. He seems very smug.>" }
WordHunterWoW_QuestEN[50839] = { title = "SKREEEEE!", description = "<Kua'fon opens his maw and issues a continuous screech.>\n\nSKREEEEEEEEE!!\n\n<You know what to do.>", objectives = "Feed Kua'fon.", progress = "<Kua'fon inspects your hands for food and shrieks demandingly at you.>\n\nSkree!", completion = "<Kua'fon gurgles in satisfaction.>" }
WordHunterWoW_QuestEN[50841] = { title = "SKREEEEE!", description = "<Kua'fon opens his maw and issues a continuous screech.>\n\nSKREEEEEEEEE!!\n\n<You know what to do.>", objectives = "Feed Kua'fon.", completion = "<Kua'fon licks his chops. His head bobs in satisfaction.>\n\nSkree." }
WordHunterWoW_QuestEN[50842] = { title = "Mast Effect", description = "Kua'fon was peering over de edge and managed to fall off de cliff again.\n\nNormally he gets back up here on his own, but it be taking too long this time.\n\nBest go down to de beach and find him. He is probably stuck up one of de ship masts out there.\n\nIf he will not come down, you can try bribing him with more fish.", objectives = "Find Kua'fon in Talanji's Rebuke and bribe him down with fish.", completion = "<Kua'fon picks at his teeth with a wing-claw, carefully avoiding eye contact with you.>" }
WordHunterWoW_QuestEN[50845] = { title = "Kul'krazahn", description = "", objectives = "" }
WordHunterWoW_QuestEN[50846] = { title = "Headhunter Lee'za", description = "", objectives = "" }
WordHunterWoW_QuestEN[50847] = { title = "Twisted Child of Rezan", description = "", objectives = "" }
WordHunterWoW_QuestEN[50848] = { title = "Brgl-Lrgl the Basher", description = "", objectives = "" }
WordHunterWoW_QuestEN[50849] = { title = "Witch Doctor Habra'du", description = "", objectives = "" }
WordHunterWoW_QuestEN[50850] = { title = "Tia'Kawan", description = "", objectives = "" }
WordHunterWoW_QuestEN[50851] = { title = "Mor'fani the Exile", description = "", objectives = "" }
WordHunterWoW_QuestEN[50852] = { title = "Lady Seirine", description = "", objectives = "" }
WordHunterWoW_QuestEN[50853] = { title = "Umbra'rix", description = "", objectives = "" }
