WordHunterWoW_QuestEN[50860] = { title = "A Nose for Ptrouble", description = "Kua'fon is getting very large. Perhaps he thinks himself equal to de beasts of this jungle.\n\nHe may well learn that he is not. You should find him before that lesson costs him his life.\n\nI heard a commotion to de north. Start there.", objectives = "Find Kua'fon in the Savagelands and rescue him.", completion = "<Kua'fon spreads his wings and utters a piercing shriek. He had it the whole time.>\n\nSkree!" }
