WordHunterWoW_QuestEN[50876] = { title = "Murderbeak", description = "", objectives = "" }
WordHunterWoW_QuestEN[50877] = { title = "Gahz'ralka", description = "", objectives = "" }
WordHunterWoW_QuestEN[50878] = { title = "Blurred Vision", description = "Look up.\n\nSee them, scattered among the trees? Those brightly glowing owls are not living, breathing denizens of the forest... they are Kaldorei magic. Sentries. A ruse -- reporting everything they see back to Malfurion.\n\nWe can't have that, now can we?\n\nDeal with them, {name}. But take care -- they aren't the only enemies in the forest.\n\nWe cannot allow anything or anyone to stand in our way.", objectives = "Eliminate the Sentry Owls in the trees and slay the frenzied furbolg of Darkshore.", completion = "Nicely done." }
WordHunterWoW_QuestEN[50879] = { title = "The Trees Have Ears", description = "With the eyes of the forest shut, one thing remains: the ears. Ancients. \n\nThey feel the vibrations of our footsteps and report our every move to Malfurion.\n\nGot that torch handy?", objectives = "Defeat the Burning Ancient.", progress = "These Ancients must be taken care of.", completion = "Come, Champion. Let us take this ancient grove." }
WordHunterWoW_QuestEN[50880] = { title = "An Unstoppable Force", description = "Now is the time to strike, {name}. \n\nPassing through the wall will not be easy, but I think it's something you can handle. Do what you must to prevail, and meet me on the other side. I will lead a squad of sturdy soldiers and as many demolishers as can survive the passing.\n\nWe may not make it to Darnassus today, but the outcome of this war does not rest on one victory alone -- it will come as the result of a thousand small victories.\n\nSo let's get started, shall we?", objectives = "Disrupt the Alliance forces in Darkshore.", completion = "Malfurion will return with his forces, but until then let's press on." }
WordHunterWoW_QuestEN[50881] = { title = "Royal Report", description = "Blood magics practiced in de city, guards missing, and our chief spy, Yazma, is acting suspicious. We must present dis to Rastakhan, but without Yazma interfering.\n\nLuckily, Rastakhan is a clever king, which is something his opponents often forget.\n\nI have prepared a report in a code made by King Rastakhan and known only to myself and my brother, Habutu. Bring it to Habutu and he will see dat it gets to de king's ear.", objectives = "Deliver Zolani's report to Habutu at the Golden Throne.", completion = "Hmm. Zolani speaks highly of your deeds. Perhaps we may not need to kill you yet." }
WordHunterWoW_QuestEN[50882] = { title = "All to Ash", description = "All throughout our campaign here, I understood the warchief's objective. I saw her strategy... believed in its necessity.\n\nWith Darnassus in Horde hands, the Alliance would be paralyzed. Anger and fear would fester in their hearts until they cracked and splintered like deadwood.\n\nBut this... this will unite them. They will come for us. All of them.\n\nReturn to the Undercity, {name}. Speak to the warchief. We must make ready for what is to come.", objectives = "Speak to Warchief Sylvanas Windrunner in Undercity.All throughout our campaign here, I understood the warchief's objective. I saw her strategy... believed in its necessity.\n\nWith Darnassus in Horde hands, the Alliance would be paralyzed. Anger and fear would fester in their hearts until they cracked and splintered like deadwood.\n\nBut this... this will unite them. They will come for us. All of them.\n\nReturn to the Undercity, <name>. Speak to the warchief. We must make ready for what is to come.You will receive:" }
WordHunterWoW_QuestEN[50885] = { title = "Lei-zhi", description = "", objectives = "" }
WordHunterWoW_QuestEN[50886] = { title = "Surrogate Wings", description = "It is not my way to coddle the young of my brood. But I think I will make an exception for your little one.\n\nAfter all, I have seen you tend to him. It would be cruel to let your... efforts... go to waste.\n\nVenture into Zuldazar city proper and find something that can act as a surrogate wing for your young one.\n\nWingminder Goja will know what to do next. Speak to him once you have it.", objectives = "Acquire a Huge Dragon Kite.", progress = "Did Pa'ku offer any useful advice?", completion = "What is this?\n\n<Wingminder Goja looks between you and the pterrordax and grins.>\n\nOh, I get it!" }
WordHunterWoW_QuestEN[50887] = { title = "Ptrust Fall", description = "I just want you to know how unusual this is for Pa'ku. She prefers to teach on the fly.\n\nWhat? It's true.\n\nThis method might work. Sometimes when young pterrordax are not eager to fly, their mother will drag them from the nest and hold them in her claws until they are comfortable enough to spread their wings.\n\nSeeing as this little one has no mother, you will use the kite to act as one.\n\nPa'ku has placed a trail for you to follow.\n\nGo and glide carefully- you may frighten your pterrordax more!", objectives = "Board the Huge Dragon Kite and take your pterrordax on a flight to build his confidence.", completion = "<Pa'ku eyes your hatchling sourly.>\n\nAre you sure we can't just throw him next time?" }
WordHunterWoW_QuestEN[50897] = { title = "Turn the Heat Around", description = "<In standard goblin fashion, the Horde forces seem to be using flamethrowers to clear out the snow.>\n\n<This one is still usable despite being beaten on, you could use it to destroy some of the goblin mining machinery.>", objectives = "Destroy 6 pieces of goblin machinery.", completion = "<Oh, the sweet sound of goblin-made explosions.>" }
WordHunterWoW_QuestEN[50899] = { title = "Don't Stalk Me, Troll", description = "", objectives = "" }
WordHunterWoW_QuestEN[50900] = { title = "Maybe When You're Older", description = "<Pa'ku squints down at the young pterrordax.>\n\nWell, I am out of ideas. My son will take you back to the nest. Do not worry, this one can fly.\n\nYOUR little one will need to get back on his own. It builds character.\n\nMaybe he will grow out of this absurd deficiency in time.", objectives = "Return to the nest at Pterror Rise.", progress = "How did it go?", completion = "Pa'ku is Lord of Wind. Naturally she expects young of her brood to take the same joy in flight.\n\nYour little one will come around. Some just take longer than others." }
WordHunterWoW_QuestEN[50901] = { title = "Saurid Surprise", description = "Da sands of Vol'dun be full of harsh creatures, but none so harsh as dey dat da Zandalari send.\n\nOne of dese criminals be right here in da Scorched Sands. His name be Sezahjin, and he be da former chef ta da king. Did he tell ya dat he be famous for a dish called \"Saurid Surprise?\" Guess what da main ingredient be.\n\nHe be fallin' far, but not far enough for Jani. It be time ta take his pride.\n\nJust be makin' sure dat da creatures of da sand not be seein' ya.", objectives = "Survive Jani's prank on Sezahjin.\n\nIf you lose your saurid disguise, return to Jani for another.", progress = "Ya taken dat accursed chef's hat yet, richmon?", completion = "Haha! Well done, richmon. No doubt he gonna find another hat eventually, but you took da one he be wearin' when he cook up his Saurid Surprise. Ya have earned me favor." }
WordHunterWoW_QuestEN[50903] = { title = "A Missing Master", description = "Master Ashton had me grab some healing supplies and run to Mayor Royston when those things attacked town. He didn't make it behind the barricade.\n\nBut if he's alive--and he's just crazy enough he might be--he's probably holed up in his cottage. With caustic compounds. And explosives.\n\nLook, why don't you go check out his basement and I'll stay out of the blast radi- I mean I'll go see if the garden can be salvaged.\n\nTry not to look flammable.", objectives = "Find Master Ashton.", progress = "Oh! You're not one of those monsters at all. Did you trounce those brutes?", completion = "I appreciate your help in liberating the town! I was becoming quite concerned by these strange monsters." }
WordHunterWoW_QuestEN[50904] = { title = "The Abandoned Passage", description = "My people have known about this ancient passageway for generations, but none have dared enter before now.\n\nThe tunnel leads to the tomb of Mythrax the Unraveler and it is said that his power still radiates within the cavern. Who knows what horrors await us inside...\n\nIt appears that your friends have already gone inside to face Jakra'zet and stop him from raising Mythrax from the dead.\n\nWe don't have time to waste. We must find Kaja and Rakera before they confront Jakra'zet on their own!", objectives = "Find Bladeguard Kaja and Warguard Rakera in Atul'Aman.", completion = "Jakra'zet has already begun the ritual. We must stop him before it's too late!" }
WordHunterWoW_QuestEN[50908] = { title = "Smells Like Trouble", description = "The Horde spilled a lot of blood in Brennadam. Now it's time to spill some more.\n\nThe scent of blood makes predators in these hills go crazy. We use it to lure animals when hunting.  \n\nThe Horde forces are occupying caves up in the hills. Toss these scent vials into the caves where the Force Commanders organize the attack. The smell should bring all the hills down upon them!", objectives = "Slay Force Commanders Ogarth and Durmok.", progress = "Those scent vials should help you eliminate both Force Commanders.", completion = "With you around, they won't try this again." }
WordHunterWoW_QuestEN[50909] = { title = "Never Outgunned", description = "This is our new home now, and we will fight to keep it!\n\nWe may be outnumbered here, but we aren't going to be outgunned.\n\nFind us every axe, sword, spear, crossbow, and gun for our rebellion!", objectives = "Find us 15 Rebel Weapons.", progress = "We'll need more than that. Find us some weapons!", completion = "This is a good start." }
WordHunterWoW_QuestEN[50910] = { title = "Dangerous Game", description = "Most of these Horde don't scare us, but we lost two people today to a group of forsaken keenblades. We've had trouble tracking them down, we could really use your help.\n\nThey're stealthy and dangerous fighters, so show no mercy.", objectives = "Rid the hills of these Forsaken Keenblades.", completion = "Your skills are impressive.  I don't think any of us could have taken out those keenblades so easily." }
WordHunterWoW_QuestEN[50911] = { title = "One Man Against the Horde", description = "Me an' a few friends were trying to help some of the folks from Corlain flee safely to Arom's Stand after things started gettin' weird. I noticed some movement up the hill so I decided to come back and check it out. If the town goin' mad wasn't bad enough, now we have another problem to deal with.\n\nThe Horde.\n\n<McKellis spits.>\n\nThose fools have no place on our lands. Wash the snow with their blood.", objectives = "Kill 10 Horde forces.", completion = "The only good orc is a dead orc." }
WordHunterWoW_QuestEN[50912] = { title = "Remix to Ignition", description = "<A goblin mining machine is halfway sticking out of the snow.\n\nDespite being buried, it seems to be in working condition. If only you had a key.>", objectives = "Find the ignition key.", progress = "<The machine lays lifeless on the snow.>", completion = "<With a bit of effort, you free the machine from the snow. It whirs to life upon using the key.>" }
WordHunterWoW_QuestEN[50913] = { title = "Akunda's Blessing", description = "You have proven worthy of my blessing, {name}.\n\nThis means should you choose me as your loa, you can call upon my power when needed.\n\nCommune at my shrine to receive my gift.\n\nKnow that whatever you choose, you will always be welcome within these walls.", objectives = "Commune at Akunda's Shrine.", progress = "I bestow my blessing upon my followers.", completion = "If at any time you require my gift, commune at a shrine built in my honor to receive my boon." }
WordHunterWoW_QuestEN[50929] = { title = "Powder to the People", description = "The Horde filth up on that hill seem to be mining some kind of ore I've not seen before.\n\nIf they've come all the way out here to find it, it must be valuable. Take what you can find!", objectives = "Gather Azerite from 6 crates.", progress = "Did you figure out what they were doing up there?", completion = "This just looks like a pile of junk!" }
WordHunterWoW_QuestEN[50930] = { title = "Falling With Style", description = "<Kua'fon looks to the kite, then back at you. He looks to the kite again, poking his head forward deliberately. He slowly pans his gaze back to you.>\n\nSkree.\n\n<Time for another flight!>", objectives = "Take Kua'fon on another flight on the Huge Dragon Kite.", progress = "There is a method to Pa'ku's madness.", completion = "Another successful flight! I only hope it helps Kua'fon learn that de sky is his home, in time.\n\nDo not worry, he will get back up to de nest on his own." }
WordHunterWoW_QuestEN[50933] = { title = "An Unfortunate Event", description = "<You have no means of identifying the corpse, but the clothing appears to be that of an imperial guard from Zuldazar.\n\nA quick search of the area reveals a trail of blood that heads off to the west. Perhaps if you follow it you can discover the cause of death.>", objectives = "Discover what happened to the Imperial Guard.", completion = "You do not look like one of de prisoners. I... I could use your help." }
WordHunterWoW_QuestEN[50934] = { title = "A Chance Sighting", description = "One of the lookouts said he saw a bunch of blood trolls chasing after a Zandalari on the other side of the river.\n\nHe seemed to be dressed like your group. Why do you people keep running into trouble in this place?\n\nI'll mark on your map where he was last seen. Just don't bring a horde of blood trolls over here, alright?", objectives = "Investigate the missing Zandalari.", completion = "<The Zandalari next to this antidote is barely alive.>" }
WordHunterWoW_QuestEN[50936] = { title = "Survival Strategy", description = "", objectives = "" }
WordHunterWoW_QuestEN[50940] = { title = "Wisdom of the Wingless", description = "<Kua'fon wheezes and quivers, exhausted.>\n\nIt's not going anywhere. Maybe it's time to seek someone without wings for advice.", objectives = "Seek out Hexlord Raal.", completion = "I heard de screeching. Glad to see you still be in one piece." }
WordHunterWoW_QuestEN[50942] = { title = "Dress for the Slide, Not the Ride", description = "If Kua'fon is serious about flying, we're going to need to protect him.\n\nGo get a berserker skull and some armor for it. Meet me down in Talanji's Rebuke and we'll get him dressed for success.", objectives = "Collect a Berserker Skull and Lightweight Skyterror Barding.", progress = "You got the things I asked for?", completion = "Now, perhaps, your companion will not be afraid of his next fall. Haha!" }
WordHunterWoW_QuestEN[50943] = { title = "The Joy of Flight", description = "You be ready, {name}?\n\nKua'fon is ready to fly. Whether or not he can is another question, but all the same I will see you two back to the roost.\n\nClimb aboard and guide him. I can't imagine he can see very well through that skull.\n\nAta and I will lead the way.", objectives = "Follow Hexlord Raal and fly Kua'fon back to the roost", completion = "<Kua'fon pants from exertion, but he seems content with his efforts.>\n\nSkree." }
WordHunterWoW_QuestEN[50944] = { title = "Down, But Not Out", description = "<Kua'fon wiggles happily in his new armor. He starts to pace restlessly back and forth. A taste for adventure has surely awakened in this flightless creature.>\n\nSkree! Skree!!", objectives = "Accept Kua'fon as your new traveling companion.", completion = "<Kua'fon lowers its head and gently nuzzles you. He is ready to follow you wherever you may go.>" }
WordHunterWoW_QuestEN[50953] = { title = "Greenstalker", description = "The mighty wolf Greenstalker was once a protector of these forests. He has fallen under the sway of dark forces. My brother and I attempted to calm his spirit, but he is too far gone.\n\nUse the charm I have constructed to weaken him. I ask you {class}, please, end his suffering.\n\nMy brother is still weak and I must stay to protect him. Go now before the wolf consumes us all!", objectives = "Slay Greenstalker.", progress = "Did you free Greenstalker's spirit?", completion = "A grim but necessary task. I hope Greenstalker's spirit will find peace now.\n\nBe careful, <name>. These woods are being twisted by ancient power." }
WordHunterWoW_QuestEN[50954] = { title = "Zandalar Forever!", description = "Bwonsamdi has whispered a warning to me: the enemy is on the move.\n\nI have gathered what defenses I could in the time allowed but we are dangerously under powered. \n\nI can only hope that, thanks to your efforts, the loa will be with us this day.\n\nAre you ready to defend Zandalar?", objectives = "Complete the Zandalar Forever scenario.", completion = "We have won the battle, not the war." }
WordHunterWoW_QuestEN[50955] = { title = "We're Not Friends", description = "I did some time in Tol Dagor with the captain of this crew, Calico McGee. He likes to hang back and direct his men from afar.\n\nI just happened to have spotted him across the flats. You and I should go pay him a visit!", objectives = "Eliminate Calico McGee.", completion = "I never liked his cat." }
WordHunterWoW_QuestEN[50956] = { title = "Walking-Around Money", description = "This is a lot of gold! It's gonna take me a while to split this up. I can give you some walking-around money to hold you over until I am done.\n\nCome back tomorrow, maybe I will have it figured out.", objectives = "Accept the money.", completion = "<A small advance from Leo, against my share of the loot.>" }
WordHunterWoW_QuestEN[50957] = { title = "Wrath of Rezan", description = "", objectives = "" }
WordHunterWoW_QuestEN[50958] = { title = "Watch Your Wallets", description = "", objectives = "" }
WordHunterWoW_QuestEN[50959] = { title = "Plundering Pirates", description = "", objectives = "" }
WordHunterWoW_QuestEN[50960] = { title = "Sweete's Orders", description = "<Tucked into the pages of the captain's logbook is a letter bearing the seal of Harlon Sweete.\n\nIt looks like these pirates have been ordered by Sweete to cause further disruption to House Waycrest. \n\nLucille should be notified of this immediately!>", objectives = "Bring Sweete's Orders to Lucille Waycrest in Drustvar.", progress = "What have you brought, mainlander?", completion = "<Lucille reads the orders.>\n\nSo This pirate seeks to destabilize House Waycrest? As if we don't have enough problems already!\n\nThank you for bringing this to my attention, <class>. It seems that the coven might just be the beginning of Kul Tiras' troubles..." }
WordHunterWoW_QuestEN[50961] = { title = "Save Our Scrolls!", description = "", objectives = "" }
WordHunterWoW_QuestEN[50962] = { title = "Cargo Reclamation", description = "", objectives = "" }
WordHunterWoW_QuestEN[50963] = { title = "Of Dark Deeds and Dark Days", description = "I should have known better, and now Rezan is dead, and my own power is barely holding on. Soon Bwonsamdi himself will be coming to collect me.\n\nTalanji... she must know what has happened here. Go to her, tell her. Aid her where you can.\n\nI followed a god of strength and yet I have not de strength to face her with dis shame.\n\nFor now, I must gather our forces and pursue Zul.", objectives = "Speak with Princess Talanji in the Royal Chambers of Dazar'alor.", completion = "Rezan is... dead?" }
WordHunterWoW_QuestEN[50964] = { title = "Ritual Combat", description = "", objectives = "" }
WordHunterWoW_QuestEN[50965] = { title = "Those Who Remain", description = "<The runes on the wooden plaque glow faintly with an ancient magic. It looks like it is a small piece of a larger record.>\n\n<One of the Thornspeakers at the Teller Farm would probably recognize what this is.>", objectives = "Collect 8 Ashenwood Relics.", progress = "Is there something more you need?", completion = "These are a few of the remaining relics of my kin. I thought them lost. You have my utmost gratitude." }
WordHunterWoW_QuestEN[50966] = { title = "Cleanup Crew", description = "", objectives = "" }
WordHunterWoW_QuestEN[50967] = { title = "Lost in the Woods", description = "My student, Amalie, and I have taken it upon ourselves to act as the keepers of these woods. We were away from Drustvar briefly, and upon our return, found the grove infested and the surrounding land corrupted.\n\nAmalie decided that she could deal with the grove infestation alone.\n\nIt's been some time since she ran off, could you look for her while you're in the Ashenwood?", objectives = "Find Amalie Oakseeker.", completion = "She said she would head back on her own? At least she is safe." }
WordHunterWoW_QuestEN[50969] = { title = "Emergency Management", description = "", objectives = "" }
WordHunterWoW_QuestEN[50970] = { title = "A Farmer's Fate", description = "Old Jakob here was one of the few folks who were never wary of us. I have, on occasion, even helped him around his farm in return for supplies. It is an injustice just to ignore his plight even amidst our own problems.\n\nThe corruption which holds him seems to be early in form. I believe I can cleanse it.\n\nTake this branch, and bring it to the three shrines around the Ashenwood. That should allow it to gather enough energy for the ritual.", objectives = "Empower the Everliving Branch.", completion = "The wood remembers, and guides us. This should be enough power to help this farmer." }
WordHunterWoW_QuestEN[50972] = { title = "Proudmoore's Parley", description = "So, we meet again.\n\nI... apologize for how you were treated last time. I trusted Priscilla like a sister and-- \n\n<Katherine chokes up for a moment before regaining her composure.>\n\nLet us keep this brief, for I will make no promises nor any formal accords in this state.\n\nReturn to your leaders. Tell them I wish to parley.\n\nThat is all for now. My people have suffered a great deal today and I have much to reflect upon.", objectives = "Report to Genn Greymane in Boralus Harbor.", completion = "So, Katherine is willing to speak with us at last?\n\nWell done." }
WordHunterWoW_QuestEN[50973] = { title = "The Heart's Power", description = "The world's soul grows stronger, <name>, but there's still trouble out there. Azerite surges from her wounds, and all sides fight tae claim its might.\n\nYe have proven yerself tae be Azeroth's champion. And thanks tae all ye have done, I sense a great power stirrin' in that amulet ye wear.\n\nAzeroth calls tae us. She wants me tae help ye unlock even greater strength in her Heart. Are ye ready?", objectives = "Ask Magni Bronzebeard to empower the Heart of Azeroth.", progress = "Hold still, champion, while I empower the Heart of Azeroth.", completion = "Can ye feel it, <name>? The Heart of Azeroth grows stronger!\n\nI believe we can unlock even more o' that amulet's potential.\n\nYou keep on absorbin' all the Azerite ye find, and I'll search for some way tae bring this madness tae an end." }
WordHunterWoW_QuestEN[50975] = { title = "Azerite Mining", description = "", objectives = "" }
WordHunterWoW_QuestEN[50976] = { title = "An Ancient Curse", description = "<The harsh conditions of Nazmir have not been kind to the stone tablet.\n\nMost of the inscriptions have been worn away but you are able to make out a picture that shows a chest surrounded by glyphs. Above the chest you noticed what appears to be a large floating skull.\n\nBelow the images you find a single word \"Aiji\".\n\nThe ruins ahead seem foreboding, and you may want to bring some friends to help you.\nWith their help, perhaps you can find the secret of this \"Aiji\" and its treasure within.>", objectives = "Activate the braziers of Xal'vor and defeat Aiji the Accursed." }
WordHunterWoW_QuestEN[50977] = { title = "Smuggler Shakedown", description = "", objectives = "" }
WordHunterWoW_QuestEN[50978] = { title = "Out With the Old Boss", description = "Right so I talked to some people. You talked to some people. No one likes the Irontide. They're cutting in to profits and scaring off good, honest scoundrel- er customers! \n\nWe take out the guy in charge and we'll be able to run the rest outta town! So a little change of management is in order.\n\nI'm not usually one for stabbin' people, I'm a lover not a fighter, but I can pay. You do this for me and I'll make sure you're welcome here whenever ya want? Sound good?", objectives = "Slay Richard Tornsail.", completion = "Great! I'm the Boss of the Cove now and what I say goes.\n\nSince you've been a pal, I'll let you stop in whenever you like. Remember to bring gold." }
WordHunterWoW_QuestEN[50979] = { title = "Just a Nip", description = "My tough-guys-in-training are quick learners! \n\nThey do seem to get a bit... bitey... when they're grouchy, though. Too many, and I start to get a little light-headed.\n\nThe nearby atrivax plants have a medicinal gel. It is great to treat fresh wounds and nullify venom.\n\nThey don't like sharing it. Could you harvest a bit for me?", objectives = "Get 10 samples of Atrivax Gel.", progress = "How goes the juicing?", completion = "Thanks, <name>! That should do the trick!\n\nAt least it will tide me over until they realize we're on the same side." }
WordHunterWoW_QuestEN[50980] = { title = "My Hungry Neighbor", description = "There is an angry hydra that has decided to make a nearby ridge his home.\n\nHe keeps getting bigger, and meaner, and hungrier!\n\nMy cobras are terrified. \n\nPlease, {name}, take care of him before he comes after us!", objectives = "Kill the Territorial Hydra.", completion = "It seems he found you indigestible. Excellent work!\n\nWe all thank you!" }
