WordHunterWoW_QuestEN[50988] = { title = "An Economic Opportunity", description = "You look savvy enough to jump on an opportunity when one comes by and, pal, do I have one for you.\n\nSee that cove down there? It's run by entrepreneurs with an eye towards meeting the logistical shortfalls that might come up in your typical city or town situation. Well, it's normally run by them.\n\nWe have a bit of an infestation by folks who are more mercenary minded if you catch my meaning.\n\nYou help me win back control of the cove and I'll see you're treated well. Sound good?", objectives = "Meet Cesi Loosecannon inside Anyport.", completion = "Right! So. Cards on the table. We're smugglers. We're not pirates. Everyone wants those red-coated jerks gone.\n\nYou help me become boss of Anyport and I'll help you.\n\nTalk to some of the key folks around here. Do some favors for 'em then come back to me, got it?" }
WordHunterWoW_QuestEN[50989] = { title = "Work Order: Storm Silver Ore", description = "", objectives = "Are you here to deliver supplies?", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, miner. We needed this storm silver ore badly." }
WordHunterWoW_QuestEN[50990] = { title = "Cutting Edge Poultry Science", description = "<Before you is a delicious chicken... And yet, despite everything, there is something a little bit... lively about this creature.\n\nWith a judicious application of science, there might be something that can still be done for this poor bird.\n\nYou resolve to bring the chicken to Dr. Oglethorpe in Booty Bay with all haste.>", objectives = "Take the Delicious Chicken to Dr. Oglethorpe in Booty Bay.", completion = "Hmm, a difficult case but I believe I can help!\n\nThese days so many people concerned if science should do something rather than if science can do it! Now let's see... Some wire, a few gears, a bit of feath-growth potion and some good old rocket fuel for some kick... And presto! One robotic chicken back from the brink!\n\nEr, if it goes insane and tries to kill everyone, you were never here and we never had this conversation." }
