WordHunterWoW_QuestEN[51001] = { title = "Every Day I'm Smugglin'", description = "Hey! Wanna make some quick gold?\n\nSee, I had a mishap a few weeks ago with a shipment. Too much grog, dark seas, sudden rocks. You know, that old story.\n\nAnyway, my cargo's been floating out there and no one will get it back for me. Can you believe it? You bring my cargo back and I'll pay you a generous recovery fee.\n\nWe got a deal? Great!\n\nOh, uh, watch out for the sharks. Did I forget to mention the sharks?", objectives = "Collect 5 Smuggled Goods from the sea near the shipwreck close to Anyport.", progress = "You get the goods?", completion = "Hey thanks! Bit damp but still good." }
WordHunterWoW_QuestEN[51002] = { title = "Work Order: Akunda's Bite", description = "", objectives = "Are you here to deliver supplies?", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, herbalist. We needed this akunda's bite badly." }
