WordHunterWoW_QuestEN[51052] = { title = "Azerite for the Alliance!", description = "", objectives = "" }
WordHunterWoW_QuestEN[51053] = { title = "The Day the Port Fell", description = "Dis be a cursed land, {race}. Feel it in your bones: de cold chill of death... and undeath.\n\nDe Pirate-King Zem'lan rules dis port, with his crew of de eternal damned.\n\nIf you be lookin' for honor or noble adventure, you won't find it here. But if you can settle for vengeance and treasure, I got an offer for you.\n\nBut you should know who you be allying with. My hands are not clean in dis.\n\nTake de medallion from my cloak and use it to reveal a vision of my past at de end of de dock.", objectives = "Use First Mate Jamboya's Medallion to view a vision of his past.", progress = "I've witnessed countless horrors through countless generations.", completion = "Dat was where it all began. I could've stopped Zem'lan right dere... I could've prevented dis fate for de crew.\n\nInstead, I led dem straight into it." }
WordHunterWoW_QuestEN[51054] = { title = "Overdue Mutiny", description = "I used to be a Zandalari, {name}.\n\nLong ago, before dis curse. We were all Zandalari pirates, proudly sailing under de black flag of our captain, Zem'lan.\n\nNow look at us... undead monsters, forced to serve our eternal captain like slaves.\n\nWell, I be done with dis. De curse can't be broken, but we can still mutiny!\n\nWhat say you? It gonna be tough, but I promise treasure and a chance to kill de notorious Pirate-King Zem'lan who murdered your vulpera friend.\n\nHelp me down, and we be gettin' started.", objectives = "Free First Mate Jamboya.", completion = "Dis won't be easy, <name>. But it be worth it." }
WordHunterWoW_QuestEN[51055] = { title = "The Yard Arm of the Law", description = "I'm not de only pirate Zem'lan has had strung up around de port. Hangin' on de yard arm is his favorite form of punishment for de crew.\n\nWe can't feel pain and don't stay dead, so his options are limited.\n\nLook for more crewmates hangin' around town. Tell dem to meet me here after you free dem.\n\nAfter weeks of hanging helplessly while being mocked and abused by de rest of de crew, I bet dey be willin' to discuss mutiny.", objectives = "Free Quartermaster Tulmac, Gunner Bosanya, and Jukanga the Snitch.", completion = "It looks like we all be of one accord. It be mutiny!" }
WordHunterWoW_QuestEN[51056] = { title = "My Last Day Alive", description = "De curse came one fateful day, in ages past, when de sethrak attacked. Dere was no end to dem.\n\nIn our desperation, I helped Pirate-King Zem'lan do de unthinkable.\n\nWe became monsters. Even worse, we became eternal slaves to Zem'lan.\n\nDe curse weighs heavy on me, but my guilt is heavier. I led me crew into dis.\n\nBefore we confront de Pirate-King himself, you need to understand what we be up against.\n\nYou need to see what happened de day dat de Port of Zem'lan fell.", objectives = "Use First Mate Jamboya's Medallion to witness visions of his past.", completion = "Now you know how desperate we were on dat day, <name>.\n\nI don't be making excuses, but you should understand why we did what we did." }
WordHunterWoW_QuestEN[51057] = { title = "Maroon 'em with Fire", description = "We gonna have to sail out to de Golden Isle to face Pirate-King Zem'lan.\n\nLet's make sure de rest of de crew can't follow us once we go. Burn their boats in de harbor.", objectives = "Use the Undying Torch to burn 8 Pillaging Canoes.", progress = "Don't burn my boat, <name>. We be needin' dat one.", completion = "Good. We be ready to sail." }
WordHunterWoW_QuestEN[51059] = { title = "The Golden Isle", description = "Pirate-King Zem'lan don't stay in de port with de rest of us. Too good to crack a jug with his crew no more.\n\nWe gotta sail out to de Golden Isle to find him. That be de forbidden island where Zem'lan hoards all of de treasure we've pillaged and plundered, so only he can enjoy dem.\n\nHop in my boat and we'll row out dere together.", objectives = "Ride in Jamboya's boat out to the Golden Isle.", completion = "Here we are. De Golden Isle. It's beautiful, ain't it?\n\nA pirate's paradise." }
WordHunterWoW_QuestEN[51060] = { title = "Our Share of the Plunder", description = "Dis treasure belongs to de crew! We've fought every battle for Zem'lan, but he hoards all de booty for himself.\n\nAnd if ya try to take some for yourself, he turns ya into one of his goldslaves. Those be de mindless drones ya see tendin' to de treasure out here.\n\nWe ain't leavin' here empty-handed after de mutiny. Collect all de treasure ya can!\n\nBeware de cursed bits. It don't hurt us, but I'm guessin' it'll hurt you.", objectives = "Collect 12 Cursed Treasures of Zem'lan.", progress = "More treasure!", completion = "I suppose dis little amount of gold won't be cursin' ya for too long. I'll carry de rest." }
WordHunterWoW_QuestEN[51061] = { title = "The First Time I Died", description = "Dis be it. Where Zem'lan cursed us all.\n\nIt began with me death. De first of countless deaths I've had since. Each of dem spent fighting and dying for Pirate-King Zem'lan and his selfish treasure hoard.\n\nI don't know if de idols he used to curse us can even be destroyed, but we gotta try. Let's take dem to de altar where de ritual occurred and try to smash one.", objectives = "Place the idols on the altar and try to destroy them.", completion = "I guess de idols can't be destroyed... even by a mortal. Curses be fickle things.\n\nI was de first Zem'lan cursed, and I did nothin' to stop him from cursin' de rest of de crew.\n\nI regret it every day...\n\nBut enough livin' in de past. It's time to be free." }
WordHunterWoW_QuestEN[51062] = { title = "Escaping Zem'lan", description = "Pirate-King Zem'lan was right about one thing: he won't stay dead for long.\n\nWe gotta take our treasure and get out of here while we got de chance.\n\nWe can take de boat, but we'll need a place to hide out for awhile. Are your vulpera friends open to housin' a few stowaways?\n\n<First Mate Jamboya motions to the piles of treasure in his boat.>\n\nClearly, we can pay dem for their trouble.", objectives = "Ride Jamboya's boat to the shore and lead the pirates to Camp Lastwind.", completion = "What have you gotten us into, <name>? We asked you to find our friend, not bring monsters into our camp." }
WordHunterWoW_QuestEN[51064] = { title = "Azerite Wounds", description = "", objectives = "" }
WordHunterWoW_QuestEN[51068] = { title = "Raiding Their Stores", description = "We're low on food supplies.\n\nHit up Newstead and bring us whatever you can find.", objectives = "Obtain a Roast Boar, a Colossal Cheese Wheel, a Basket of Eggs, and a Keg of Applebrew." }
WordHunterWoW_QuestEN[51069] = { title = "WANTED: Darkspeaker Jo'la", description = "Wanted for atrocious crimes against the Zandalari: Darkspeaker Jo'la\n\n Defeat this powerful adherent of Zul, and a great reward shall be yours.", objectives = "Slay Darkspeaker Jo'la", completion = "Dat troll was nothing but bad news for everyone. You have done well." }
WordHunterWoW_QuestEN[51070] = { title = "Raiding the Boulderfist", description = "The Boulderfist have recently raided Drywhisker Mine, and are sitting on a large amount of iron ore.\n\nWe want it back.", objectives = "Obtain 200 pieces of Unprocessed Iron Ore.", progress = "We can't let the Alliance take Arathi. We'll use whatever iron we can get.", completion = "This will do. Throm-ka, <name>." }
WordHunterWoW_QuestEN[51071] = { title = "WANTED: Sabertusk Empress", description = "To any and all brave enough to seek the challenge: \n\nFind and defeat a ferocious Sabertusk Empress, the strongest and most vicious of all sabertusks in Zuldazar. \n\nThey can be found up and down the road from the Village in the Vines. \n\nA reward for any that succeed!", objectives = "Slay a Sabertusk Empress", progress = "The wanted poster stands with tasks etched on it.", completion = "Thank you, champion. Dat is one less threat to de area." }
WordHunterWoW_QuestEN[51072] = { title = "WANTED: Prime Thumpknuckle", description = "To any and all brave enough to seek the challenge: \n\nFind and defeat a Prime Thumpknuckle, the largest and most dangerous of all the wild gorillas.\n\nThey can be found up and down the road from the Village in the Vines. \n\nA reward for any that succeed!", objectives = "Slay a Prime Thumpknuckle", completion = "You faced down those Thumpknuckles? Dat is worth a lot to us. Thank you." }
WordHunterWoW_QuestEN[51078] = { title = "Azerite Madness", description = "There be a group of earth elementals nearby that be goin' crazy due te havin' Azerite infused onto 'em.\n\nWe cannot allow this Azerite to spread to any more elementals. We need te put 'em down.\n\nGo and fight these Azerite infused elementals nearby. When they be down, use yer amulet to absorb their lingerin' Azerite.\n\nIt be a shame te do this, but we're fightin' these things in order te save the planet.You will learn:", objectives = "Absorb Azerite from defeated Azerite Infused Elementals." }
WordHunterWoW_QuestEN[51081] = { title = "Syrawon the Dominus", description = "", objectives = "" }
WordHunterWoW_QuestEN[51082] = { title = "Iron Stores", description = "While the mine is under Horde banners our peons ensure the iron supply never runs dry.\n\nThis key provides access to the chest. Make sure it still works.", objectives = "Use the Heavy Iron Key to access the Iron Stores.", progress = "Chest giving you trouble?", completion = "Heh, glad to see it still works." }
WordHunterWoW_QuestEN[51084] = { title = "Dark Chronicler", description = "", objectives = "" }
WordHunterWoW_QuestEN[51085] = { title = "WANTED: Dark Chronicler", description = "Champion wanted for an expedition into the depths of Xibala. \n\nStrange noises and wails come from the bones at night and our workers are terrified. \n\nSeek out the source of the strange noises and destroy it, and a reward will be yours.", objectives = "Slay Dark Chronicler", completion = "The ruins will now be silent at night." }
WordHunterWoW_QuestEN[51086] = { title = "Break's Over", description = "It's come to my attention a few of our peons have been caught sleeping instead of hauling iron from the mine. We can't let our supplies get low.\n\nTake this club and get those lazy peons back on track.", objectives = "Return 3 Lazy Peons to work.", completion = "With our peons back on track the iron stores should be full in no time." }
WordHunterWoW_QuestEN[51087] = { title = "WANTED: Dark Chronicler", description = "Champion wanted for an expedition into the depths of Xibala. \n\nStrange noises and wails come from the bones at night and our workers are terrified. \n\nSeek out the source of the strange noises and destroy it, and a reward will be yours.", objectives = "Slay Dark Chronicler", progress = "Something stirs in the ruins. I hope you can discover its source!", completion = "A spirit? How terrible!" }
WordHunterWoW_QuestEN[51088] = { title = "Heart of Darkness", description = "We sent troops with Captain Conrad ahead to Nazmir to gain a foothold in that hellish jungle.\n\nThe reports we've been receiving of the local troll population are... disconcerting.\n\nThey're in over their heads, {name}. I have Brann Bronzebeard prepped and ready to head out.\n\nAccompany Brann to Nazmir so we can secure our position. The Wind's Redemption is at your disposal.", objectives = "Accompany Brann to Fort Victory in Nazmir.", completion = "I've wrestled with death, <race>. It's the most unexcitin' contest ye can imagine." }
WordHunterWoW_QuestEN[51089] = { title = "WANTED: Tojek", description = "<This appears to be a list of threats in the immediate vicinity, a angry scribble grabs your attention.>\n\nA reward of gold be promised to de one dat slays da creature Tojek. You know what dey say, an eye for an eye! \n\n-Rovash", objectives = "Hunt down Tojek.", completion = "Hah! He be dead? Really? Dat be wonderful!\n\nHere be your reward, you earned it!" }
WordHunterWoW_QuestEN[51090] = { title = "Picturesque Norwington Estate", description = "", objectives = "" }
WordHunterWoW_QuestEN[51091] = { title = "WANTED: Ten'gor and Nol'ixwan", description = "To any hunters worthy of the challenge: \n\nFind and defeat the dueling giant direhorn and devilsaur, named Nol'ixwan and Ten'gor. \n\nTheir never-ending battle has disrupted travel throughout Zuldazar. \n\nGlory for any that succeed!", objectives = "Slay Nol'ixwan and Ten'gor", progress = "Do you think you are de greatest hunter in all of Zandalar?", completion = "Those two have been fighting for supremacy as long as can be remembered. They will not be bothering de jungles of Zandalar anymore." }
WordHunterWoW_QuestEN[51092] = { title = "Picturesque Boralus", description = "", objectives = "" }
WordHunterWoW_QuestEN[51095] = { title = "Ashmane", description = "", objectives = "" }
WordHunterWoW_QuestEN[51096] = { title = "Azer'tor", description = "", objectives = "" }
