WordHunterWoW_QuestEN[51100] = { title = "Jumbo Sandsnapper", description = "", objectives = "" }
WordHunterWoW_QuestEN[51101] = { title = "The Wounded King", description = "I have things under control here... for now, at any rate.\n\nIf we want to salvage this situation, Rastakhan must survive. Habutu is gone, but his other guardian, Zolani, has sent word.\n\nShe is protecting the King at a small fishing village called Zeb'ahari. Find Zolani and do what you can to ensure Rastakhan lives.\n\nBe careful, {name}.", objectives = "Meet Zolani in Zeb'ahari.", completion = "It is good dat you have come. De king is dying, and we do not have much time to change dat." }
WordHunterWoW_QuestEN[51102] = { title = "Kamid the Trapper", description = "", objectives = "" }
WordHunterWoW_QuestEN[51103] = { title = "Nez'ara", description = "", objectives = "" }
WordHunterWoW_QuestEN[51104] = { title = "Skycaller Teskris", description = "", objectives = "" }
WordHunterWoW_QuestEN[51105] = { title = "Ak'tar", description = "", objectives = "" }
WordHunterWoW_QuestEN[51106] = { title = "Songstress Nahjeen", description = "", objectives = "" }
WordHunterWoW_QuestEN[51107] = { title = "Scaleclaw Broodmother", description = "", objectives = "" }
WordHunterWoW_QuestEN[51108] = { title = "Hivemother Kraxi", description = "", objectives = "" }
WordHunterWoW_QuestEN[51109] = { title = "Scorched Earth", description = "", objectives = "" }
WordHunterWoW_QuestEN[51111] = { title = "King or Prey", description = "My loa has seen fit to question my resolve.\n\nFor my people, my pride, and my faith, we will correct dis. Return to your Horde. Ready your forces, and I will ready mine.\n\nWhen de time comes, we will strike back against de traitorous snake, Zul.", objectives = "Return to Baine in the Royal Chambers.", completion = "You have gone beyond our wildest expectations!\n\nThank you, <name>, for upholding the honor of the Horde. We must remember who we were, to realize what we may become." }
WordHunterWoW_QuestEN[51112] = { title = "Warbringer Hozzik", description = "", objectives = "" }
WordHunterWoW_QuestEN[51113] = { title = "Warlord Zothix", description = "", objectives = "" }
