WordHunterWoW_QuestEN[51120] = { title = "Stef \"Marrow\" Quin", description = "", objectives = "" }
WordHunterWoW_QuestEN[51121] = { title = "Enraged Krolusk", description = "", objectives = "" }
WordHunterWoW_QuestEN[51122] = { title = "Scorpox", description = "", objectives = "" }
WordHunterWoW_QuestEN[51123] = { title = "Sirokar", description = "", objectives = "" }
WordHunterWoW_QuestEN[51124] = { title = "Relic Hunter Hazaak", description = "", objectives = "" }
WordHunterWoW_QuestEN[51125] = { title = "Jungleweb Hunter", description = "", objectives = "" }
WordHunterWoW_QuestEN[51127] = { title = "Getting Out of Hand", description = "", objectives = "" }
WordHunterWoW_QuestEN[51129] = { title = "Dubious Offering", description = "Cannae be sure o' the wisdom o' this Captain Conrad.\n\nSendin' our own on these blood troll bats with offerin's?\n\nSomethin' about this stinks more'n an armpit after a bar fight.", objectives = "Take a bat from Fort Victory to Zalamar in Nazmir.", completion = "I wasn't built for fallin' that far! The only part o' me that doesn't hurt is me hat!" }
WordHunterWoW_QuestEN[51130] = { title = "Azerite for the Horde!", description = "", objectives = "" }
WordHunterWoW_QuestEN[51131] = { title = "Absolutely Barbaric", description = "", objectives = "" }
WordHunterWoW_QuestEN[51134] = { title = "If Bones Could Talk", description = "<These skeletons appear to be rising out of the ancient ruins that dot the land here. Their bones are covered with what looks like runes, but time has worn away all but fragments of the markings.\n\nIf you could find some of these runes intact, Lucille might be able to decipher them to find out where these skeletons come from...\n\n...and why they are no longer at rest.>", objectives = "Collect a Pristine Rune-Etched Bone from Awakened Dead in Alpine Rise.", progress = "What's this?", completion = "These markings... this is the language of the Drust!\n\nThe magic of the coven must be disturbing their spirits, drawing them back into our world to fight us once more!\n\nThis is unsettling... but it is another reason we must bring an end to the Heartsbane!" }
WordHunterWoW_QuestEN[51139] = { title = "WANTED: Tojek", description = "<The tattered paper appears to include a list of known threats in the area.\n\nThe top of the list reads: \"Tojek - Direhorn - Responsible for damages to 3 vehicles, 6 supply crates, and the tragic loss of Garrick Blacksteel's mole machine, avoid at all costs.\"\n\nPerhaps you can hunt down this creature to prevent further attacks.>", objectives = "Hunt down Tojek.", completion = "Ye got rid o' that blasted direhorn? Fantastic! Maybe some day I can get tae work on rebuilding me machine now!\n\nThank ye!" }
WordHunterWoW_QuestEN[51140] = { title = "Share the Wealth", description = "<Though old and mud covered, this is still gold, lots of it! It's not enough to be Nedly's legendary lost treasure, but it's still several thousand in gold coins.\n\nIt's a significant find, and should be returned to Shealds to be split among all the workers.>", objectives = "Take the gold to Shealds.", completion = "Some people would have just run off with this, but you didn't! We'll split this up into two hundred and fourteen shares. Here's your cut." }
WordHunterWoW_QuestEN[51142] = { title = "Pests", description = "Confound it all! These rat-faced thieves keep getting into all of our supplies! I swear, anything that's not tied down, and even some things that are, they nip off with'.\n\nYou want to make a difference for the war effort in Zandalar? Pop off as many of those buggers as you can find. \n\nOtherwise, get on with it!", objectives = "Slay 8 Thieving Snappers in the Alliance Docks.", completion = "A thief has come to steal from thieves?" }
WordHunterWoW_QuestEN[51144] = { title = "A Bundle of Furs", description = "You there! Would you happen to be passing by Hatherford?\n\nI have a delivery to make there, but my normal delivery person fell ill after a trip to Anglepoint. \n\nWould you mind taking this bundle of furs to Dandy Jones in Hatherford for me? I would go myself, but I must hold down my stall.", objectives = "Deliver the Bundle of Warm Furs to Dandy Jones in Hatherford.", progress = "Welcome to my inn, friend! How can  I help ya?", completion = "Ah, my furs! Thanks for the delivery. It's getting a bit cold out here - these will be perfect for the beds!\n\nIf you need food or a place to lay your head, I can offer you the best!" }
WordHunterWoW_QuestEN[51145] = { title = "Curse of Jani", description = "Thief and killer, know dat ya be standin' before da Patron of Scavengers, da Lord of Thieves, da God of Garbage, Master of Minions, and da Keeper of Secrets.\n\nYa be standin' before me in raiment worth entire kingdoms of gold, bearin' weapons dat cost more than even me most devout and renowned followers will ever earn.\n\nI tink now be a good time ta teach ya a lesson. Maybe show ya high and mighty greatness what it means ta be snappin' in da gutters.", objectives = "Survive the Trial of Jani.", progress = "You be bitin' that ratmon yet?", completion = "Haha! Well done, wealthy stranger. When ya out and about in dese lands, keep ya eyes open. Ya never know when one of de children might be pointin' ya ta a useful place." }
WordHunterWoW_QuestEN[51146] = { title = "Kua'fon's Day Off", description = "You know, I think Kua'fon might be lonely when you are not here.\n\nWhat makes me say that? Well, I got a very angry scroll from a Tortollan indicating he was stealing shiny things from their stalls, but that could mean anything.\n\nYou should probably stop him before he damages your reputation, hm?\n\n<Wingminder Goja cackles.>", objectives = "Stop Kua'fon from being a nuisance in the Port of Zandalar.", completion = "<Kua'fon apologetically headbutts you.>\n\nSkree." }
WordHunterWoW_QuestEN[51147] = { title = "Kua'fon's Day Off", description = "A messenger came from de Terrace of de Chosen. Your companion is at it again.\n\n<Wingminder Goja chuckles.>\n\nNot even de priests of Pa'ku seem to be able to convince him to leave. You should go and send him back home, where he belongs.", objectives = "Find Kua'fon at the Terrace of the Chosen and send him home.", completion = "<Kua'fon scrapes his rough tongue over your cheek.>\n\nSkree." }
WordHunterWoW_QuestEN[51149] = { title = "Left at the Port", description = "There was a mishap when we were loading the most recent shipment for the Southwind Station. Apparently some paperwork meant for the dockmaster was left behind.\n\nHe can't hand over deliveries to the couriers without it, but the next cargo ferry won't be departing any time soon. Do you think you could deliver it by foot? The ferry dock is just a short ride down the road.", objectives = "Deliver the package to Dockmaster Tyndall.", completion = "I was wondering where this was. Thank you kindly." }
WordHunterWoW_QuestEN[51150] = { title = "Honoring the Fallen", description = "This is a shameful situation. Unforgivable! The soldiers weren't carryin' offerrin's to the blood trolls, they WERE the offerin'!\n\nIt'd be right difficult to bury 'em proper in this hole. Best we can do is get their dog tags.\n\nPoor lads an' lassies.", objectives = "Recover 7 Dog Tags from Fort Victory soldiers.", completion = "I'll keep these tags an' get 'em to their families. Let's keep mum on the manner o' their deaths, aye? No need to cause 'em even more sadness." }
WordHunterWoW_QuestEN[51151] = { title = "A Letter to the League", description = "A researcher at the Resort up the hill was hoping to get a letter out to a group called the \"Explorers' League\". He claims that they have a camp set up near some old Drust ruins on the other side of the sound.\n\nThere's no official station so it will have to be delivered by hand. If you happen to head in that direction, can you take it with you?", objectives = "Find the Explorers' League members at the Thovas Base-Camp.\n\nProvided item:", completion = "We might have a wee problem on our hands." }
WordHunterWoW_QuestEN[51153] = { title = "Mor'fani the Exile", description = "", objectives = "" }
WordHunterWoW_QuestEN[51154] = { title = "Past Due", description = "", objectives = "" }
WordHunterWoW_QuestEN[51155] = { title = "Brgl-Lrgl the Basher", description = "", objectives = "" }
WordHunterWoW_QuestEN[51156] = { title = "Fangcaller Xorreth", description = "", objectives = "" }
WordHunterWoW_QuestEN[51157] = { title = "Golanar", description = "", objectives = "" }
WordHunterWoW_QuestEN[51159] = { title = "Bring out the Big Gun", description = "<The cannon here is still in good condition. It's a lot of firepower to slow down the Horde.\n\nTaking this to Lea Martinel at Eckhart Lodge would really help their defenses.>", objectives = "Cannon delivered.", completion = "This is an unexpected surprise!" }
WordHunterWoW_QuestEN[51161] = { title = "WANTED: Za'roco", description = "To any with honor and a sharp blade: \n\nFind and kill the thief, Za'roco. \n\nThose that betray their fellow exile don't deserve to live. \n\nAny who can cross his name off this list will earn a fitting reward.", objectives = "Find and kill Za'roco the Grifter.", completion = "Za'roco got what he deserved, and now, so will you." }
WordHunterWoW_QuestEN[51162] = { title = "WANTED: Taz'raka the Traitor", description = "To all caravans and travelers:\n\nBeware Taz'raka the Traitor, a skeleton ambushing travelers on the road near Port of Zem'lan. If you must travel on that road, move quickly, and avoid entering any of the ruins.\n\nSeveral caravans have combined resources to offer a reward for Taz'raka's death.\n\nTo collect, speak with Norah in Camp Lastwind.", objectives = "Find and kill Taz'raka the Traitor.", progress = "Be careful out there, <name>.", completion = "A bounty worth paying. Thank you, <name>." }
WordHunterWoW_QuestEN[51164] = { title = "WANTED: Cobra Excursion Participants", description = "Attention guests of the Goldtusk Inn:\n\nWe're proud to announce a surprise new addition to our lineup of excursion activities!\n\nThe new Giant Deadly Unstoppable Killer Cobra Experience is now available!\n\nThere's no need to sign up, you've all been automatically volunteered for this activity.\n\nTo participate, simply travel into the dunes north of the inn and try not to be killed by the massive cobra now patrolling the area.\n\nWe are not currently offering guided tours for this activity. Have fun!", objectives = "Kill Sevriss.", progress = "All of our excursion survivors receive a reward!", completion = "You killed de giant snake? Congratulations!\n\nGuess I'd better update the brochure excursion list." }
WordHunterWoW_QuestEN[51165] = { title = "WANTED: Sandscout Vesarik", description = "To any and all who wish to see the Faithless empire fall: \n\nSandscout Vesarik was spotted patrolling the dunes to the east. Gather a formidable force and strike him down!\n\nThose who succeed will be granted a fitting reward.", objectives = "Find and kill Sandscout Vesarik.", progress = "Sandscout Vesarik was last seen patrolling the dunes to the east.", completion = "Vesarik's death will be a devastating blow to the Faithless forces." }
WordHunterWoW_QuestEN[51166] = { title = "Down to the Roots", description = "", objectives = "" }
WordHunterWoW_QuestEN[51167] = { title = "Blood of Hir'eek", description = "Spooky chantin' in the next room can only mean one thing: someone's askin' for the ol' what-fer!\n\nI'd give ya a hand but I gotta drink a couple-a potions before I'm back on me feet.\n\nTake out that blood witch and I bet the magic'll dissipate.", objectives = "Defeat Blood Witch Pakkala.", progress = "Two things I can't abide in this world: witches an' tall chairs.", completion = "Always thought witches dinnae wear clothes when ritualisin'. And where was 'er broomstick?" }
WordHunterWoW_QuestEN[51168] = { title = "Zealots of Zalamar", description = "We're surrounded by the enemy, {name}, and it's got me blood ragin'!\n\nI'm fit as a fi... instrument... and ready to help get us outta this forsaken cavern.\n\nLet's show 'em the end o' their miserable lives, eh?", objectives = "Slay 10 Zalamar Zealots in The Fall.", progress = "Smells like... Victory.", completion = "Worst places in the world are all dark holes with no artifacts about!" }
WordHunterWoW_QuestEN[51169] = { title = "Flight from the Fall", description = "Let's get outta this hole! Hairs on the back o' me neck won't settle down. Was hopin' I'd find some artifacts, or treasures, or haggis, or at least a few worthwhile trinkets down here.\n\nThose bats look like the ones that we came on... hopefully they'll take us back to Fort Victory and not some rotten grotto with no valuables inside.", objectives = "Take a bat to Fort Victory.", completion = "Fort Victory's got the wrong name. Somethin' like Fort Folly seems more appropriate ta me." }
WordHunterWoW_QuestEN[51170] = { title = "Ooh Rah!", description = "We're going to need a harbor for our base of operations. Those ruins across the way should be perfect for our needs.\n\nUnfortunately, it looks to be occupied by a hostile force so I'm sending the marines to secure the shore. As the most experienced soldier here I want you to go with them. \n\nI don't want to see a single hostile remain when our engineers arrive.\n\nNow, go take that harbor in the name of the Alliance!", objectives = "Capture Shatterstone Harbor.", completion = "Thank the Light you came with us! Private Leonard didn't make it and Private James got captured by those damn snake-men! \n\nThe important thing is I think the rest of 'em got scared off once you started raining death down on 'em.\n\nSmall victories, right?" }
WordHunterWoW_QuestEN[51172] = { title = "Forked Lightning", description = "", objectives = "" }
WordHunterWoW_QuestEN[51173] = { title = "Sandfishing", description = "", objectives = "" }
WordHunterWoW_QuestEN[51174] = { title = "Instructions Not Included", description = "", objectives = "" }
WordHunterWoW_QuestEN[51175] = { title = "Azerite Wounds", description = "", objectives = "" }
WordHunterWoW_QuestEN[51176] = { title = "Unaccounted For", description = "", objectives = "" }
WordHunterWoW_QuestEN[51177] = { title = "Lessons of the Damned", description = "When I arrived here in disguise, the blood trolls thought me some sort of messenger of their Blood God.\n\nI seized the advantage and played into their primitive beliefs.\n\nI came here intending to open trade and learn how we can work with them against the Horde.\n\nWhat I discovered was altogether more compelling. I will show you.", objectives = "Learn of Captain Conrad's progress.", completion = "Dreadful business, <name>. I was set on a rescue or corpse recovery. To see one o' our own that far gone was... unsettlin'.\n\nWhat's done is done. I'll send a report back to Halford. Don't bother yerself with the busy work this time." }
WordHunterWoW_QuestEN[51178] = { title = "Hundred Troll Holdout", description = "", objectives = "" }
WordHunterWoW_QuestEN[51179] = { title = "Azerite Madness", description = "", objectives = "" }
WordHunterWoW_QuestEN[51180] = { title = "Instructions Not Included", description = "", objectives = "" }
WordHunterWoW_QuestEN[51181] = { title = "Instructions Not Included", description = "", objectives = "" }
WordHunterWoW_QuestEN[51185] = { title = "Azerite Empowerment", description = "", objectives = "" }
WordHunterWoW_QuestEN[51190] = { title = "Granting a Reprieve", description = "Now, on to more pressing matters.\n\nThe Forsaken have shown up and are preventing us from saving our people. All my soldiers are either injured, exhausted, or in no shape for fighting.\n\nIt seems these trollish natives have joined them as well. I am spread too thin.\n\nKill the Horde. Kill the Zandalari. Kill them all.", objectives = "Slay 8 Forsaken and 8 Zandalari in Talanji's Rebuke.", completion = "A few less cretins to worry about." }
WordHunterWoW_QuestEN[51191] = { title = "Save Them All", description = "Reinforcements? Ah thank tha Light!\n\nWe done the best we can triaging the injured, but we need help. We need more hands that can heal wounds or at the verra least apply bandages.\n\nHow are yer hands? Here, take these bandages and do what ye can tae treat tha injured.", objectives = "Heal 8 injured sailors.", progress = "We've done what we can. Now all we can do is rest.", completion = "Ye'd make an excellent medic. Or at tha verra least a good nurse." }
WordHunterWoW_QuestEN[51192] = { title = "A Lack of Surplus", description = "Food, wood, cloth... we're short on everything. Of course, I'm always short, but that donna stop me.\n\nHeh.\n\nSee what ya can salvage from tha shipwrecks.", objectives = "Collect supplies from the shipwreck.", progress = "Did ya find anything useful?", completion = "It's amazin' what we can do when we have tha supplies tae do it!" }
WordHunterWoW_QuestEN[51193] = { title = "That One's Mine", description = "Yer here to help? I donna have anything... Well, maybe I do.\n\nI know it's just a simple hammer. I know it's not special. But it's mine.\n\nThat disgustin undead, Alan Hawkins, is taunting me wi'it. I promised Feorea I wouldna run off tae fight him, but ye made no such promises.\n\nKill him and retrieve me hammer.", objectives = "Retrieve Degdod's Hammer from Alan Hawkins.", progress = "Donna judge me. This is me best hammer.", completion = "I know it doesna seem like a special hammer. But to me, it's verra important." }
WordHunterWoW_QuestEN[51198] = { title = "Fertilizer Duty", description = "", objectives = "" }
WordHunterWoW_QuestEN[51199] = { title = "The Glory of the Hunt", description = "You here for the festival, friend?\n\nWe're still settin' up here, but the hunt should've started by now!\n\nIf ya want to take part, go meet Abbey in Foxhollow Woods. She'll get you all set up.\n\nHappy huntin'!", objectives = "Meet Abbey Watkins at the edge of Foxhollow Woods.", completion = "Ah, Gora sent you! Care to join in the hunt?" }
WordHunterWoW_QuestEN[51200] = { title = "The Black Sheep", description = "I'll admit, Millie has never really been one to follow the herd. Usually, it's no problem. She'll wander off for a bit, do her own thing and eventually make her way back to the flock.\n\nThe hills have grown increasingly more dangerous lately, especially with the wolves and giants about. She's been gone awhile and I'm starting to worry.\n\nCould you please help me look for her?", objectives = "Find and rescue Millie.", completion = "Oh, my sweet Millie! Thank you, <name>. I'm in your debt." }
WordHunterWoW_QuestEN[51201] = { title = "The Troll's Tale", description = "You've arrived at an... interesting time, {class}. All of my ships have been destroyed. Half of my men are feeding the fishes, and the rest aren't doing much better. We're as good as doomed.\n\nAnd still, the Alliance prevails.\n\nThese Zandalari trolls are to blame for this carnage. I need to know how they did it before we kill them all and escape from this Light-forsaken island.", objectives = "Speak with the Captured Zandalari Troll to find out how the Alliance fleet was sunk.", progress = "<Thom sneers at the Zandalari troll kneeling before him.>\n\nTalk, you filthy brute!", completion = "Princess... Talanji, you say? I see.\n\nKing Wrynn will be told about this. This Zandalari princess will learn what it means to make an enemy of the Alliance." }
WordHunterWoW_QuestEN[51203] = { title = "Cry Wolf", description = "Lately, the wolves have been terrorizing my flock. They weren't an issue until the giants moved in and pushed them out of their normal hunting grounds.\n\nI feel bad asking you to do this, but could you thin their ranks a bit? If there are fewer wolves competing for food, maybe they'll leave us alone.", objectives = "Kill 10 Feral Razorclaws.", completion = "My flock should be able to rest easier now." }
WordHunterWoW_QuestEN[51204] = { title = "WANTED: Razorclaw Alpha", description = "Adventurers Needed!\n\nThe wolves have been attacking my flock! I don't have the means to fight them back.\n\nI've seen one, much larger than the rest, leading a few of the attacks.\n\nPlease, if anyone can help, I'll gladly offer whatever reward I can muster.\n\n- Shepherd Mary Ann Milbrooke", objectives = "Slay the Razorclaw Alpha.", completion = "Wow, I wasn't sure if anyone would ever answer my posting. Thank you!" }
WordHunterWoW_QuestEN[51205] = { title = "Aww, Rats!", description = "I didn't sign up for this! I just want to get back to the simple things, like grinding wheat and drinking mead.\n\nAs if things couldn't get any worse around here, there's an army of rats ransacking the shed and I don't have the stomach to exterminate them.\n\nHere, I got this off some crazy gnome that stopped into port recently. I thought maybe it'd help with the bees. Maybe you can try it on the rats?", objectives = "Collect 8 Bilge Rats.", completion = "Thank you so much. I'll get rid of these little guys." }
WordHunterWoW_QuestEN[51207] = { title = "Ettin It Done", description = "Okay, now here's a little something I whipped up for you with those extra ingredients.\n\nWe don't have much around here in the way of weapons, but we've got gunpowder and plenty of flour. A surprisingly explosive combination!\n\nToss one of these goodies at those nasty ettins, should disorient them long enough to give 'em a good whack upside the head!\n\nYou thought I was just a sweet old lady, baking delicious cookies for any ol' passerby? Hah, I'll have you know I was quite the firecracker in my day.", objectives = "Use Flour Bombs to slay 8 Ettins.", completion = "<name>, my grandson could learn a thing or two from you. Come back to visit anytime!" }
WordHunterWoW_QuestEN[51208] = { title = "Wheat A Minute", description = "With the storage shed ransacked by rats and the giants pillaging our shipments, we've been running low on food.\n\nWhen I was making my way out here, I saw a bunch of grain sacks littered about, near the wrecked wagons.\n\nI'd appreciate it if you could retrieve whatever you find while you're out here.", objectives = "Collect 10 Grain Sacks.", completion = "Wow! I can't believe you were able to carry all of that." }
WordHunterWoW_QuestEN[51209] = { title = "Mighty Grokkfist", description = "Grandma is always telling me I need to toughen up a little... how easy we've got it these days.\n\nI read a story about giants that are terrified of rats, so I thought, \"Hey Charles, here's a great idea, let's take all those rats {name} gathered and let 'em loose on the ettins.\"\n\nI tried to be tough for once, but look how it turned out. Now, I'm stuck out here, just hoping I don't get squashed.\n\nTheir leader is just up the hill there. Here, take the rats with you and let's hope I was right!", objectives = "Use the Pack of Rats to kill Grokkfist.", completion = "I can't believe it actually worked. I thought for sure we'd all be squished!" }
WordHunterWoW_QuestEN[51210] = { title = "Blast Back the Siege", description = "", objectives = "" }
WordHunterWoW_QuestEN[51211] = { title = "The Heart of Azeroth", description = "Our world's dyin', {name}. Sargeras's sword has cut deep. Her pain is drivin' the elements into a frenzy!\n\nI can hear Azeroth's voice, but she needs more than her speaker.\n\nShe needs her champion.\n\nFar below us lies an ancient titan vault called the Chamber of Heart. I sense she wishes tae speak tae ye there.\n\nCome with me into the chamber. It may be our only chance tae save her!", objectives = "Travel to the Chamber of Heart and commune with Azeroth.", progress = "Ye need tae hear from Azeroth herself, <name>.", completion = "The Heart of Azeroth... that's the key tae healin' her wounds!" }
WordHunterWoW_QuestEN[51212] = { title = "Waycrest Manor: Witchy Kitchen", description = "", objectives = "" }
WordHunterWoW_QuestEN[51213] = { title = "Waycrest Manor: No need to Hag-gle", description = "", objectives = "" }
WordHunterWoW_QuestEN[51214] = { title = "Be A Dear", description = "As you can plainly see by the rocks falling from the sky, we are under siege by those terrible ettins!\n\nIf you could be obliged to lend us a hand, I'd be most grateful. We can't possibly hope to defeat them unless we properly prepare you first.\n\nCould you be a dear and fetch a few things for me from around the Hamlet? Some water, a sack of flour, and a bundle of logs should help.\n\nI've already sent my grandson, Charles, off to fetch a few other items. I've not seen him for quite a while though.", objectives = "Collect a Water Bucket, Sack of Flour, and Logs, then return them to Marie Davenport.", progress = "Did you have any trouble dear?", completion = "Thank you so much. I wish Charles was half as studious as you." }
WordHunterWoW_QuestEN[51215] = { title = "Milking Goats", description = "Unfortunately, Milbrooke's flock hasn't been producing lately. What with all the wolves about, the poor things must be terrified.\n\nWild goats wander the hills, and they are quite fearless compared to the sheep. \n\nIf you can find a few with young ones about, you may be able to persuade them to offer some fresh, delicious goat milk!", objectives = "Collect 6 Mountain Goat Milk.", progress = "Were you able to collect enough milk?", completion = "It smells wonderful. This is perfect, thank you <name>!" }
WordHunterWoW_QuestEN[51216] = { title = "Waycrest Manor: Something to Crow About", description = "", objectives = "" }
WordHunterWoW_QuestEN[51217] = { title = "WANTED: Yarsel'ghun", description = "By the decree of the Storm's Wake.\n\nFind and kill the foreign spy, Yarsel'ghun. \n\nA foreigner agent hiding on our soil, she is responsible for acts of terrorism against the citizens of Stormsong.\n\nThe individual that ends her existence will earn a fitting reward.", objectives = "Find and kill Yarsel'ghun.", progress = "The wanted poster is nailed to the wall, with tasks etched on it.", completion = "One less Horde in Stormsong." }
WordHunterWoW_QuestEN[51218] = { title = "Undelivered Package", description = "< The ransacked cart has obviously seen better days. A single package remains, obscured by the spilled grain. It's addressed to Marie Davenport of Millstone Hamlet. >", objectives = "Deliver the package to Marie Davenport.", completion = "Ohhhh, goodness! You found my lost tea. Thank you dear!" }
WordHunterWoW_QuestEN[51220] = { title = "Deep Sea Venture", description = "As mighty as Ai'twen is, this Venture Company is still a threat to him. I need you to watch over Ai'twen and Toki as you continue your great adventure.  \n\nEliminate the Venture Company Seawrenches that lurk the waters you travel to.", objectives = "Eliminate 6 Seawrenches", progress = "Hurry to it, Ai'twen's saftey is important.", completion = "You've struck a mighty blow against these Venture Company thugs, and kept Ai'twen safe." }
WordHunterWoW_QuestEN[51221] = { title = "Response Required", description = "Time is short and more creatures will die without your help. The Venture Company prepares a huge digging machine to tear the reef apart and destroy this cave. They've assigned a special operative to be sure the job is done right.\n\nYou must act now, {name}. Take out the operative in charge of the camp; this should buy us some time.", objectives = "Eliminate Lithia Costcutter", completion = "You've bought us valuable time with your heroic actions." }
WordHunterWoW_QuestEN[51222] = { title = "What's Yours is Mined", description = "During a visit to Pandaria, I witnessed the citizens of Halfhill defeat attacking hozen by flinging the hozen's excrement back at them.  \n\nThe hozen were unprepared to face the wrath of their own weaponry used against them. A similar strategy can be applied here. We will gather Venture Co. Sea Mines and use them against the invaders.  \n\nYou hook ropes to each mine, and Ai'twen and I will haul them up.", objectives = "Collect 10 Sea Mines", completion = "Excellent work, <name>. Our plan is coming together nicely." }
WordHunterWoW_QuestEN[51223] = { title = "Walking on Broken Glass", description = "", objectives = "" }
WordHunterWoW_QuestEN[51224] = { title = "Profit and Reconnaissance", description = "This was supposed to be a covert operation. Unfortunately, our Trade Prince insisted on coming along... with the loudest, most conspicuous vehicle the Horde has ever conceived.\n\nAt least you're here with me, {name}.\n\nLet's get going, then. We know next to nothing about the Drustvar territory. It's time to do some recon.", objectives = "Escort Gallywix and Eitrigg on Gallywix's War Trike.\n\nIf you become separated from Gallywix and Eitrigg, you can find them at Anyport.", progress = "Let's get this over with.", completion = "I'm getting a bad feeling about these woods.\n\nWait a minute... what is THAT!?" }
WordHunterWoW_QuestEN[51225] = { title = "Albatrocity", description = "", objectives = "" }
WordHunterWoW_QuestEN[51226] = { title = "Death from Two Sides", description = "The overgrown lizards from down on the beach decided to swarm the camp suddenly. \n\nWe're used to dealing with one or two each week, but it seems like the whole brood came up the cliff. Wonder if the smell of blood drew them in.\n\nThey're putting our remaining men at risk, wipe them out!", objectives = "Kill 8 Brinefang Saurolisk.", progress = "Have you thinned out those saurolisks yet?", completion = "There's one problem dealt with." }
WordHunterWoW_QuestEN[51228] = { title = "Instant Meat, Ready to Eat", description = "", objectives = "" }
WordHunterWoW_QuestEN[51229] = { title = "Establish a Beachhead", description = "I won't allow Private Leonard's sacrifice to be in vain. Let's get our men out here and fortify this place up before those... \"sethrak\" decide to come back.\n\nHere, plant this banner somewhere visible so the ship knows its safe. That platform over next to the dock should do the trick.", objectives = "Plant the Alliance banner and establish your base in Vol'dun.", completion = "The crew's setting up our camp in record time! Good work securing the beachhead.\n\nNow, about Sergeant Ermey..." }
WordHunterWoW_QuestEN[51230] = { title = "Emergency Transplants", description = "Riverbud is a precious resource for us. Not only does it have potent magical properties, but it also feeds many of de beasts we train or eat ourselves.\n\nHowever, de Blood Trolls have been dumping a lot of cursed blood in de rivers. It may not be their goal, but if we do not act soon, de pollution may wipe out all de riverbud.\n\nI need you to take dis handful of seeds, and plant dem in de rivermud. In exchange, I will teach you how to harvest it more effectively.", objectives = "Plant 10 Riverbud Seeds in rivermud.", completion = "I cannot thank you enough. Riverbud is absolutely critical to both de Zandalari and to de wildlife. Regardless, I said I would teach you, and I am true to my word.\n\nDe riverbud you have harvested looks blown out.  When you go to pick the bulbs, do not just rip dem off of the plant.  Instead, twist dem first so they pinch de stem closed. It will keep de fluid from draining out." }
WordHunterWoW_QuestEN[51231] = { title = "Wiccaphobia", description = "Do you see that... that shape up in the brambles up ahead? Is that... <Eitrigg shudders.>\n\nIs that goblin... wrapped up in that tree?", objectives = "Investigate the shape up ahead, then protect Eitrigg and Gallywix.", progress = "Huh?", completion = "I TOLD you I've got a bad feeling about this place..." }
WordHunterWoW_QuestEN[51232] = { title = "Hundred Troll Holdout", description = "", objectives = "" }
WordHunterWoW_QuestEN[51233] = { title = "I Hope There's No Witches in the Mountains", description = "<Gallywix looks flustered after his ordeal with the crone.>\n\nYou know, ah... I think maybe we better set up our foothold somewhere else. Maybe, up in the mountains? You know, like... not here, where the witches are?", objectives = "Drive Eitrigg and Gallywix to the mountains.", progress = "Yes, <name>?", completion = "This... this I can work with." }
WordHunterWoW_QuestEN[51234] = { title = "Krazzlefrazz Outpost", description = "I already did a bunch of the leg-work for settin' up our foothold. All we gotta do is finish deploying all the instant-base technology, and we'll be good to go here in Drustvar.\n\nWhy don't you go finish the base building. I'm gonna see if I can salvage any wolfercycle parts.", objectives = "Use the goblin devices in Krazzlefrazz Outpost to build your foothold in Drustvar.", progress = "What?", completion = "There we go. That's real nice.\n\nAnd hey, look! Here come some fresh rocket troops!" }
WordHunterWoW_QuestEN[51238] = { title = "Abandoned in the Burrows", description = "", objectives = "" }
WordHunterWoW_QuestEN[51239] = { title = "Instructions Not Included", description = "", objectives = "" }
WordHunterWoW_QuestEN[51240] = { title = "WANTED: Anchorface", description = "Kill the blasted shark that ate me legs! And me crew! And me boat - even the anchor!\n\nHe's been swimming around in the sea, looking for his next meal. Kill 'im.\n\nI've left a reward with Cesi Loosecannon if you do.\n\n<The poster is signed 'Captain Slagbolt'>", objectives = "Slay Anchorface in the waters near Anyport.", progress = "Oh, did you kill that shark that almost got Ole Slaggy?", completion = "Nicely done! Here's the reward Slagbolt left. When he comes in to port next he'll be glad to see that shark gone." }
WordHunterWoW_QuestEN[51241] = { title = "The Bear Witch Project", description = "", objectives = "" }
WordHunterWoW_QuestEN[51243] = { title = "Breaking The Food Chain", description = "De extra riverbud you planted has helped, but it has not been enough.  Some of de local beasts are consuming de riverbud before dey can mature. We need dese plants to germinate, or we could risk losing it entirely.\n\nThe largest group of young riverbud consumers are de jacunda. If we are going to give de riverbud a chance to survive dis, you will need to thin their numbers.\n\nDo dat and I will teach you everything I know about riverbud.", objectives = "Kill 12 Ravenous Jacunda.", completion = "Thank you for putting de fish down. I do not regret dis action, as dey would have starved if de riverbud ran out, so at least dey had a quicker death.\n\nThe secret to riverbud is dat dere are additional bulbs in de root system. Just pull de plant by de vine firmly with steady pressure." }
WordHunterWoW_QuestEN[51244] = { title = "What Rots Beneath", description = "Good job killin' Ateena and sendin' whatever dat construct was down ta da bottom of... whatever dis ting be.\n\nMe scouts be seein' Titan Keeper Hezrel marchin' down to sometin' called da Altar of Rot.\n\nNow dat we got rid of dat construct, we can be flyin' down dere ta see what Hezrel be up to. \n\nDis be best handled by you and me. Da princess be havin' business back in da city.", objectives = "Find Titan Keeper Hezrel within the Altar of Rot.", completion = "No time to waste. Area ahead exhibits immense corruption triggered by G'huun.\n\nScanners indicate corruption caused by leak within G'huun containment structure.\n\nMust push forward to contain leak. Cannot perform function alone." }
WordHunterWoW_QuestEN[51245] = { title = "I'm a Lumberjack and I'm Okay", description = "", objectives = "" }
WordHunterWoW_QuestEN[51246] = { title = "The Wreckoning", description = "I can't believe any of them survived the wreck. We were told to prevent any survivors from gaining a foothold.\n\nThere are far more of them than expected. We need to weaken their forces.\n\nWell? What are you waiting for? An engraved invitation?", objectives = "Kill 10 Shipwrecked 7th Legion.", completion = "We have an infestation of Alliance. We've done what we can. I will need to message for reinforcements." }
WordHunterWoW_QuestEN[51247] = { title = "The Things They Carried", description = "We need to know more about these sailors before we report back.\n\nIdeally, we would invade their camp but there are too many for our small group to take on. Lucky for us, they are focused on their salvage operation over safety. See if you can find any intelligence on their leaders who are scavenging the derelicts.", objectives = "Acquire intelligence from the Alliance.", progress = "What have you found?", completion = "Intelligence isn't always gathered from the most obvious things." }
WordHunterWoW_QuestEN[51248] = { title = "Productive Pests", description = "This jungle is a whole new habitat for creatures and critters. A shame we're here to deal with Alliance driftwood.\n\nI've got an idea and I think it's genius. Two words: Poison bugs.\n\nFirst, I need some bugs. Crawling and flying ones, just to be thorough for our test.", objectives = "Gather 5 bugs", completion = "These are going to be great!" }
WordHunterWoW_QuestEN[51249] = { title = "Crabulous Feast", description = "The Forsaken didn't bring any food with them. I think they might be cannibals. At the very least, they don't need to eat!\n\nTeekay and I are going to starve out here! {name}, if you're not too busy, could you bring us something to eat?\n\nMaybe some fresh crab?", objectives = "Gather 7 lumps of crab meat from the Derelict Hexopods.", progress = "My stomach is rumbling already.", completion = "This will do nicely. Now all we need is some butter. And maybe some lemon." }
WordHunterWoW_QuestEN[51250] = { title = "Buzz Off!", description = "", objectives = "" }
WordHunterWoW_QuestEN[51251] = { title = "Basement Dwellers", description = "Ever since the untimely passing of dear, sweet Lizzie, rest her soul, the pests have multiplied like crazy!\n\nIn recent days, giant spiders have begun crawling out of the cellar underneath the southern mill. \n\nNo one has been able to go down there, for fear of being wrapped in web and eaten alive!\n\nWould you mind squashing a few arachnids and collecting any silk you find?", objectives = "Collect 8 Spider Silk from the Cellar Crawlers.", progress = "If only Lizzie were still here...", completion = "We can all rest easier now that those spiders have been squashed." }
WordHunterWoW_QuestEN[51252] = { title = "Kiro's Desert Flower", description = "", objectives = "" }
WordHunterWoW_QuestEN[51278] = { title = "Lost and Forgotten", description = "We have seen firsthand the depravity that has taken hold of my former brethren. The time has come to put an end to it.\n\nThe path ahead is no doubt packed with Lord Stormsong's cultists and their soulwrought elementals. I will absorb their souls as they fall with the Dead Ringer, as you once did.\n\nHowever, there will be no release for these fiends... not this time. We will need them to pry open the final door to the Shrine.", objectives = "Fill the Dead Ringer with souls.", progress = "This burden is ours to bear, but I am glad we do not bear it alone.", completion = "Mourn not for the fallen. We do what we must to save our people." }
WordHunterWoW_QuestEN[51279] = { title = "Nazmani Cultists", description = "The rumors o' the blood trolls from back in Boralus don't line up with the letters from Captain Conrad.\n\nOpen to trade? Willin' to work with us against the Horde? Ready to teach us their magic?\n\nHogwash.\n\nOnly time worth spendin' with these evil trolls is time killin' 'em.", objectives = "Kill 15 Nazmani trolls in Koramar.", progress = "That chantin' noise won't leave my head, draenei.", completion = "Know that feelin' when somethin's amiss and ya can't quite figure it? It's exhilaratin'!" }
WordHunterWoW_QuestEN[51280] = { title = "Offerings to G'huun", description = "Been watchin' these cultists with both good eyes.\n\nThose big glowin' jars o' theirs look important.\n\nOpened one up and it sent a shiver down me spine, but nothin' seemed worth the takin'.\n\nIf it ain't worth stealin', I guess it's worth smashin'.", objectives = "Destroy 8 Offerings to G'huun in Zul'Nazman.", completion = "Doesn't seem ta be much o' value out here in this cursed jungle. Why'd Captain Conrad think they were worth tradin' with?" }
WordHunterWoW_QuestEN[51281] = { title = "Zul'Nazman", description = "Not sure if I like this Harry fella. He's growin' on me, though. Got some wild ideas about the blood elves, but he's not all bad.\n\nWhat were we talkin' about? Ah, right.\n\nCaptain Conrad. He said the Captain went to Zul'Nazman ta commune with the blood trolls there. Seems... less than well planned.\n\nLet's go see what there is to see, shall we?", objectives = "Meet Brann Bronzebeard at Zul'Nazman in Nazmir.", completion = "I'm startin' to believe we're on a corpse run here. Can't imagine we'll find the famous Captain Conrad alive at this point." }
WordHunterWoW_QuestEN[51282] = { title = "Captain Conrad", description = "Looks like there's couple o' guards posted by this hut. If I had ta guess, Captain Conrad'll be in there.\n\nSomethin' still feels off about this place, though. Why don't ya go on ahead and I'll hang here in case things go south fast?\n\nI got yer back, {name}.", objectives = "Meet with Captain Conrad at Tul'vor in Nazmir.", completion = "I was wondering when you would come for me. I must admit that I am not as captive as you might believe. Quite to the contrary, in fact." }
WordHunterWoW_QuestEN[51283] = { title = "Voyage to the West", description = "Reconnaissance reports that the Horde has made inroads into the desert of Vol'dun.\n\nWe can't allow the Horde to continue to work there unchecked, so we're preparing an expedition to establish a beachhead.\n\n{name}, as one of our most accomplished soldiers I'd appreciate if you joined us. Your help will be essential for the success of our mission.\n\nWrap up your affairs here in the harbor and report to Grand Admiral Jes-Tereth. We will set sail when you're ready.", objectives = "Speak with Grand Admiral Jes-Tereth and travel to Vol'dun.", completion = "I hope the trip didn't make you seasick, <name>. Our mission is only just getting started." }
WordHunterWoW_QuestEN[51284] = { title = "Falcon Hunt", description = "", objectives = "" }
WordHunterWoW_QuestEN[51285] = { title = "Feeding Frenzy", description = "", objectives = "" }
WordHunterWoW_QuestEN[51286] = { title = "Stop the Evacuation", description = "This is a complete disaster. The intelligence you gathered seems to indicate that they already have footholds on this island and this is just another one.\n\nThey have a boat and we need to stall them. Here's some seaforium. Plant it on their boat and sabotage their hopes of escape. If possible, take out their Captain leading the evacuation.", objectives = "Stop the Alliance evacuation efforts.", progress = "I hope you have good news for me. For once.", completion = "Finally something goes our way. We've stopped them escaping, for now." }
WordHunterWoW_QuestEN[51287] = { title = "Tol Dagor: Sealed Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[51296] = { title = "Tol Dagor: The Overseer's Pride", description = "", objectives = "" }
WordHunterWoW_QuestEN[51297] = { title = "Tol Dagor: Shorefront Property", description = "", objectives = "" }
WordHunterWoW_QuestEN[51302] = { title = "The Underrot: Sealing G'huun's Corruption", description = "Massive leak of G'huun corruption located nearby. Substance surrounding us indicator of G'huun corruption, named underrot.\n\nInitial scans suggest a massive abomination composed of underrot is ahead, releasing more corruption into Nazmir.\n\nMust destroy Unbound Abomination, contain G'huun's corruption.\n\nFunction clear. Proceed inside.", objectives = "Enter the Underrot and defeat the Unbound Abomination.", completion = "Hezrel be dead? Dat be a shame, dat thing was useful ta have around. \n\nIt be good dat we stopped dis abomination in dere... but I be worried dat dis ain't gonna be da end.\n\nWe still gotta take down da construct dat we shot down... and hopefully find a way ta keep G'huun sealed." }
WordHunterWoW_QuestEN[51305] = { title = "Jelly Clouds", description = "", objectives = "" }
WordHunterWoW_QuestEN[51308] = { title = "Zuldazar Foothold", description = "King Wrynn passed along orders to dispatch our finest to establish a foothold in Zandalar. That means you.\n\nFortunately, we have a few choices as to where we can set up camp.\n\nStick around. I'll go over the battle plan.", objectives = "Listen to Commander Wyrmbane's battle plan, then speak with Grand Admiral Jes-Tereth to travel to Talanji's Rebuke in Zuldazar.", completion = "Backups from Kul Tiras? Perfect. I was just about to finish another execution." }
WordHunterWoW_QuestEN[51309] = { title = "Rocks of Ragnaros", description = "With me shaman still in their conveyances, a vital component o' our upcomin' ritual remains scattered among the supplies.\n\nI can only hope the Horde haven't taken 'em. They're rare an' precious...\n\nIf you see any glowin' objects out there, recover 'em. They're o' tremendous value.", objectives = "Recover 9 Firelands Slag from the beach in Xibala.", progress = "I wasn't worried about 'em bein' broken. A little fire'd never hurt those rocks.", completion = "Couple o' scorch marks here an' there, but nothin' out o' the ordinary. These'll do nicely." }
WordHunterWoW_QuestEN[51310] = { title = "Raiders of the Lost Crop", description = "I could use a hand here!\n\nSo there I was, mindin' my own business and collectin' my harvest when these big galoots show up on their wolves and start torching the town! Luckily I was delivering a sack o' grain, or they'd have caught me and run me down!\n\nI won't stand for having these orcs or their dogs chewing up my fields or my crop.\n\nWhat do you say, friend? Help a farmer run some looters off his land?", objectives = "Slay 6 Orc Raiders.", completion = "Hah, that'll teach them to come here with their pooches and steal our grain!" }
WordHunterWoW_QuestEN[51311] = { title = "Energizing Extract", description = "", objectives = "" }
WordHunterWoW_QuestEN[51312] = { title = "Aromatic Pollenator", description = "While gathering the pollen, you found a dead bug absolutely covered in pollen.  You know that this little creature is the secret to harvesting pollen easier, but the answer seems just out grasp.\n\nMaybe if you ask Declan about it, he might have an idea.", objectives = "Bring the Dead Pollen-Covered Bee to Declan Senal.\n\nProvided item:", completion = "Oh, wow.  Yeah, that little fella is certainly covered in pollen.  Actually, this gives me an idea... but you may not like it." }
WordHunterWoW_QuestEN[51313] = { title = "Learn From the Best", description = "You want to learn how these bees are so good at harvesting pollen, but if you show up, they'll start swarming you.\n\nWhat you've got is a problem that can be solved with a little alchemy.  I just so happen to have this potion that, once drunk, will turn the imbiber into a plant.\n\nHere's the deal: you go out and drink the potion, and you'll see firsthand how the bees do what they do. After the potion wears off, you tell me what happened.\n\nOh, and don't ask why I have that potion on me.", objectives = "Drink Declan's potion and allow bees to harvest your pollen.", completion = "Fascinating!  It sounds like they used their bodies to block the mouth of the flower and beat their wings to stir up the pollen.\n\nWith the pollen being trapped inside the flower, it has no where to go but to get stuck on the bee.\n\nHmm, next time you've got a siren sting, try placing your hand over most of the mouth of the flower and gently blowing into it.  That might replicate what the bees were doing." }
WordHunterWoW_QuestEN[51314] = { title = "Grain Drain", description = "We've got to salvage what we can.\n\nThis valley is the breadbasket of Kul Tiras. We feed the citizens, the militia, the army, you name it! Perhaps you've heard of our famous Kul Tiran sourdough bread? Goes great with sausages.\n\nMore importantly, those blasted Horde are getting in the way of our harvest! Lucky for us, the golems work 'round the clock to package the grain.\n\nI just need you to go out to the fields and grab as many bags as you can carry. I'll pay you for your trouble, of course.", objectives = "Collect 8 Sacks of Grain.", progress = "We need that grain!", completion = "Good harvest this year. Our people will eat well." }
WordHunterWoW_QuestEN[51315] = { title = "Wild Flutterbies", description = "", objectives = "" }
WordHunterWoW_QuestEN[51316] = { title = "Walking in a Spiderweb", description = "", objectives = "" }
WordHunterWoW_QuestEN[51317] = { title = "Grounding the Grimestone", description = "", objectives = "" }
WordHunterWoW_QuestEN[51318] = { title = "Go for the Boat", description = "", objectives = "" }
WordHunterWoW_QuestEN[51319] = { title = "The Final Ascent", description = "Beyond this gate lies Lord Stormsong... and our retribution. It seems he has sealed it tight, likely to buy himself time to finish whatever foul ritual awaits us.\n\nRelease the souls within the Dead Ringer when you are ready. I will direct them into the binding holding the gate shut.\n\nFrom there, we find Stormsong and end this once and for all.", objectives = "Open the Tempest Gate.", progress = "No matter what lies beyond that gate, we face it together.", completion = "I thought this moment would never come." }
WordHunterWoW_QuestEN[51320] = { title = "Sealed Fate", description = "Three wards ahead threaten to block our entry into the Shrine. We call them the Tidemother's Wrath, Radiance, and Pride.\n\nLegends say the wards were gifts from the sea itself. They once protected our flagships against even the fiercest storms. Ever since we settled here they have instead kept the Shrine of the Storm safe.\n\nIt seems Lord Stormsong has turned their power against us. I can feel their energy radiating out even from here, protecting his forces from our magic.\n\nWe must destroy them.", objectives = "Destroy the Tidemother's Wrath, Tidemother's Radiance, and Tidemother's Pride.", progress = "So long as the wards hold, we will be no match for Lord Stormsong's power.", completion = "I can feel the wards' power waning even now. This is our chance to strike." }
WordHunterWoW_QuestEN[51322] = { title = "Wings and Stingers", description = "", objectives = "" }
WordHunterWoW_QuestEN[51330] = { title = "Resilient Seeds", description = "", objectives = "" }
WordHunterWoW_QuestEN[51331] = { title = "Mole Machinations", description = "Seems the enemy's anticipated our moves. While we developed our refinin' techniques for Azerite, the goblins 'ave done the same.\n\nIt wasn't five minutes after we established ourselves here that the Horde arrived to disrupt our progress.\n\nWe've got several shaman of great import waitin' impatiently in the mole machines on that beach.\n\nYou can take the key and clear the way so they arrive safely.", objectives = "Free 4 Dark Iron Earthbreakers from mole machines in Xibala.", completion = "If they didn't wanna cook in a mole machine, they shoulda chose a different profession!" }
WordHunterWoW_QuestEN[51332] = { title = "A Trip Across the Ocean", description = "I understand you are to be establishing our foothold in Drustvar. You will be assisted on this mission by Trade Prince Gallywix.\n\nI know, a strange choice, but I am told that there is Azerite in Drustvar, and the Trade Prince was insistent.", objectives = "Report to Trade Prince Gallywix in Zuldazar.", completion = "Hey <name>. You ever been to Drustvar?\n\nWe're goin' to Drustvar." }
WordHunterWoW_QuestEN[51333] = { title = "Anchors Aweigh!", description = "", objectives = "" }
WordHunterWoW_QuestEN[51335] = { title = "Cookies and Cream", description = "Thank you for helping me collect everything. \n\nI couldn't let you go out there and battle those mean ettins on an empty stomach. Now, I would be no better than those terrible monsters if I did that, would I?\n\n{name}, you just feel free to take a load off while I make you a fresh batch of cookies and some warm milk!", objectives = "Enjoy Marie's fresh baked cookies and milk.", progress = "Just a moment...", completion = "What did you think <name>, hit the spot, don't they?" }
WordHunterWoW_QuestEN[51339] = { title = "Cleaning Bills", description = "The Venture Company contaminates our pristine waters with toxic oil.  \n\nMy people are strong and will endure this until the time is right to strike back. The creatures with soft skins cannot wait. We must act now and save them from this danger.\n\nCollect and scrub clean any oily sandbill pipers you see. Quickly, before it's too late!", objectives = "Clean 8 Oily Sandbill Pipers", completion = "These smallest of victories are the foundation for the Venture Companies defeat." }
WordHunterWoW_QuestEN[51340] = { title = "Drustvar Ho!", description = "Azerite's in the air, {name}. Can ya smell it?\n\nDrustvar--way over in Kul Tiras--apparently has a real big seam o' Azerite beneath it. Azerite means profit, and profit means winning this war against the Alliance... which means even more profit.\n\nWe gotta get that Azerite!\n\nCheck in with Eitrigg an' Tattersail so we can get going soon. Time is money!", objectives = "Speak with Eitrigg and Dread-Admiral Tattersail.", completion = "Here we are. Time to see what the Alliance is up to." }
WordHunterWoW_QuestEN[51341] = { title = "Daughter of the Sea", description = "They're not letting us any closer to the keep. We'll have to walk from here.\n\nReturning to Boralus has stirred feelings I thought I'd left behind. Memories smoothed away by the years like stones in the tide.\n\nIt all feels raw again.\n\nI do not know how this will end--only that we must try.", objectives = "Accompany Jaina Proudmoore to an audience with Katherine Proudmoore.", completion = "Hope you had a nice nap. You're gonna need your strength." }
WordHunterWoW_QuestEN[51342] = { title = "Battle for Stromgarde", description = "", objectives = "" }
WordHunterWoW_QuestEN[51343] = { title = "Swimming Lessons", description = "For millennia we have roamed Azeroth's depths, yet never has a land walker journeyed with us. In order to help us, you must learn to travel the waters as we do.\n\nThe three scrolls of the sea shall grant you the energies to travel and survive underwater as we do.\n\nBring me the Scrolls of Harmonious Fins, Endless Tides and Graceful Breaths.", objectives = "Collect the three scrolls.", progress = "You must collect the Scroll of Harmonious Fins, Endless Tides and Graceful Breaths.", completion = "These will do nicely.  Just as we are, you shall now be one with the sea." }
WordHunterWoW_QuestEN[51344] = { title = "To Matters at Hand", description = "Ye need te get back te Zuldazar, Princess Talanji's people are in desperate need of help.\n\nNow that ye got the heart, ye can absorb Azerite from all kinds of sources.\n\nUse the teleporter pad behind ye te return te Zuldazar. I be disablin' it when yer done... no need te have the likes of Nathanos walkin' in here.\n\nJust remember. Ye got the Heart of Azeroth around yer neck. Whatever happens... we must save the planet.", objectives = "Use the Teleport Pad to return to Zuldazar", completion = "Good, you have returned. Dere is no time to waste." }
WordHunterWoW_QuestEN[51349] = { title = "Honor Bound", description = "Sergeant Ermey is a man of honor, he would never leave one of his men behind. But one of these days that sentiment is going to get himself killed. \n\nWe don't even know what threats we face in this land. We certainly don't have the resources to spend searching for a missing private.\n\nI want you to go after him. Do whatever it takes to give up this fool's errand and return to the camp. He was last seen headed to the south-east, I'd start your search there.", objectives = "Find Sergeant Ermey in Vol'dun.", completion = "Wyrmbane sent you after me, huh? Well, he's going to have to wait.\n\nThis thing knows where Private James was taken!" }
WordHunterWoW_QuestEN[51350] = { title = "Unexpected Aid", description = "I was shadowing those sethrak when I saw this one left for dead beside the trail. I don't think he's like the others. Looks like they roughed him up pretty bad.\n\nI made contact and before he passed out he said he knew where our man was being taken!\n\nWe need to find out what this thing knows!\n\nI'll need to make a salve for these wounds. There's some cactus I saw growing around here that should make a good base for it.", objectives = "Harvest 8 Prickly Pear Roots in Bonetrail Gulch.", progress = "Got the cactus for the salve?", completion = "Those will do the trick!" }
WordHunterWoW_QuestEN[51351] = { title = "Poisoned Barbs", description = "I'm surprised this snake-man is alive, let alone able to speak. Look at this! \n\n<Ermey holds up a needle-like barb.>\n\nIt looks like it came from one of those giant insects wandering about in the bottom of the gulch. I'll bet my stripes it's poisoned.\n\nYou know what they say, that which kills can also cure.\n\nGo get a few more of these barbs. I bet if I mix it in with that cactus he's wanting we will get a good antivenom to treat his wounds.", objectives = "Collect 8 Saltspine Barbs in Bonetrail Gulch.", progress = "Got those barbs for me?", completion = "That's the stuff! Hope you didn't get stung too." }
WordHunterWoW_QuestEN[51352] = { title = "Don't Play with Matches", description = "These Venture Co. thugs set flame to the very oils they harvest. They hope to drive us from this land.\n\nTheir plan has a flaw. If a great wave extinguished every torch, their oil could not be lit. You can be our great wave!\n\nExtinguish all the flames here, and we shall be victorious this day.", objectives = "Eliminate 10 Venture Co. Flame Starters and 2 Venture Co. Oilers.", progress = "Get to work, the battle is not won yet!", completion = "The war has just begun, but it was a great first victory!" }
WordHunterWoW_QuestEN[51353] = { title = "Cave of Ai'twen", description = "Toki has researched a strategy that is historically sound. However to defeat the Venture Company, we will have to awaken Ai'twen from the bubble of tranquil waters.\n\nSeek out Loroja in the Cave of Ai'twen and we shall begin the process.", objectives = "Seek out Loroja in the Cave of Ai'twen.", completion = "Your presence here can only mean one thing.  Ai'twen's help is needed." }
WordHunterWoW_QuestEN[51354] = { title = "Anger in a Bottle", description = "These quilboar are tougher than normal and I think I found out why.\n\nThey carry vials of some sort, filled with this nasty orange liquid. They'll quaff it and gain tremendous strength and stamina.\n\nI'll bet if we get some of it Hobbs could whip up a counter-agent, or whatever it is that alchemists do. Either way, deprive them of their strength potions and it'll make getting around here easier!", objectives = "Collect 10 Foul-Smelling Samples.", progress = "Do you have the samples yet?", completion = "This stuff smells awful. Maybe Hobbs will know what to do with it. Once we get out of here I'll make sure these samples get to him." }
WordHunterWoW_QuestEN[51355] = { title = "Secretest Fish", description = "<Danielle Anglers in Mechagon may be interested in this fish.>", objectives = "Take the fish to Danielle Anglers in Mechagon.\n\nProvided item:", completion = "Where did you find this fish? It opens up many new possibilities for fish research!\n\nWith just a little adjustment, I can modify a rudimentary lure, adapting it to attract more fish than ever!\n\nOf course it might just attract more fishermen instead!" }
WordHunterWoW_QuestEN[51356] = { title = "WANTED: Sister Lilias", description = "The Waycrest Guard seeks an able-bodied soldier to eliminate a threat in Corlain.\n\nA witch by the name of Sister Lilias is wanted for the torture and killing of many of our townsfolk. Her end would prove a boon to all of Drustvar.\n\nPresent her head to claim your reward.", objectives = "Collect Sister Lilias' head from Sister Lilias in Corlain.", progress = "Inquisitor?", completion = "Ah, the witch is dead. Good.\n\nHere's your reward, as promised. Keep up the good work, Inquisitor." }
WordHunterWoW_QuestEN[51357] = { title = "Armed and Ready", description = "You must be special if the sethrak didn't kill you right away.\n \nEither that, or you'd fetch a good price at the slave market.\n\nDon't worry though. We're getting out of here.\n\nI have a wagon at the entrance, but no weapon to fight with.\n \nLuckily, it seems the sethrak have plenty.", objectives = "Choose a weapon for Nisha.", progress = "I'm good with whatever you pick, but let's hurry.", completion = "Using their own weapons against them. I like it." }
WordHunterWoW_QuestEN[51358] = { title = "WANTED: Gryphon 'Nappers", description = "A warning to all gryphon owners!\n\nDo not let your feathered companions out of your sight. We have received numerous reports about gryphons in the area being stolen in the night.\n\nIf anybody can track down and stop these thieves, a reward awaits!", objectives = "Kill Lindel the Snatcher and Silent Boris.", completion = "I heard the lost gryphon came back!\n\nI guess we've got you to thank, <name>." }
WordHunterWoW_QuestEN[51359] = { title = "Fragment of the Firelands", description = "The rumors o' yer capabilities seemed overblown, but it appears yer indeed a competent one, aren't ye?\n\nI underestimated ye, {name}. For that, I apologize. Don't tell Thaelin.\n\nThe components for the ritual are now prepared. All ye need to do is add the Firelands Slag to the Unstable Magma an' a great bein' from the Firelands will heed our call.\n\nYou'll gain control o' it and can eliminate the nearby goblin threat with nigh invincibility.", objectives = "Stabilize the Unstable Magma then use the Magma Elemental to defeat 200 Bilgewater Goblins.", progress = "Me shaman are gettin' better at this, aye? First couple o' summons and we had a hot fight on our hands.", completion = "Ah haha haaaaaaaaaaaa! Wow! I gotta admit, I'm a bit jealous I let ye take 'er out for a spin before I could. Those goblins never saw ye comin'!" }
WordHunterWoW_QuestEN[51360] = { title = "Enormous Anchor Pod", description = "In all the gathering you've done, you have never come across an anchor pod of this size. Whatever the reason that it has gotten so large, there is much that can be learned from it.\n\nYour mind wanders back to Declan, and if there is anything about it in the book you picked up earlier.", objectives = "Bring the Enormous Anchor Pod to Declan Senal.\n\nProvided item:", completion = "Oh dear... This certainly appears larger than usual. Even the book does not have anything on a giant seed pod. This could be bad..." }
WordHunterWoW_QuestEN[51361] = { title = "More Anchor Pods", description = "Everyone in Kul Tiras knows that anchor weed is a blight that was brought here by merchants.\n\nIt thrives in this weather and it leechs nutrients from other plants, so we work to keep it from spreading, but it also has a strong magical essence, keeping us from just eradicating it.\n\nHowever, if it has mutated so it can disperse more seeds, we may need to finally purge it.\n\nBring me the biggest seed pods you can find, we need to see if this is a unique case. I'll dissect this one and learn what I can.", objectives = "Harvest 9 Mature Anchor Pods from anchor weed.", progress = "If the anchor weed is mutating, we may need to purge it from this land.  Do you have the other seed pods for comparison?", completion = "These all look reasonably sized, which helps to confirm my suspicions.\n\nWhile I was dissecting the enormous pod, I found glass splinters and noticed that the interior had an alchemical smell. It sounds crazy, but I think an adventurer dropped an elixir of giant growth, shattering the vial and this plant soaked it up.\n\nThe enlarged anatomy of the giant pod let me notice that these thick walls of the seed pod are actually thin and lined with additional seeds!  You can peel the pod for more seeds!" }
WordHunterWoW_QuestEN[51364] = { title = "An Explosive Exit", description = "Alright, {name}. I think it's time we make a run for it. \n\nHopefully my wagon's still nearby.\n\nI'll steer us to our hideaway. I just need you to lob explosives onto any sethrak who are brave enough to follow us.", objectives = "Find Nisha's wagon and ride it to safety.", completion = "This is the troll you flew in with, is it not? She lives, for now." }
WordHunterWoW_QuestEN[51365] = { title = "Cultural Significance", description = "I've noticed your skill with harvesting plants has improved, but I also noticed that you just treat each flower and leaf as a commodity.  The flora of these islands have a rich history, with a deep cultural significance to us.\n\nTake this sea stalk, go around town, and ask some of the men and women what it means to them.  Humor me, and I'll make it worth your while.", objectives = "Learn the importance of sea stalks from people in Boralus.", completion = "Sea stalk has a unique magical property that allows the stalk to provide the flower water, even if the flower is cut off. \n\nSailors will give their loved ones a flower and keep the stalk on themselves, so if they fall over board, the salt water kills the flower. What you hold is more than a stick, it's a family member's life.\n\nAs for your lesson, unlike most other magic plants, the best material to harvest for magical essence is the stem, not the leaves or flower." }
WordHunterWoW_QuestEN[51366] = { title = "Antidote Application", description = "The antidote's ready. \n\nIt smells like death and tastes worse, but it should be potent enough. Let's hope that we're not too late for it to do any good.\n\nHere, administer the salve to his wounds. It should work nearly instantly.", objectives = "Administer the Antivenom to Vorrik.", completion = "I can feel life returning to my limbs. Thank you, stranger!\n\nI'm afraid we don't have the time for more of an introduction. Your friend is held captive by the Faithless.\n\nDon't worry, my people will be happy to aid you in return for your kindness to me." }
WordHunterWoW_QuestEN[51367] = { title = "WANTED: Raging Earthguard", description = "Be careful when traveling toward Anglepoint!\n\nAn immense creature of the earth has spawned on one of the hills, threatening all who go near.\n\nAny adventurers who take down this earthen guardian shall be rewarded greatly.", objectives = "Kill the Raging Earthguard west of Norwington Estate.", completion = "You defeated the revenant! Bully! Well done as always, my friend!" }
WordHunterWoW_QuestEN[51368] = { title = "WANTED: The Hornet", description = "That's it, I'm putting a bounty on that blasted hornet.\n\nEvery time I try to do some good old fashioned bare-handed fishing, that son of a bear comes after me.\n\nSomebody take that bug down!", objectives = "Kill The Hornet.", completion = "The hornet's dead! Good on ya, house cat.\n\nI'd like to not die to a bug." }
WordHunterWoW_QuestEN[51369] = { title = "Friends in Strange Places", description = "I saw a creature like your friend here. We both were being held captive by my ruthless kin, the Faithless.\n\nBefore I was cast aside I gave him something to protect, something most precious. Naturally, I would also like to see your friend's safe return.\n\nMy people will lend you their aid.  Come, I will call for my pterrordax to take us. Together we shall find where your soldier friend was taken.", objectives = "Fly to the Sanctuary of the Devoted.", completion = "Oh no! The Faithless are attacking the temple!" }
WordHunterWoW_QuestEN[51370] = { title = "Short-Supply Reward", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[51371] = { title = "Flavorable Offering", description = "Ai'twen saved many Tortollans during the great purge of the Inky Grotto. He rests here in this tranquil bubble as a reward for his service.  To entice him back to our world we'll need a flavorful offering.\n\nThe seaweed that grows outside is Ai'twen's favorite meal. Its salty flavor will surely coax Ai'twen to leave the bubble for our world. Gather it from the creatures outside this cave, and where it grows wild on the reef.", objectives = "Gather 50 Seaweed.", progress = "Search for the Seaweed outside and on Makrura Brineshells", completion = "An excellent offering.  Let us watch now, and see if this will suffice." }
WordHunterWoW_QuestEN[51373] = { title = "Ears Everywhere", description = "", objectives = "" }
WordHunterWoW_QuestEN[51374] = { title = "Unending Gorilla Warfare", description = "", objectives = "" }
WordHunterWoW_QuestEN[51376] = { title = "Can't Teach on an Empty Stomach", description = "I would love to teach you, but it's so hard for me to concentrate right now.  I haven't eaten anything all day, so it's all I can think about.\n\nHowever, if a helpful adventurer were to fish up some lane snapper from the ocean just behind me, I would owe them a something in return.  Perhaps something valuable, such as advice in regards to effectively picking the notorious winter's kiss.\n\nIf you don't feel like fishing, you could just buy some on the auction house, I don't mind.", objectives = "Collect 7 Lane Snapper for Xun Xun Sweetflower. Lane Snapper can be fished from the ocean or purchased from the Auction House.", progress = "Oh, do you have something for me?", completion = "You brought me fresh fish? What a wonderful surprise! Now I can focus on teaching an eager pupil.\n\nThe important thing to know when trying to pick winter's kiss is that any exposure to heat before it is harvested can cause the flower to wilt.\n\nTo prevent that from happening, bury your hands in the snow right before you harvest it. By reducing the temperature of your hands before touching the plant, you can usually get a couple extra petals without issue.\n\nGood luck!" }
WordHunterWoW_QuestEN[51377] = { title = "Temple of Sethraliss: Ecological Research", description = "", objectives = "" }
WordHunterWoW_QuestEN[51378] = { title = "Temple of Sethraliss: A Bazaar Menagerie", description = "", objectives = "" }
WordHunterWoW_QuestEN[51379] = { title = "Temple of Sethraliss: Navigating Currents", description = "", objectives = "" }
WordHunterWoW_QuestEN[51380] = { title = "Back to Franklin", description = "Oh, good! You are still here!\n\nI heard you had built a rapport with Franklin. I'd be lying if I said talking about him didn't make me reminisce when we worked together.\n\nIf you're not busy, could you go talk to him? Ask him if he can show you anything else. I'm sure he remembers more, if you're still looking for more information.\n\nAnd tell him that if he were to get his life sorted out, I'd like to talk to him about working together again.", objectives = "Speak with Franklin The Drunk.", completion = "Myra sent you?\n\nWait... my old business partner?" }
WordHunterWoW_QuestEN[51384] = { title = "WANTED: Quartermaster Ssylis", description = "Don't venture too far into the bay if you're not looking for a fight!\n\nA couple of Bilge Rats have taken up residence in a nearby cave, and they won't stand down from any challenge.\n\nThey ain't harming anybody, 'long as you stay away. But if somebody wants to go take care of their leader, they will be rewarded.", objectives = "Kill Quartermaster Ssylis in Krakenbane Cove.", progress = "<Alby nods at you.>", completion = "Aye, you got the saurok.\n\nBilge Rats should be out of here soon enough." }
WordHunterWoW_QuestEN[51385] = { title = "A Supply of Stingers", description = "", objectives = "" }
WordHunterWoW_QuestEN[51386] = { title = "Battle Victorious", description = "We have everything necessary to strike a blow against this Venture Company. \n\nOur plan is sound, we are well prepared and we have the element of surprise.\n\nWe shall ride atop Ai'twen and reign chaos upon them with their very own weapons.", objectives = "Ride Ai'twen and destroy the Venture Companies forces", progress = "The Venture Companies defeat is at hand.  Let's get to it!", completion = "This victory will be discussed for millennium to come.  The Venture Co. is a resilient foe though, I am sure we will meet them again!" }
WordHunterWoW_QuestEN[51388] = { title = "Stopping the Infestation", description = "", objectives = "" }
WordHunterWoW_QuestEN[51389] = { title = "Breaking Free", description = "Look, these guys are in a tough spot but let's not lose track of the mission. We've got to rescue Private James!\n\nI saw a bunch of cages down in the camp of those snakes that are besieging the temple. If James is going to be anywhere, then it'll be there!", objectives = "Find Private James and free him from his captors.", completion = "I can't believe you and the sarge went to such effort to rescue me! I'm... I'm speechless... thank you!" }
WordHunterWoW_QuestEN[51390] = { title = "WANTED: The Crimson Cutthroats", description = "For numerous and sinister crimes against the Lord Admiral: smuggling, forgery, sailing under false colors, looting, poaching, brigandage, sacking, pillaging, vandalism, impersonating Kul Tiran Naval officers, arson, kidnapping, torture, piracy, perjury, theft and ransacking multiple mead shipments.\n\nA reward is placed on the heads of The Crimson Cutthroats to be paid in full upon proof of their demise.", objectives = "Slay the Crimson Cutthroats near Falconhurst.", completion = "You finally got those damnable outlaws? Well done! My people have enough trouble here without having to deal with brigands. \n\nTake your reward with my thanks." }
WordHunterWoW_QuestEN[51391] = { title = "Defang the Faithless", description = "Did you see them as we flew in? The Faithless are sieging the temple! \n\nFriend, I know we just met but I must ask for your aid once more. Please, help us break their ranks!", objectives = "Kill 12 Faithless attackers within the Temple Grounds.", completion = "I've already heard how you sent the Faithless running! \n\nOn behalf of my people, thank you." }
WordHunterWoW_QuestEN[51394] = { title = "Break the Siege", description = "This isn't the first time the Faithless have attacked us, nor will it be the last, but the temple must be protected!\n\nPlease, do whatever you can to destroy their siege equipment and push them back.", objectives = "Disrupt the Faithless assault on the Sanctuary of the Devoted.", completion = "The Faithless will never stop their siege, but your efforts have bought us time." }
WordHunterWoW_QuestEN[51395] = { title = "The Keepers' Keys", description = "It's good to see that your companion is back unharmed.\n\nBut more importantly, let's see if he still has my stone hidden in his pockets.", objectives = "Speak to Private James and uncover the significance of Vorrik's Stone.", completion = "The Faithless will never stop their siege, but your efforts have bought us time." }
WordHunterWoW_QuestEN[51397] = { title = "Up In Your Drill", description = "<The drill on the front of the machine is in good condition.>\n\n<This seems like the perfect type of work hazard.>Upon completion of this quest you will gain:", objectives = "Use the Goblin Mining Machine to disrupt the excavation camp." }
WordHunterWoW_QuestEN[51398] = { title = "An Unusual Mentor", description = "Hey {name}, you look like you're ready to handle hostile territory.\n\nFar away in the desert of Vol'dun, on the continent of Zandalar, there grows a plant called akunda's bite. You couldn't pay me enough to go there myself, and there's almost no mention of them in any of the books I've read, but all is not lost.\n\nI know of an herbalist who lives there in the desert and studies that plant.  Find him, and I'm sure he'll be able to teach you a thing or two. Oh, and do be warned...\n\nHe is a bit... eccentric.", objectives = "Find Patu in Vol'dun.", completion = "You seek knowledge on akunda's bite? Marvelous plant, but surprisingly delicate given the harsh environment. Only the strongest will survive...\n\nHmmm... Yes, you'll do nicely.  If you assist me in my work, I would be willing to provide you with some insights." }
WordHunterWoW_QuestEN[51399] = { title = "Foul Harvest", description = "You have traveled far to find knowledge, but you have found me instead. I am curious though, how much further you would travel for it. I will teach you, if you do something for me first.\n\nIron sharpens iron, as they say, so too does adversity strengthen the seed.\n\nGo out and find seeds, ones that have been consumed by the wild beasts and have returned to the earth unscathed.\n\nOnly those seeds will be strong enough to survive the desert sands of Vol'dun.", objectives = "Collect 12 Digested Akunda's Bite Seeds.", progress = "Were you able to get the seeds?", completion = "Hmmm... This seems like a good harvest. There is a quiet dignity in their resilience.\n\nBut dignity is not enough. They must be more than quiet, they must quake with thunder." }
WordHunterWoW_QuestEN[51401] = { title = "Carry On", description = "Let's get to Brennadam right away. We need to find Brother Pike and get to the bottom of all of this before things get any worse.\n\nThis road should take us right into town. Brennadam's the busiest market this side of Boralus, so there should be plenty of people there who can help us find Pike.\n\nReady when you are!", objectives = "Meet Taelia in Brennadam.", completion = "Looks like more trouble." }
WordHunterWoW_QuestEN[51402] = { title = "Reporting In", description = "I can't believe what we got ourselves in the middle of here. Keystones, C'Thraxxi, there's even a snake-man civil war going on!\n\nAll I know is Wyrmbane is going to want a full report and if there's anything I hate more than inept privates getting themselves captured it's paperwork.\n\nLet's get going.", objectives = "Report to High Commander Halford Wyrmbane.", completion = "<Wyrmbane listens to your report.>\n\nThe news of this C'Thraxxi is troubling, but you did well in befriending the local population. This likely won't be the last time we'll have to depend upon them.\n\nWell done, <name>." }
WordHunterWoW_QuestEN[51403] = { title = "The Speaker's Imperative", description = "The world's soul is secure... fer now. I can hear Azeroth again, although her voice is still weak.\n\nThe elementals on the surface above have calmed down. Even using just a fraction of its power, the Heart of Azeroth brought stability tae this place.\n\nYe need tae return tae Stormwind and inform your allies of what transpired here. Remind them that no matter what happens with the Horde, our world must be saved.\n\nWe'll speak again soon, <name>. The battle fer Azeroth has only just begun.", objectives = "Return to Stormwind City.", completion = "<Wyrmbane listens to your tale.>\n\nThe Heart of Azeroth... a powerful artifact indeed.  Thank the Light you were there to aid Magni.\n\nBut I fear I bear dire news, <name>. While you were away, the Horde launched a brazen attack on Stormwind.\n\nI have a message for you from King Anduin. You must meet him at the keep at once." }
WordHunterWoW_QuestEN[51404] = { title = "What Happens Next", description = "After feeling the bite of Akunda so many times, static electricity causes your hair to stand on end as you hold in your hands an intact lightning pod. You noticed that by wrapping the lightning pod in it's own leaves, you were able to remove it without discharging it.\n\nIf you manage to develop this technique, harvesting this plant would become significantly less hazardous and provide additional material in pristine condition.", objectives = "Harvest 10 Akunda's Bite without being shocked." }
WordHunterWoW_QuestEN[51405] = { title = "Corruption in the Bay", description = "", objectives = "" }
WordHunterWoW_QuestEN[51406] = { title = "The Lord's Hunt", description = "", objectives = "" }
WordHunterWoW_QuestEN[51407] = { title = "Find Their Words", description = "This portal will get you quickly back to the outpost.\n\nWhen there, present the orders to Akru. \n\nHer knowledge is vast, she will be able to discern the truth within.", objectives = "Deliver the Orders from Nazjatar to Akru at Seekers' Outpost.", progress = "Ah. Deyon is correct. I know many things. What do you have there?", completion = "Yes... yes... I see here. Dire words indeed, young one." }
WordHunterWoW_QuestEN[51408] = { title = "Giving Back to Nature", description = "Perform one additional task, and I will give you the knowledge you seek. The seeds you have are strong, but they need time until they are ready to grow. \n\nHowever, one must always be prepared in the desert. This sapling is mature enough to live on its own, but it is frail. It needs the dry desert winds to build static so it may bite, but until it does, it is as helpless as grass.\n\nPlant it in the desert sands, near the fallen beast south of the Brine Basin, and protect it until it can defend itself.", objectives = "Plant the Akunda's Bite Sapling and defend it until it builds a static charge.", progress = "Have you planted the sapling yet? Has it taken root?", completion = "Your efforts have been instrumental in maintaining the balance in this land.\n\nNow I shall reward you with the knowledge you sought... But first, when you approach the flower, what do you do?\n\n<Patu nods as you explain your current knowledge of harvesting akunda's bite>\n\nHmmm... It seems that you do not know  the value of this plant's leaves. The bulb discharges on touch, which will kill the leaves if they are still attached. Harvest the leaves first and your yield shall be greater." }
WordHunterWoW_QuestEN[51411] = { title = "Azerite Mining", description = "", objectives = "" }
WordHunterWoW_QuestEN[51412] = { title = "Azerite Empowerment", description = "", objectives = "" }
WordHunterWoW_QuestEN[51415] = { title = "Azerite Madness", description = "", objectives = "" }
WordHunterWoW_QuestEN[51418] = { title = "Xibala", description = "{name}! How's things going over here?\n\nOh. Wow. There's Horde soldiers everywhere. And Zandalari trolls. And hardly any machines at all.\n\nWe should DEFINITELY head back to Xibala, with the dark iron dwarves. It's perfect for our foothold!", objectives = "Use the rowboat in Talanji's Rebuke to travel to Xibala.", completion = "You're <name>, the <race> <class> that Kelsey's been talkin' up? We've heard much about ye, lad." }
WordHunterWoW_QuestEN[51421] = { title = "Shiver Me Timbers", description = "It seems our resident shadow hunter has managed to seize a small pirate sloop.\n\nWe have sent him to Tiragarde Sound in a search for a foothold, and it seems that he has concocted a plan.\n\nTy'jin has requested your help, personally. Do not keep him waiting.", objectives = "Accompany Shadow Hunter Ty'jin to Tiragarde Sound.", completion = "Welcome ta Tiragarde, boss-mon. Ya ready to be parleyin'?" }
WordHunterWoW_QuestEN[51422] = { title = "Azerite Madness", description = "", objectives = "" }
WordHunterWoW_QuestEN[51425] = { title = "There's No Place Like Home", description = "So, the Arathi Highlands. Quite a sprawl, isn't it?\n\nAt some point, you may wish to return to this fair Stromgarde with haste.\n\nMight I offer a suggestion as to how...?", objectives = "Talk to Captain Roderick Brewston", completion = "Should you desire to return with haste, simply use this, yes?" }
WordHunterWoW_QuestEN[51426] = { title = "Inspection Gadget", description = "Some time ago, a good friend of mine who had a tinker shop in Boralus just stopped all correspondence. With the state of foreign affairs, I wasn't able to look for him myself until recently.\n\nIt's not just him. It seems that all of the gnomes that were living in the city just up and vanished.\n\nI've decided to start my search with these ruins, but the machines here have gone haywire. Could you go get a good magnetic reading on the place?", objectives = "Survey the Rusted Vault.", completion = "This data is astounding! It will take quite a while to go through all of it." }
WordHunterWoW_QuestEN[51427] = { title = "I Like Turtles", description = "Excellent work, {name}.\n\nPresent the offering to Ai'twen.\n\nHe will accept it and come to our aid.", objectives = "Present the offering to Ai'twen.", progress = "We are patient.  When you are ready.", completion = "An excellent offering.  Let us watch now, and see if this will suffice." }
